INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C1','math',4,2,'u4',2,'다각형 — 선분으로만 둘러싸인 도형으로, 곡선이 한 군데라도 섞이거나 열려 있으면 다각형이 아니며, 삼각형·사각형도 다각형이다',ARRAY['4수02-08']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C2','math',4,2,'u4',2,'변과 꼭짓점 세기 — 다각형의 변과 꼭짓점을 빠짐없이, 겹치지 않게 세고, 다각형의 변의 수와 꼭짓점의 수는 언제나 같다',ARRAY['4수02-08']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C3','math',4,2,'u4',3,'다각형의 이름 — 다각형은 변의 수에 따라 오각형·육각형·칠각형·팔각형…으로 부르며, 같은 이름이라도 모양과 크기는 여러 가지이다',ARRAY['4수02-08']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C4','math',4,2,'u4',4,'정다각형 — 변의 길이가 모두 같고 각의 크기가 모두 같은 다각형으로, 둘 가운데 하나만 같으면 정다각형이 아니며, 이름 앞에 「정」을 붙인다',ARRAY['4수02-08']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C5','math',4,2,'u4',4,'정다각형의 변과 각 — 정다각형은 모든 변의 길이의 합 = 한 변 × 변의 수이고, 한 각의 크기를 알면 모든 각의 크기를 안다',ARRAY['4수02-08']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C6','math',4,2,'u4',5,'대각선 — 다각형에서 서로 이웃하지 않는 두 꼭짓점을 이은 선분으로, 이웃한 꼭짓점을 이으면 변이고, 두 끝이 모두 꼭짓점이어야 한다',ARRAY['4수02-08']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C7','math',4,2,'u4',5,'대각선의 수와 사각형의 대각선 — 한 꼭짓점에서 차례로 그어 빠짐없이 세고(삼각형 0·사각형 2·오각형 5·육각형 9), 사각형의 두 대각선의 길이·만나는 모양을 견준다',ARRAY['4수02-08']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C8','math',4,2,'u4',6,'모양 만들기 — 모양 조각을 겹치지 않게, 길이가 같은 변끼리 맞대어 이어 붙이고, 어떤 조각을 몇 개 썼는지와 만든 도형의 이름을 말한다',ARRAY['4수02-08']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C9','math',4,2,'u4',7,'모양 채우기 — 주어진 모양을 조각으로 겹치지 않고 빈틈없이 채우며, 같은 모양이라도 쓰는 조각에 따라 채우는 방법과 조각 수가 달라진다',ARRAY['4수02-08']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u4-C10','math',4,2,'u4',8,'조각을 모아 다각형 만들기 — 조각을 모아 만든 도형의 이름은 쓴 조각의 수가 아니라 바깥쪽 변의 수로 정하고, 조건에 맞는 다각형을 여러 가지로 만든다',ARRAY['4수02-08']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X01','math',4,'u4',ARRAY['M4-2-u4-C1']::text[],'선분이 들어 있기만 하면 다각형이라고 생각한다 — 곡선이 한 군데 섞였거나 끝이 열려 있어도 다각형이라고 한다','선분으로만, 그리고 둘러싸였는지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X02','math',4,'u4',ARRAY['M4-2-u4-C1','M4-2-u4-C3']::text[],'뾰족한 곳(각)이 많으면 다각형이라고 생각한다 — 변이 아니라 각에 눈을 둔다','각이 아니라 변을 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X03','math',4,'u4',ARRAY['M4-2-u4-C1','M4-2-u4-C3']::text[],'삼각형·사각형은 변이 적어서 다각형이 아니라고 생각한다','삼각형·사각형도 다각형') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X04','math',4,'u4',ARRAY['M4-2-u4-C2','M4-2-u4-C3','M4-2-u4-C10']::text[],'변을 셀 때 하나를 빠뜨리거나 두 번 세어 변의 수(이름)를 하나 어긋나게 말한다','한 곳에서 시작해 표시하며 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X05','math',4,'u4',ARRAY['M4-2-u4-C3']::text[],'같은 이름의 다각형은 모양·크기가 같아야 한다고 생각한다 — 오목하거나 길쭉하면 그 이름이 아니라고 한다','이름은 변의 수로만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X06','math',4,'u4',ARRAY['M4-2-u4-C2','M4-2-u4-C3']::text[],'다각형의 꼭짓점의 수가 변의 수와 다르다고 생각한다(하나 더 많거나 적다고 한다)','변의 수 = 꼭짓점의 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X07','math',4,'u4',ARRAY['M4-2-u4-C4']::text[],'변의 길이만 모두 같으면 정다각형이라고 생각한다 — 각의 크기를 확인하지 않는다','각의 크기도 모두 같은지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X08','math',4,'u4',ARRAY['M4-2-u4-C4']::text[],'각의 크기만 모두 같으면 정다각형이라고 생각한다 — 변의 길이를 확인하지 않는다','변의 길이도 모두 같은지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X09','math',4,'u4',ARRAY['M4-2-u4-C5']::text[],'정다각형의 모든 변의 길이의 합을 구할 때 변의 수를 잘못 곱하거나 나눈다(정육각형을 4나 5로 등)','이름의 앞부분 = 변의 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X10','math',4,'u4',ARRAY['M4-2-u4-C4','M4-2-u4-C5']::text[],'정다각형은 크기가 정해져 있거나 반듯하게 놓여야 한다고 생각한다 — 크기가 다르거나 돌려 놓으면 정다각형이 아니라고 한다','크기·놓인 방향과 상관없이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X11','math',4,'u4',ARRAY['M4-2-u4-C6','M4-2-u4-C7']::text[],'이웃한 두 꼭짓점을 이은 선분(변)도 대각선이라고 생각한다','이웃하지 않는 꼭짓점끼리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X12','math',4,'u4',ARRAY['M4-2-u4-C6']::text[],'꼭짓점과 변의 가운데를 이은 선분이나 도형을 가로지르는 아무 선분도 대각선이라고 생각한다','두 끝이 모두 꼭짓점인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X13','math',4,'u4',ARRAY['M4-2-u4-C7']::text[],'대각선의 수를 셀 때 한 꼭짓점에서 그은 것만 세거나, 같은 대각선을 두 번 센다','모든 꼭짓점에서, 겹친 것은 한 번') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X14','math',4,'u4',ARRAY['M4-2-u4-C6','M4-2-u4-C7']::text[],'삼각형에도 대각선을 그을 수 있다고 생각한다','삼각형은 모든 꼭짓점이 이웃') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X15','math',4,'u4',ARRAY['M4-2-u4-C7']::text[],'사각형의 두 대각선의 성질을 섞는다 — 직사각형의 두 대각선이 수직이라고 하거나 마름모의 두 대각선이 길이가 같다고 한다','길이가 같은지·수직인지 따로 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X16','math',4,'u4',ARRAY['M4-2-u4-C8','M4-2-u4-C9']::text[],'조각을 겹치게 놓거나 빈틈을 남겨도 모양을 만들거나 채운 것이라고 생각한다','겹치지 않게, 빈틈없이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X17','math',4,'u4',ARRAY['M4-2-u4-C8','M4-2-u4-C10']::text[],'만든 도형의 이름을 쓴 조각의 수로 정하거나, 조각끼리 맞댄 안쪽 선까지 변으로 센다','바깥쪽 변만 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X18','math',4,'u4',ARRAY['M4-2-u4-C8','M4-2-u4-C9','M4-2-u4-C10']::text[],'같은 모양을 만들거나 채우는 방법은 한 가지뿐이라고 생각한다 — 조각 수가 다르면 다른 모양이라고 한다','방법은 여러 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X19','math',4,'u4',ARRAY['M4-2-u4-C8','M4-2-u4-C9']::text[],'모양 조각 사이의 크기 관계를 잘못 안다 — 사다리꼴은 정삼각형 2개, 정육각형은 정삼각형 4개라고 한다','정삼각형 몇 개로 덮이는지 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u4-X20','math',4,'u4',ARRAY['M4-2-u4-C1','M4-2-u4-C2','M4-2-u4-C3','M4-2-u4-C4','M4-2-u4-C5','M4-2-u4-C6','M4-2-u4-C7','M4-2-u4-C8','M4-2-u4-C9','M4-2-u4-C10']::text[],'묻는 말을 거꾸로 읽는다 — 아닌 것↔맞는 것, 잘못 말한↔바르게 말한','물음의 「아닌·잘못」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L02_basic#1','math',4,2,'u4','L02','g4_2_math_u4_L02_basic','lesson_basic','M4-2-u4-C1',1,'mc','auto','다각형은 어떤 도형인가요?',ARRAY['M4-2-u4-X01','M4-2-u4-X02']::text[],true,'{"seq":1,"concept":"M4-2-u4-C1","difficulty":1,"kind":"mc","stem":"다각형은 어떤 도형인가요?","options":[{"t":"선분으로만 둘러싸인 도형","correct":true},{"t":"곡선으로 둘러싸인 도형","mis":"M4-2-u4-X01"},{"t":"선분이 하나라도 있는 도형","mis":"M4-2-u4-X01"},{"t":"각이 세 개보다 많은 도형","mis":"M4-2-u4-X02"}],"explanation":["선분으로만 둘러싸인 도형을 다각형이라고 해요.","선분으로만 이루어지고, 그리고 둘러싸여 있어야 해요.","각의 수나 크기·색깔이 아니라 변(선분)을 보고 가려요."],"variant_rule":{"alt":[{"stem":"선분으로만 둘러싸인 도형을 무엇이라고 하나요?","options":[{"t":"다각형","correct":true},{"t":"정다각형","mis":"M4-2-u4-X07"},{"t":"대각선","mis":"M4-2-u4-X11"},{"t":"곡선","mis":"M4-2-u4-X01"}],"explanation":["선분으로만 둘러싸인 도형을 다각형이라고 해요.","선분으로만 이루어지고, 그리고 둘러싸여 있어야 해요.","각의 수나 크기·색깔이 아니라 변(선분)을 보고 가려요."],"asset":null},{"stem":"다각형인지 아닌지 가릴 때 무엇을 보아야 하나요?","options":[{"t":"선분으로만 둘러싸였는지","correct":true},{"t":"각이 몇 개인지","mis":"M4-2-u4-X02"},{"t":"크기가 얼마나 큰지","mis":"M4-2-u4-X05"},{"t":"색깔이 무엇인지","mis":"M4-2-u4-X05"}],"explanation":["선분으로만 둘러싸인 도형을 다각형이라고 해요.","선분으로만 이루어지고, 그리고 둘러싸여 있어야 해요.","각의 수나 크기·색깔이 아니라 변(선분)을 보고 가려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L02_basic#2','math',4,2,'u4','L02','g4_2_math_u4_L02_basic','lesson_basic','M4-2-u4-C2',1,'mc','auto','두 점을 곧게 이은 선을 무엇이라고 하나요?',ARRAY['M4-2-u4-X01','M4-2-u4-X06']::text[],true,'{"seq":2,"concept":"M4-2-u4-C2","difficulty":1,"kind":"mc","stem":"두 점을 곧게 이은 선을 무엇이라고 하나요?","options":[{"t":"선분","correct":true},{"t":"반직선","mis":"M4-2-u4-X01"},{"t":"직선","mis":"M4-2-u4-X01"},{"t":"꼭짓점","mis":"M4-2-u4-X06"}],"explanation":["선분은 두 점을 곧게 이은 선, 반직선은 한쪽으로, 직선은 양쪽으로 끝없이 늘인 선이에요.","도형을 이루는 곧은 선은 변, 두 변이 만나는 점은 꼭짓점이에요.","다각형을 이루는 것은 선분이에요."],"variant_rule":{"alt":[{"stem":"양쪽으로 끝없이 늘인 곧은 선을 무엇이라고 하나요?","options":[{"t":"직선","correct":true},{"t":"선분","mis":"M4-2-u4-X01"},{"t":"반직선","mis":"M4-2-u4-X01"},{"t":"변","mis":"M4-2-u4-X04"}],"explanation":["선분은 두 점을 곧게 이은 선, 반직선은 한쪽으로, 직선은 양쪽으로 끝없이 늘인 선이에요.","도형을 이루는 곧은 선은 변, 두 변이 만나는 점은 꼭짓점이에요.","다각형을 이루는 것은 선분이에요."],"asset":null},{"stem":"도형에서 두 변이 만나는 점을 무엇이라고 하나요?","options":[{"t":"꼭짓점","correct":true},{"t":"변","mis":"M4-2-u4-X06"},{"t":"선분","mis":"M4-2-u4-X01"},{"t":"각도","mis":"M4-2-u4-X02"}],"explanation":["선분은 두 점을 곧게 이은 선, 반직선은 한쪽으로, 직선은 양쪽으로 끝없이 늘인 선이에요.","도형을 이루는 곧은 선은 변, 두 변이 만나는 점은 꼭짓점이에요.","다각형을 이루는 것은 선분이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
