INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L02_basic#5','math',4,2,'u4','L02','g4_2_math_u4_L02_basic','lesson_basic','M4-2-u4-C1',2,'ox','auto','이 도형은 다각형이에요.',ARRAY['M4-2-u4-X07']::text[],true,'{"seq":5,"concept":"M4-2-u4-C1","difficulty":2,"kind":"ox","stem":"이 도형은 다각형이에요.","answer":"O","reason_options":[{"t":"선분으로만 둘러싸여 있어서","correct":true},{"t":"각이 모두 같지 않아 다각형이 아니라서","mis":"M4-2-u4-X07"}],"mis":"M4-2-u4-X07","explanation":["도형을 이루는 선이 모두 선분인지 봐요.","선분 5개로 빈틈없이 둘러싸여 있어요.","그래서 다각형이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,72.0],[8.0,32.0],[48.0,8.0],[88.0,32.0],[88.0,72.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 도형은 다각형이에요.","answer":"X","reason_options":[{"t":"곡선이 섞여 있어서","correct":true},{"t":"선분이 들어 있으니 다각형이라서","mis":"M4-2-u4-X01"}],"explanation":["다각형은 선분으로만, 그리고 둘러싸여 있어야 해요.","이 도형은 곡선이 섞여 있어요.","그래서 다각형이 아니에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[8.0,72.0],[8.0,40.0]],[[88.0,40.0],[88.0,72.0]],[[8.0,72.0],[88.0,72.0]]],"curve":[[[8.0,40.0],[88.0,40.0],[48.0,-19.2]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 도형은 다각형이에요.","answer":"O","reason_options":[{"t":"선분으로만 둘러싸여 있어서","correct":true},{"t":"오목하게 들어간 곳이 있어 다각형이 아니라서","mis":"M4-2-u4-X05"}],"explanation":["도형을 이루는 선이 모두 선분인지 봐요.","선분 6개로 빈틈없이 둘러싸여 있어요.","그래서 다각형이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,8.0],[40.0,8.0],[40.0,40.0],[88.0,40.0],[88.0,72.0],[8.0,72.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
