INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L02_challenge#2','math',4,2,'u4','L02','g4_2_math_u4_L02_challenge','lesson_challenge','M4-2-u4-C1',2,'ox','auto','삼각형은 변이 3개뿐이라 다각형이 아니에요.',ARRAY['M4-2-u4-X03']::text[],true,'{"seq":2,"concept":"M4-2-u4-C1","difficulty":2,"kind":"ox","stem":"삼각형은 변이 3개뿐이라 다각형이 아니에요.","answer":"X","reason_options":[{"t":"삼각형도 선분으로만 둘러싸인 도형이라서","correct":true},{"t":"변이 많아야 다각형이라서","mis":"M4-2-u4-X03"}],"mis":"M4-2-u4-X03","explanation":["다각형은 선분으로만 둘러싸인 도형이에요.","곡선이 섞이거나 열려 있으면 안 되고, 변의 수가 적어도(삼각형·사각형) 다각형이에요.","각이 아니라 변에 눈을 두고 가려요."],"variant_rule":{"alt":[{"stem":"선분으로만 그렸어도 끝이 열려 있으면 다각형이 아니에요.","answer":"O","reason_options":[{"t":"다각형은 선분으로 둘러싸여 있어야 해서","correct":true},{"t":"선분이 있기만 하면 다각형이라서","mis":"M4-2-u4-X01"}],"explanation":["다각형은 선분으로만 둘러싸인 도형이에요.","곡선이 섞이거나 열려 있으면 안 되고, 변의 수가 적어도(삼각형·사각형) 다각형이에요.","각이 아니라 변에 눈을 두고 가려요."],"asset":null},{"stem":"뾰족한 곳(각)이 많을수록 다각형이에요.","answer":"X","reason_options":[{"t":"다각형은 각이 아니라 선분으로만 둘러싸였는지로 가려서","correct":true},{"t":"다각형은 각이 많은 도형이라서","mis":"M4-2-u4-X02"}],"explanation":["다각형은 선분으로만 둘러싸인 도형이에요.","곡선이 섞이거나 열려 있으면 안 되고, 변의 수가 적어도(삼각형·사각형) 다각형이에요.","각이 아니라 변에 눈을 두고 가려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
