INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L02_challenge#4','math',4,2,'u4','L02','g4_2_math_u4_L02_challenge','lesson_challenge','M4-2-u4-C1',3,'mc','auto','아래 도형이 다각형이 아닌 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u4-X02','M4-2-u4-X05','M4-2-u4-X01']::text[],true,'{"seq":4,"concept":"M4-2-u4-C1","difficulty":3,"kind":"mc","stem":"아래 도형이 다각형이 아닌 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"선분으로 둘러싸여 있지 않고 열려 있어서","correct":true},{"t":"각이 없어서","mis":"M4-2-u4-X02"},{"t":"크기가 작아서","mis":"M4-2-u4-X05"},{"t":"곡선이 섞여 있어서","mis":"M4-2-u4-X01"}],"explanation":["다각형은 선분으로만 이루어지고, 둘러싸여 있어야 해요.","이 도형은 선분으로 둘러싸여 있지 않고 열려 있어서 두 조건을 다 갖추지 못했어요.","크기나 각의 수로 가르지 않아요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[24.0,8.0],[72.0,8.0]],[[72.0,8.0],[88.0,40.0]],[[88.0,40.0],[72.0,72.0]],[[72.0,72.0],[24.0,72.0]],[[24.0,72.0],[8.0,40.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 도형이 다각형이 아닌 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"곡선이 섞여 있어서","correct":true},{"t":"각이 없어서","mis":"M4-2-u4-X02"},{"t":"크기가 작아서","mis":"M4-2-u4-X05"},{"t":"선분으로 둘러싸여 있지 않고 열려 있어서","mis":"M4-2-u4-X01"}],"explanation":["다각형은 선분으로만 이루어지고, 둘러싸여 있어야 해요.","이 도형은 곡선이 섞여 있어서 두 조건을 다 갖추지 못했어요.","크기나 각의 수로 가르지 않아요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[8.0,60.8],[88.0,60.8]]],"curve":[[[8.0,60.8],[88.0,60.8],[48.0,-12.8]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 아래 도형이 다각형이 아닌 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"선분으로 둘러싸여 있지 않고 열려 있어서","correct":true},{"t":"각이 없어서","mis":"M4-2-u4-X02"},{"t":"크기가 작아서","mis":"M4-2-u4-X05"},{"t":"곡선이 섞여 있어서","mis":"M4-2-u4-X01"}],"explanation":["다각형은 선분으로만 이루어지고, 둘러싸여 있어야 해요.","이 도형은 선분으로 둘러싸여 있지 않고 열려 있어서 두 조건을 다 갖추지 못했어요.","크기나 각의 수로 가르지 않아요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[8.0,72.0],[48.0,8.0]],[[48.0,8.0],[88.0,72.0]],[[88.0,72.0],[22.4,72.0]]]}],"tag":false