INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L02_challenge#5','math',4,2,'u4','L02','g4_2_math_u4_L02_challenge','lesson_challenge','M4-2-u4-C1',3,'error','auto','다각형에 대해 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u4-X01','M4-2-u4-X20']::text[],true,'{"seq":5,"concept":"M4-2-u4-C1","difficulty":3,"kind":"error","stem":"다각형에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「끝이 조금 벌어져 있어도 선분으로만 그렸으니 다각형이야.」","correct":true,"mis_target":"M4-2-u4-X01"},{"t":"시우 — 「곡선이 섞이면 다각형이 아니야.」","mis":"M4-2-u4-X20"},{"t":"은우 — 「다각형은 선분으로만 둘러싸인 도형이야.」","mis":"M4-2-u4-X20"},{"t":"하랑 — 「사각형도 다각형이야.」","mis":"M4-2-u4-X20"}],"explanation":["다각형은 선분으로만 둘러싸인 도형이에요.","서윤의 말은 다각형의 뜻과 맞지 않아요.","열려 있거나 곡선이 섞이면 다각형이 아니고, 삼각형·사각형도 다각형이에요."],"variant_rule":{"alt":[{"stem":"다각형에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「삼각형은 변이 적어서 다각형이 아니야.」","correct":true,"mis_target":"M4-2-u4-X03"},{"t":"은우 — 「다각형은 선분으로만 둘러싸인 도형이야.」","mis":"M4-2-u4-X20"},{"t":"하랑 — 「사각형도 다각형이야.」","mis":"M4-2-u4-X20"},{"t":"지아 — 「다각형인지는 변을 보고 가려.」","mis":"M4-2-u4-X20"}],"explanation":["다각형은 선분으로만 둘러싸인 도형이에요.","시우의 말은 다각형의 뜻과 맞지 않아요.","열려 있거나 곡선이 섞이면 다각형이 아니고, 삼각형·사각형도 다각형이에요."],"asset":null},{"stem":"다각형에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「뾰족한 꼭짓점이 많으면 다각형이야.」","correct":true,"mis_target":"M4-2-u4-X02"},{"t":"하랑 — 「사각형도 다각형이야.」","mis":"M4-2-u4-X20"},{"t":"지아 — 「다각형인지는 변을 보고 가려.」","mis":"M4-2-u4-X20"},{"t":"준서 — 「곡선이 섞이면 다각형이 아니야.」","mis":"M4-2-u4-X20"}],"explanation":["다각형은 선분으로만 둘러싸인 도형이에요.","은우의 말은 다각형의 뜻과 맞지 않아요.","열려 있거나 곡선이 섞이면 다각형이 아니고, 삼각형·사각형도 다각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L02_challenge#6','math',4,2,'u4','L02','g4_2_math_u4_L02_challenge','lesson_challenge','M4-2-u4-C2',3,'sa','auto','두 다각형 ㉮와 ㉯의 변은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u4-C2","difficulty":3,"kind":"sa","stem":"두 다각형 ㉮와 ㉯의 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["㉮의 변을 세면 5개예요.","㉯의 변을 세면 7개예요.","모두 5 + 7 = 12개예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,8.0],[88.0,8.0],[88.0,72.0],[48.0,40.0],[8.0,72.0]]]},{"w":96,"h":80,"poly":[[[8.0,8.0],[88.0,8.0],[88.0,72.0],[64.0,72.0],[64.0,40.0],[32.0,40.0],[8.0,72.0]]]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 두 다각형 ㉮와 ㉯의 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["㉮의 변을 세면 6개예요.","㉯의 변을 세면 8개예요.","모두 6 + 8 = 14개예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,72.0],[8.0,8.0],[32.0,32.0],[56.0,8.0],[88.0,40.0],[88.0,72.0]]]},{"w":96,"h":80,"poly":[[[32.0,8.0],[64.0,8.0],[88.0,32.0],[88.0,48.0],[64.0,72.0],[32.0,72.0],[8.0,48.0],[8.0,32.0]]]}]}},{"stem":"이번에는 다른 그림이에요. 두 다각형 ㉮와 ㉯의 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["㉮의 변을 세면 7개예요.","㉯의 변을 세면 5개예요.","모두 7 + 5 = 12개예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,8.0],[88.0,8.0],[88.0,72.0],[64.0,72.0],[64.0,40.0],[32.0,40.0],[8.0,72.0]]]},{"w":96,"h":80,"poly":[[[8.0,8.0],[88.0,8.0],[88.0,72.0],[48.0,40.0],[8.0,72.0]]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L02_challenge#7','math',4,2,'u4','L02','g4_2_math_u4_L02_challenge','lesson_challenge','M4-2-u4-C1',3,'ox','auto','이 도형은 다각형이에요.',ARRAY['M4-2-u4-X01']::text[],true,'{"seq":7,"concept":"M4-2-u4-C1","difficulty":3,"kind":"ox","stem":"이 도형은 다각형이에요.","answer":"X","reason_options":[{"t":"선분으로 둘러싸여 있지 않고 열려 있어서","correct":true},{"t":"선분이 들어 있으니 다각형이라서","mis":"M4-2-u4-X01"}],"mis":"M4-2-u4-X01","explanation":["다각형은 선분으로만, 그리고 둘러싸여 있어야 해요.","이 도형은 선분으로 둘러싸여 있지 않고 열려 있어요.","그래서 다각형이 아니에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[25.6,72.0],[8.0,72.0]],[[8.0,72.0],[8.0,32.0]],[[8.0,32.0],[48.0,8.0]],[[48.0,8.0],[88.0,32.0]],[[88.0,32.0],[88.0,72.0]],[[88.0,72.0],[54.4,72.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 이 도형은 다각형이에요.","answer":"O","reason_options":[{"t":"선분으로만 둘러싸여 있어서","correct":true},{"t":"변이 3개뿐이라 다각형이 아니라서","mis":"M4-2-u4-X03"}],"explanation":["도형을 이루는 선이 모두 선분인지 봐요.","선분 3개로 빈틈없이 둘러싸여 있어요.","그래서 다각형이에요 — 삼각형도 다각형이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,8.0],[8.0,72.0],[80.0,72.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 이 도형은 다각형이에요.","answer":"X","reason_options":[{"t":"곡선이 섞여 있어서","correct":true},{"t":"선분이 들어 있으니 다각형이라서","mis":"M4-2-u4-X01"}],"explanation":["다각형은 선분으로만, 그리고 둘러싸여 있어야 해요.","이 도형은 곡선이 섞여 있어요.","그래서 다각형이 아니에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[8.0,60.8],[88.0,60.8]]],"curve":[[[8.0,60.8],[88.0,60.8],[48.0,-12.8]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L02_challenge#8','math',4,2,'u4','L02','g4_2_math_u4_L02_challenge','lesson_challenge','M4-2-u4-C2',4,'sa','auto','직사각형 모양 종이의 귀퉁이 1군데를 점선을 따라 곧게 잘라 냈어요. 남은 도형의 변은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u4-C2","difficulty":4,"kind":"sa","stem":"직사각형 모양 종이의 귀퉁이 1군데를 점선을 따라 곧게 잘라 냈어요. 남은 도형의 변은 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["귀퉁이 한 곳을 자르면 꼭짓점 하나가 없어지고 새 꼭짓점 2개가 생겨요.","그래서 한 번 자를 때마다 변이 1개씩 늘어요.","4 + 1 = 5개예요."],"asset":{"type":"geo","items":[{"w":144,"h":96,"poly":[[[8.0,40.0],[40.0,8.0],[136.0,8.0],[136.0,88.0],[8.0,88.0]]],"dash":[[[8.0,40.0],[8.0,8.0]],[[8.0,8.0],[40.0,8.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직사각형 모양 종이의 귀퉁이 2군데를 점선을 따라 곧게 잘라 냈어요. 남은 도형의 변은 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["귀퉁이 한 곳을 자르면 꼭짓점 하나가 없어지고 새 꼭짓점 2개가 생겨요.","그래서 한 번 자를 때마다 변이 1개씩 늘어요.","4 + 2 = 6개예요."],"asset":{"type":"geo","items":[{"w":144,"h":96,"poly":[[[8.0,8.0],[104.0,8.0],[136.0,40.0],[136.0,56.0],[104.0,88.0],[8.0,88.0]]],"dash":[[[104.0,8.0],[136.0,8.0]],[[136.0,56.0],[136.0,88.0]],[[136.0,8.0],[136.0,40.0]],[[136.0,88.0],[104.0,88.0]]]}],"tag":false}},{"stem":"직사각형 모양 종이의 귀퉁이 3군데를 점선을 따라 곧게 잘라 냈어요. 남은 도형의 변은 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["귀퉁이 한 곳을 자르면 꼭짓점 하나가 없어지고 새 꼭짓점 2개가 생겨요.","그래서 한 번 자를 때마다 변이 1개씩 늘어요.","4 + 3 = 7개예요."],"asset":{"type":"geo","items":[{"w":144,"h":96,"poly":[[[8.0,40.0],[40.0,8.0],[136.0,8.0],[136.0,56.0],[104.0,88.0],[40.0,88.0],[8.0,56.0]]],"dash":[[[8.0,40.0],[8.0,8.0]],[[136.0,56.0],[136.0,88.0]],[[40.0,88.0],[8.0,88.0]],[[8.0,8.0],[40.0,8.0]],[[136.0,88.0],[104.0,88.0]],[[8.0,88.0],[8.0,56.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L02_challenge#9','math',4,2,'u4','L02','g4_2_math_u4_L02_challenge','lesson_challenge','M4-2-u4-C2',4,'sa','auto','길이가 같은 막대 12개를 모두 써서 다각형을 하나 만들었어요. 한 변을 막대 2개를 곧게 이어 만들었다면 이 다각형의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u4-C2","difficulty":4,"kind":"sa","stem":"길이가 같은 막대 12개를 모두 써서 다각형을 하나 만들었어요. 한 변을 막대 2개를 곧게 이어 만들었다면 이 다각형의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 변에 막대 2개가 들어가요.","변의 수는 12 ÷ 2 = 6개예요.","꼭짓점의 수는 변의 수와 같아 6개예요."],"variant_rule":{"alt":[{"stem":"길이가 같은 막대 12개를 모두 써서 다각형을 하나 만들었어요. 한 변을 막대 3개를 곧게 이어 만들었다면 이 다각형의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 변에 막대 3개가 들어가요.","변의 수는 12 ÷ 3 = 4개예요.","꼭짓점의 수는 변의 수와 같아 4개예요."],"asset":null},{"stem":"길이가 같은 막대 15개를 모두 써서 다각형을 하나 만들었어요. 한 변을 막대 3개를 곧게 이어 만들었다면 이 다각형의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 변에 막대 3개가 들어가요.","변의 수는 15 ÷ 3 = 5개예요.","꼭짓점의 수는 변의 수와 같아 5개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L02_challenge#10','math',4,2,'u4','L02','g4_2_math_u4_L02_challenge','lesson_challenge','M4-2-u4-C1',4,'essay','teacher','둥근 문 모양 도형과 끝이 열린 집 모양 도형이 각각 다각형이 아닌 까닭을 쓰고, 다각형인지 가릴 때 무엇을 보아야 하는지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u4-C1","difficulty":4,"kind":"essay","stem":"둥근 문 모양 도형과 끝이 열린 집 모양 도형이 각각 다각형이 아닌 까닭을 쓰고, 다각형인지 가릴 때 무엇을 보아야 하는지 써 보세요.","answer_guide":{"answer":"예: 둥근 문 모양은 곡선이 섞여 있어서 다각형이 아니다. 끝이 열린 집 모양은 선분으로만 그렸지만 둘러싸여 있지 않고 열려 있어서 다각형이 아니다. 다각형인지 가릴 때는 각의 수가 아니라 선분으로만, 빈틈없이 둘러싸였는지를 보아야 한다.","scoring_points":["둥근 문 모양은 곡선이 섞여서라고 썼는가","열린 집 모양은 둘러싸여 있지 않아서라고 썼는가","선분으로만 둘러싸였는지를 본다고 썼는가"]},"explanation":["곡선이 섞이면 다각형이 아니에요.","선분으로만 그렸어도 열려 있으면 다각형이 아니에요.","「선분으로만」과 「둘러싸임」 두 가지를 봐요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[8.0,72.0],[8.0,40.0]],[[88.0,40.0],[88.0,72.0]],[[8.0,72.0],[88.0,72.0]]],"curve":[[[8.0,40.0],[88.0,40.0],[48.0,-19.2]]],"cap":"둥근 문"},{"w":96,"h":80,"seg":[[[25.6,72.0],[8.0,72.0]],[[8.0,72.0],[8.0,32.0]],[[8.0,32.0],[48.0,8.0]],[[48.0,8.0],[88.0,32.0]],[[88.0,32.0],[88.0,72.0]],[[88.0,72.0],[54.4,72.0]]],"cap":"열린 집"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L03_basic#1','math',4,2,'u4','L03','g4_2_math_u4_L03_basic','lesson_basic','M4-2-u4-C3',1,'mc','auto','변이 5개인 다각형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X04','M4-2-u4-X07']::text[],true,'{"seq":1,"concept":"M4-2-u4-C3","difficulty":1,"kind":"mc","stem":"변이 5개인 다각형의 이름은 무엇인가요?","options":[{"t":"오각형","correct":true},{"t":"사각형","mis":"M4-2-u4-X04"},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"정오각형","mis":"M4-2-u4-X07"}],"explanation":["다각형은 변의 수에 따라 이름을 붙여요.","변의 수와 꼭짓점의 수는 같아요 — 모두 5개예요.","그래서 오각형이에요."],"variant_rule":{"alt":[{"stem":"꼭짓점이 6개인 다각형의 이름은 무엇인가요?","options":[{"t":"육각형","correct":true},{"t":"오각형","mis":"M4-2-u4-X04"},{"t":"칠각형","mis":"M4-2-u4-X06"},{"t":"정육각형","mis":"M4-2-u4-X07"}],"explanation":["다각형은 변의 수에 따라 이름을 붙여요.","변의 수와 꼭짓점의 수는 같아요 — 모두 6개예요.","그래서 육각형이에요."],"asset":null},{"stem":"선분 7개로 둘러싸인 도형의 이름은 무엇인가요?","options":[{"t":"칠각형","correct":true},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"팔각형","mis":"M4-2-u4-X04"},{"t":"정칠각형","mis":"M4-2-u4-X07"}],"explanation":["다각형은 변의 수에 따라 이름을 붙여요.","변의 수와 꼭짓점의 수는 같아요 — 모두 7개예요.","그래서 칠각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L03_basic#2','math',4,2,'u4','L03','g4_2_math_u4_L03_basic','lesson_basic','M4-2-u4-C3',1,'sa','auto','칠각형의 변은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u4-C3","difficulty":1,"kind":"sa","stem":"칠각형의 변은 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["이름의 앞부분이 변의 수를 알려 줘요 — 칠는 7개.","꼭짓점의 수는 변의 수와 같아요.","칠각형의 변은 7개예요."],"variant_rule":{"alt":[{"stem":"육각형의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["이름의 앞부분이 변의 수를 알려 줘요 — 육는 6개.","꼭짓점의 수는 변의 수와 같아요.","육각형의 꼭짓점은 6개예요."],"asset":null},{"stem":"팔각형의 변은 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["이름의 앞부분이 변의 수를 알려 줘요 — 팔는 8개.","꼭짓점의 수는 변의 수와 같아요.","팔각형의 변은 8개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L03_basic#3','math',4,2,'u4','L03','g4_2_math_u4_L03_basic','lesson_basic','M4-2-u4-C3',1,'mc','auto','아래 도형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X04','M4-2-u4-X02']::text[],true,'{"seq":3,"concept":"M4-2-u4-C3","difficulty":1,"kind":"mc","stem":"아래 도형의 이름은 무엇인가요?","options":[{"t":"육각형","correct":true},{"t":"오각형","mis":"M4-2-u4-X04"},{"t":"칠각형","mis":"M4-2-u4-X04"},{"t":"팔각형","mis":"M4-2-u4-X02"}],"explanation":["변에 표시하며 하나씩 세요.","변이 6개예요.","변이 6개인 다각형은 육각형이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,8.0],[40.0,8.0],[40.0,40.0],[88.0,40.0],[88.0,72.0],[8.0,72.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 도형의 이름은 무엇인가요?","options":[{"t":"오각형","correct":true},{"t":"사각형","mis":"M4-2-u4-X04"},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"칠각형","mis":"M4-2-u4-X02"}],"explanation":["변에 표시하며 하나씩 세요.","변이 5개예요.","변이 5개인 다각형은 오각형이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[16.0,8.0],[80.0,16.0],[88.0,56.0],[48.0,72.0],[8.0,48.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 아래 도형의 이름은 무엇인가요?","options":[{"t":"칠각형","correct":true},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"팔각형","mis":"M4-2-u4-X04"},{"t":"구각형","mis":"M4-2-u4-X02"}],"explanation":["변에 표시하며 하나씩 세요.","변이 7개예요.","변이 7개인 다각형은 칠각형이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,8.0],[88.0,8.0],[88.0,72.0],[64.0,72.0],[64.0,40.0],[32.0,40.0],[8.0,72.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L03_basic#4','math',4,2,'u4','L03','g4_2_math_u4_L03_basic','lesson_basic','M4-2-u4-C3',1,'mc','auto','정지 표지판은 선분 8개로 둘러싸인 모양이에요. 이 모양의 이름은 무엇인가요?',ARRAY['M4-2-u4-X04','M4-2-u4-X06']::text[],true,'{"seq":4,"concept":"M4-2-u4-C3","difficulty":1,"kind":"mc","stem":"정지 표지판은 선분 8개로 둘러싸인 모양이에요. 이 모양의 이름은 무엇인가요?","options":[{"t":"팔각형","correct":true},{"t":"칠각형","mis":"M4-2-u4-X04"},{"t":"구각형","mis":"M4-2-u4-X06"},{"t":"정칠각형","mis":"M4-2-u4-X04"}],"explanation":["변의 수(= 꼭짓점의 수)를 확인해요.","8개예요.","그래서 팔각형이에요."],"variant_rule":{"alt":[{"stem":"벌집의 한 칸은 선분 6개로 둘러싸인 모양이에요. 이 모양의 이름은 무엇인가요?","options":[{"t":"육각형","correct":true},{"t":"오각형","mis":"M4-2-u4-X04"},{"t":"칠각형","mis":"M4-2-u4-X06"},{"t":"정오각형","mis":"M4-2-u4-X04"}],"explanation":["변의 수(= 꼭짓점의 수)를 확인해요.","6개예요.","그래서 육각형이에요."],"asset":null},{"stem":"축구공의 검은 무늬 한 조각은 변이 5개예요. 이 모양의 이름은 무엇인가요?","options":[{"t":"오각형","correct":true},{"t":"사각형","mis":"M4-2-u4-X04"},{"t":"육각형","mis":"M4-2-u4-X06"},{"t":"칠각형","mis":"M4-2-u4-X04"}],"explanation":["변의 수(= 꼭짓점의 수)를 확인해요.","5개예요.","그래서 오각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L03_basic#5','math',4,2,'u4','L03','g4_2_math_u4_L03_basic','lesson_basic','M4-2-u4-C3',2,'mc','auto','다각형의 이름이 같으면 무엇이 같은가요?',ARRAY['M4-2-u4-X05']::text[],true,'{"seq":5,"concept":"M4-2-u4-C3","difficulty":2,"kind":"mc","stem":"다각형의 이름이 같으면 무엇이 같은가요?","options":[{"t":"변의 수와 꼭짓점의 수","correct":true},{"t":"변의 길이","mis":"M4-2-u4-X05"},{"t":"도형의 크기","mis":"M4-2-u4-X05"},{"t":"각의 크기","mis":"M4-2-u4-X05"}],"explanation":["다각형의 이름은 변의 수로만 정해요.","이름이 같으면 변의 수와 꼭짓점의 수가 같고, 모양·크기·변의 길이는 달라도 돼요.","삼각형·사각형도 선분으로만 둘러싸인 다각형이에요."],"variant_rule":{"alt":[{"stem":"오각형에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"오각형은 모두 변이 5개이지만 모양은 여러 가지예요","correct":true},{"t":"오각형은 모두 모양과 크기가 같아요","mis":"M4-2-u4-X05"},{"t":"오목한 곳이 있으면 오각형이 아니에요","mis":"M4-2-u4-X05"},{"t":"오각형의 꼭짓점은 6개예요","mis":"M4-2-u4-X06"}],"explanation":["다각형의 이름은 변의 수로만 정해요.","이름이 같으면 변의 수와 꼭짓점의 수가 같고, 모양·크기·변의 길이는 달라도 돼요.","삼각형·사각형도 선분으로만 둘러싸인 다각형이에요."],"asset":null},{"stem":"삼각형은 다각형인가요?","options":[{"t":"선분으로만 둘러싸여 있으므로 다각형이에요","correct":true},{"t":"변이 적어서 다각형이 아니에요","mis":"M4-2-u4-X03"},{"t":"각이 세 개뿐이라 다각형이 아니에요","mis":"M4-2-u4-X02"},{"t":"곡선이 있어서 다각형이 아니에요","mis":"M4-2-u4-X01"}],"explanation":["다각형의 이름은 변의 수로만 정해요.","이름이 같으면 변의 수와 꼭짓점의 수가 같고, 모양·크기·변의 길이는 달라도 돼요.","삼각형·사각형도 선분으로만 둘러싸인 다각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L03_basic#6','math',4,2,'u4','L03','g4_2_math_u4_L03_basic','lesson_basic','M4-2-u4-C2',2,'sa','auto','칠각형의 변의 수와 꼭짓점의 수를 더하면 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u4-C2","difficulty":2,"kind":"sa","stem":"칠각형의 변의 수와 꼭짓점의 수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["이름의 앞부분 = 변의 수 = 꼭짓점의 수예요.","7개와 7개예요.","7 + 7 = 14개예요."],"variant_rule":{"alt":[{"stem":"오각형의 변의 수와 육각형의 변의 수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["이름의 앞부분 = 변의 수 = 꼭짓점의 수예요.","5개와 6개예요.","5 + 6 = 11개예요."],"asset":null},{"stem":"팔각형의 변의 수와 꼭짓점의 수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["이름의 앞부분 = 변의 수 = 꼭짓점의 수예요.","8개와 8개예요.","8 + 8 = 16개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
