INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L03_basic#10','math',4,2,'u4','L03','g4_2_math_u4_L03_basic','lesson_basic','M4-2-u4-C3',3,'sa','auto','오각형 2개와 육각형 3개가 있어요. 변은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u4-C3","difficulty":3,"kind":"sa","stem":"오각형 2개와 육각형 3개가 있어요. 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["오각형 하나는 5개, 육각형 하나는 6개예요.","5 × 2 = 10, 6 × 3 = 18이에요.","모두 10 + 18 = 28개예요."],"variant_rule":{"alt":[{"stem":"칠각형 2개와 팔각형 1개의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["칠각형 하나는 7개, 팔각형 하나는 8개예요.","7 × 2 = 14, 8 × 1 = 8이에요.","모두 14 + 8 = 22개예요."],"asset":null},{"stem":"육각형 2개와 팔각형 2개가 있어요. 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["육각형 하나는 6개, 팔각형 하나는 8개예요.","6 × 2 = 12, 8 × 2 = 16이에요.","모두 12 + 16 = 28개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
