INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L03_challenge#4','math',4,2,'u4','L03','g4_2_math_u4_L03_challenge','lesson_challenge','M4-2-u4-C3',3,'error','auto','아래 도형을 보고 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u4-X05','M4-2-u4-X20']::text[],true,'{"seq":4,"concept":"M4-2-u4-C3","difficulty":3,"kind":"error","stem":"아래 도형을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「들어간 곳이 있으니까 육각형이 아니야.」","correct":true,"mis_target":"M4-2-u4-X05"},{"t":"하랑 — 「변이 6개이니 육각형이야.」","mis":"M4-2-u4-X20"},{"t":"지아 — 「꼭짓점도 6개야.」","mis":"M4-2-u4-X20"},{"t":"준서 — 「선분으로만 둘러싸였으니 다각형이야.」","mis":"M4-2-u4-X20"}],"explanation":["이 도형은 선분 6개로 둘러싸여 있어요.","변의 수 = 꼭짓점의 수 = 6 — 그래서 육각형이에요.","오목한 곳이 있어도 이름은 변의 수로만 정해요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,72.0],[8.0,8.0],[32.0,32.0],[56.0,8.0],[88.0,40.0],[88.0,72.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 아래 도형을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「꼭짓점이 7개이니까 변은 8개야.」","correct":true,"mis_target":"M4-2-u4-X06"},{"t":"지아 — 「변이 7개이니 칠각형이야.」","mis":"M4-2-u4-X20"},{"t":"준서 — 「꼭짓점도 7개야.」","mis":"M4-2-u4-X20"},{"t":"민서 — 「선분으로만 둘러싸였으니 다각형이야.」","mis":"M4-2-u4-X20"}],"explanation":["이 도형은 선분 7개로 둘러싸여 있어요.","변의 수 = 꼭짓점의 수 = 7 — 그래서 칠각형이에요.","오목한 곳이 있어도 이름은 변의 수로만 정해요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,8.0],[88.0,8.0],[88.0,72.0],[64.0,72.0],[64.0,40.0],[32.0,40.0],[8.0,72.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 아래 도형을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「변이 5개이니까 육각형이야.」","correct":true,"mis_target":"M4-2-u4-X04"},{"t":"준서 — 「변이 5개이니 오각형이야.」","mis":"M4-2-u4-X20"},{"t":"민서 — 「꼭짓점도 5개야.」","mis":"M4-2-u4-X20"},{"t":"도윤 — 「선분으로만 둘러싸였으니 다각형이야.」","mis":"M4-2-u4-X20"}],"explanation":["이 도형은 선분 5개로 둘러싸여 있어요.","변의 수 = 꼭짓점의 수 = 5 — 그래서 오각형이에요.","오목한 곳이 있어도 이름은 변의 수로만 정해요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,8.0],[88.0,8.0],[88.0,72.0],[48.0,40.0],[8.0,72.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L03_challenge#5','math',4,2,'u4','L03','g4_2_math_u4_L03_challenge','lesson_challenge','M4-2-u4-C3',3,'sa','auto','오각형 3개와 칠각형 1개의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u4-C3","difficulty":3,"kind":"sa","stem":"오각형 3개와 칠각형 1개의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["오각형 하나는 5개, 칠각형 하나는 7개예요.","5 × 3 = 15, 7 × 1 = 7이에요.","모두 15 + 7 = 22개예요."],"variant_rule":{"alt":[{"stem":"팔각형 2개와 오각형 2개가 있어요. 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["팔각형 하나는 8개, 오각형 하나는 5개예요.","8 × 2 = 16, 5 × 2 = 10이에요.","모두 16 + 10 = 26개예요."],"asset":null},{"stem":"육각형 3개와 칠각형 2개의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["육각형 하나는 6개, 칠각형 하나는 7개예요.","6 × 3 = 18, 7 × 2 = 14예요.","모두 18 + 14 = 32개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L03_challenge#6','math',4,2,'u4','L03','g4_2_math_u4_L03_challenge','lesson_challenge','M4-2-u4-C3',3,'mc','auto','모양과 크기가 같은 다각형 4개의 변을 모두 세었더니 28개였어요. 이 다각형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X09','M4-2-u4-X04']::text[],true,'{"seq":6,"concept":"M4-2-u4-C3","difficulty":3,"kind":"mc","stem":"모양과 크기가 같은 다각형 4개의 변을 모두 세었더니 28개였어요. 이 다각형의 이름은 무엇인가요?","options":[{"t":"칠각형","correct":true},{"t":"육각형","mis":"M4-2-u4-X09"},{"t":"팔각형","mis":"M4-2-u4-X04"},{"t":"사각형","mis":"M4-2-u4-X09"}],"explanation":["다각형 하나의 변의 수 × 4 = 28이에요.","28 ÷ 4 = 7 — 한 다각형의 변은 7개예요.","그래서 칠각형이에요."],"variant_rule":{"alt":[{"stem":"모양과 크기가 같은 다각형 5개의 변을 모두 세었더니 30개였어요. 이 다각형의 이름은 무엇인가요?","options":[{"t":"육각형","correct":true},{"t":"오각형","mis":"M4-2-u4-X09"},{"t":"칠각형","mis":"M4-2-u4-X04"},{"t":"팔각형","mis":"M4-2-u4-X09"}],"explanation":["다각형 하나의 변의 수 × 5 = 30이에요.","30 ÷ 5 = 6 — 한 다각형의 변은 6개예요.","그래서 육각형이에요."],"asset":null},{"stem":"모양과 크기가 같은 다각형 3개의 변을 모두 세었더니 24개였어요. 이 다각형의 이름은 무엇인가요?","options":[{"t":"팔각형","correct":true},{"t":"칠각형","mis":"M4-2-u4-X09"},{"t":"구각형","mis":"M4-2-u4-X04"},{"t":"삼각형","mis":"M4-2-u4-X09"}],"explanation":["다각형 하나의 변의 수 × 3 = 24예요.","24 ÷ 3 = 8 — 한 다각형의 변은 8개예요.","그래서 팔각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L03_challenge#7','math',4,2,'u4','L03','g4_2_math_u4_L03_challenge','lesson_challenge','M4-2-u4-C3',3,'mc','auto','직사각형 모양 종이의 귀퉁이 1군데를 점선을 따라 곧게 잘라 냈어요. 남은 도형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X04']::text[],true,'{"seq":7,"concept":"M4-2-u4-C3","difficulty":3,"kind":"mc","stem":"직사각형 모양 종이의 귀퉁이 1군데를 점선을 따라 곧게 잘라 냈어요. 남은 도형의 이름은 무엇인가요?","options":[{"t":"오각형","correct":true},{"t":"사각형","mis":"M4-2-u4-X04"},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"칠각형","mis":"M4-2-u4-X04"}],"explanation":["귀퉁이 한 곳을 자르면 변이 1개 늘어요.","남은 도형의 변은 4 + 1 = 5개예요.","변이 5개이니 오각형이에요."],"asset":{"type":"geo","items":[{"w":144,"h":96,"poly":[[[8.0,8.0],[136.0,8.0],[136.0,88.0],[40.0,88.0],[8.0,56.0]]],"dash":[[[40.0,88.0],[8.0,88.0]],[[8.0,88.0],[8.0,56.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직사각형 모양 종이의 귀퉁이 2군데를 점선을 따라 곧게 잘라 냈어요. 남은 도형의 이름은 무엇인가요?","options":[{"t":"육각형","correct":true},{"t":"오각형","mis":"M4-2-u4-X04"},{"t":"칠각형","mis":"M4-2-u4-X04"},{"t":"사각형","mis":"M4-2-u4-X05"}],"explanation":["귀퉁이 한 곳을 자르면 변이 1개 늘어요.","남은 도형의 변은 4 + 2 = 6개예요.","변이 6개이니 육각형이에요."],"asset":{"type":"geo","items":[{"w":144,"h":96,"poly":[[[8.0,40.0],[40.0,8.0],[104.0,8.0],[136.0,40.0],[136.0,88.0],[8.0,88.0]]],"dash":[[[8.0,40.0],[8.0,8.0]],[[104.0,8.0],[136.0,8.0]],[[8.0,8.0],[40.0,8.0]],[[136.0,8.0],[136.0,40.0]]]}],"tag":false}},{"stem":"직사각형 모양 종이의 귀퉁이 4군데를 점선을 따라 곧게 잘라 냈어요. 남은 도형의 이름은 무엇인가요?","options":[{"t":"팔각형","correct":true},{"t":"칠각형","mis":"M4-2-u4-X04"},{"t":"구각형","mis":"M4-2-u4-X04"},{"t":"사각형","mis":"M4-2-u4-X05"}],"explanation":["귀퉁이 한 곳을 자르면 변이 1개 늘어요.","남은 도형의 변은 4 + 4 = 8개예요.","변이 8개이니 팔각형이에요."],"asset":{"type":"geo","items":[{"w":144,"h":96,"poly":[[[8.0,40.0],[40.0,8.0],[104.0,8.0],[136.0,40.0],[136.0,56.0],[104.0,88.0],[40.0,88.0],[8.0,56.0]]],"dash":[[[8.0,40.0],[8.0,8.0]],[[104.0,8.0],[136.0,8.0]],[[136.0,56.0],[136.0,88.0]],[[40.0,88.0],[8.0,88.0]],[[8.0,8.0],[40.0,8.0]],[[136.0,8.0],[136.0,40.0]],[[136.0,88.0],[104.0,88.0]],[[8.0,88.0],[8.0,56.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L03_challenge#8','math',4,2,'u4','L03','g4_2_math_u4_L03_challenge','lesson_challenge','M4-2-u4-C2',4,'mc','auto','어떤 다각형의 변의 수와 꼭짓점의 수를 더했더니 18개였어요. 이 다각형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X06','M4-2-u4-X04','M4-2-u4-X13']::text[],true,'{"seq":8,"concept":"M4-2-u4-C2","difficulty":4,"kind":"mc","stem":"어떤 다각형의 변의 수와 꼭짓점의 수를 더했더니 18개였어요. 이 다각형의 이름은 무엇인가요?","options":[{"t":"구각형","correct":true},{"t":"십각형","mis":"M4-2-u4-X06"},{"t":"팔각형","mis":"M4-2-u4-X04"},{"t":"십일각형","mis":"M4-2-u4-X13"}],"explanation":["다각형은 변의 수와 꼭짓점의 수가 같아요.","같은 수 두 개의 합이 18이니 한 수는 18 ÷ 2 = 9예요.","변이 9개인 구각형이에요."],"variant_rule":{"alt":[{"stem":"어떤 다각형의 변의 수와 꼭짓점의 수를 더했더니 14개였어요. 이 다각형의 이름은 무엇인가요?","options":[{"t":"칠각형","correct":true},{"t":"팔각형","mis":"M4-2-u4-X06"},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"구각형","mis":"M4-2-u4-X13"}],"explanation":["다각형은 변의 수와 꼭짓점의 수가 같아요.","같은 수 두 개의 합이 14이니 한 수는 14 ÷ 2 = 7이에요.","변이 7개인 칠각형이에요."],"asset":null},{"stem":"어떤 다각형의 변의 수와 꼭짓점의 수를 더했더니 20개였어요. 이 다각형의 이름은 무엇인가요?","options":[{"t":"십각형","correct":true},{"t":"십일각형","mis":"M4-2-u4-X06"},{"t":"구각형","mis":"M4-2-u4-X04"},{"t":"십이각형","mis":"M4-2-u4-X13"}],"explanation":["다각형은 변의 수와 꼭짓점의 수가 같아요.","같은 수 두 개의 합이 20이니 한 수는 20 ÷ 2 = 10이에요.","변이 10개인 십각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L03_challenge#9','math',4,2,'u4','L03','g4_2_math_u4_L03_challenge','lesson_challenge','M4-2-u4-C3',4,'mc','auto','모양과 크기가 같은 다각형 6개의 변을 모두 세었더니 30개였어요. 이 다각형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X09','M4-2-u4-X04']::text[],true,'{"seq":9,"concept":"M4-2-u4-C3","difficulty":4,"kind":"mc","stem":"모양과 크기가 같은 다각형 6개의 변을 모두 세었더니 30개였어요. 이 다각형의 이름은 무엇인가요?","options":[{"t":"오각형","correct":true},{"t":"사각형","mis":"M4-2-u4-X09"},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"칠각형","mis":"M4-2-u4-X09"}],"explanation":["다각형 하나의 변의 수 × 6 = 30이에요.","30 ÷ 6 = 5 — 한 다각형의 변은 5개예요.","그래서 오각형이에요."],"variant_rule":{"alt":[{"stem":"모양과 크기가 같은 다각형 2개의 변을 모두 세었더니 18개였어요. 이 다각형의 이름은 무엇인가요?","options":[{"t":"구각형","correct":true},{"t":"팔각형","mis":"M4-2-u4-X09"},{"t":"십각형","mis":"M4-2-u4-X04"},{"t":"십일각형","mis":"M4-2-u4-X09"}],"explanation":["다각형 하나의 변의 수 × 2 = 18이에요.","18 ÷ 2 = 9 — 한 다각형의 변은 9개예요.","그래서 구각형이에요."],"asset":null},{"stem":"모양과 크기가 같은 다각형 4개의 변을 모두 세었더니 24개였어요. 이 다각형의 이름은 무엇인가요?","options":[{"t":"육각형","correct":true},{"t":"오각형","mis":"M4-2-u4-X09"},{"t":"칠각형","mis":"M4-2-u4-X04"},{"t":"사각형","mis":"M4-2-u4-X09"}],"explanation":["다각형 하나의 변의 수 × 4 = 24예요.","24 ÷ 4 = 6 — 한 다각형의 변은 6개예요.","그래서 육각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L03_challenge#10','math',4,2,'u4','L03','g4_2_math_u4_L03_challenge','lesson_challenge','M4-2-u4-C3',4,'essay','teacher','오목하게 들어간 곳이 있는 아래 도형의 이름을 쓰고, 반듯한 육각형과 모양이 달라도 같은 이름으로 부를 수 있는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u4-C3","difficulty":4,"kind":"essay","stem":"오목하게 들어간 곳이 있는 아래 도형의 이름을 쓰고, 반듯한 육각형과 모양이 달라도 같은 이름으로 부를 수 있는 까닭을 써 보세요.","answer_guide":{"answer":"예: 육각형이다. 이 도형은 선분 6개로 둘러싸여 있고 꼭짓점도 6개이다. 다각형의 이름은 모양이나 크기가 아니라 변의 수로 정하므로, 오목한 곳이 있어도 변이 6개이면 육각형이다.","scoring_points":["육각형이라고 썼는가","변(꼭짓점)이 6개라고 썼는가","이름은 변의 수로 정하고 모양·크기와 상관없다고 썼는가"]},"explanation":["변을 세면 6개예요.","다각형의 이름은 변의 수로 정해요.","오목해도, 모양이 달라도 변이 6개면 육각형이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,72.0],[8.0,8.0],[32.0,32.0],[56.0,8.0],[88.0,40.0],[88.0,72.0]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_basic#1','math',4,2,'u4','L04','g4_2_math_u4_L04_basic','lesson_basic','M4-2-u4-C4',1,'mc','auto','정다각형은 어떤 다각형인가요?',ARRAY['M4-2-u4-X07','M4-2-u4-X08','M4-2-u4-X02']::text[],true,'{"seq":1,"concept":"M4-2-u4-C4","difficulty":1,"kind":"mc","stem":"정다각형은 어떤 다각형인가요?","options":[{"t":"변의 길이가 모두 같고 각의 크기도 모두 같은 다각형","correct":true},{"t":"변의 길이가 모두 같은 다각형","mis":"M4-2-u4-X07"},{"t":"각의 크기가 모두 같은 다각형","mis":"M4-2-u4-X08"},{"t":"변이 다섯 개보다 많은 다각형","mis":"M4-2-u4-X02"}],"explanation":["정다각형은 변의 길이가 모두 같고, 그리고 각의 크기도 모두 같은 다각형이에요.","둘 가운데 하나만 같으면 정다각형이 아니에요.","자로 변의 길이를, 각도기로 각의 크기를 재어 확인해요."],"variant_rule":{"alt":[{"stem":"변의 길이가 모두 같고 각의 크기가 모두 같은 다각형을 무엇이라고 하나요?","options":[{"t":"정다각형","correct":true},{"t":"다각형","mis":"M4-2-u4-X07"},{"t":"대각선","mis":"M4-2-u4-X11"},{"t":"정사각형","mis":"M4-2-u4-X03"}],"explanation":["정다각형은 변의 길이가 모두 같고, 그리고 각의 크기도 모두 같은 다각형이에요.","둘 가운데 하나만 같으면 정다각형이 아니에요.","자로 변의 길이를, 각도기로 각의 크기를 재어 확인해요."],"asset":null},{"stem":"정다각형인지 알아보려면 무엇을 확인해야 하나요?","options":[{"t":"변의 길이와 각의 크기를 모두","correct":true},{"t":"변의 길이만","mis":"M4-2-u4-X07"},{"t":"각의 크기만","mis":"M4-2-u4-X08"},{"t":"도형의 크기만","mis":"M4-2-u4-X10"}],"explanation":["정다각형은 변의 길이가 모두 같고, 그리고 각의 크기도 모두 같은 다각형이에요.","둘 가운데 하나만 같으면 정다각형이 아니에요.","자로 변의 길이를, 각도기로 각의 크기를 재어 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_basic#2','math',4,2,'u4','L04','g4_2_math_u4_L04_basic','lesson_basic','M4-2-u4-C4',1,'mc','auto','변의 길이가 모두 같고 각의 크기가 모두 같으며 선분 9개로 둘러싸인 도형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X07','M4-2-u4-X04']::text[],true,'{"seq":2,"concept":"M4-2-u4-C4","difficulty":1,"kind":"mc","stem":"변의 길이가 모두 같고 각의 크기가 모두 같으며 선분 9개로 둘러싸인 도형의 이름은 무엇인가요?","options":[{"t":"정구각형","correct":true},{"t":"구각형","mis":"M4-2-u4-X07"},{"t":"정팔각형","mis":"M4-2-u4-X04"},{"t":"정십각형","mis":"M4-2-u4-X04"}],"explanation":["변의 길이·각의 크기가 모두 같으니 정다각형이에요.","변(꼭짓점)이 9개이니 구각형이에요.","이름 앞에 「정」을 붙여 정구각형이에요."],"variant_rule":{"alt":[{"stem":"각의 크기가 모두 같고 변의 길이도 모두 같은 다각형의 꼭짓점이 5개예요. 이 도형의 이름은 무엇인가요?","options":[{"t":"정오각형","correct":true},{"t":"오각형","mis":"M4-2-u4-X07"},{"t":"정사각형","mis":"M4-2-u4-X04"},{"t":"정육각형","mis":"M4-2-u4-X04"}],"explanation":["변의 길이·각의 크기가 모두 같으니 정다각형이에요.","변(꼭짓점)이 5개이니 오각형이에요.","이름 앞에 「정」을 붙여 정오각형이에요."],"asset":null},{"stem":"변의 길이가 모두 같고 각의 크기가 모두 같으며 선분 8개로 둘러싸인 도형의 이름은 무엇인가요?","options":[{"t":"정팔각형","correct":true},{"t":"팔각형","mis":"M4-2-u4-X07"},{"t":"정칠각형","mis":"M4-2-u4-X04"},{"t":"정구각형","mis":"M4-2-u4-X04"}],"explanation":["변의 길이·각의 크기가 모두 같으니 정다각형이에요.","변(꼭짓점)이 8개이니 팔각형이에요.","이름 앞에 「정」을 붙여 정팔각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_basic#3','math',4,2,'u4','L04','g4_2_math_u4_L04_basic','lesson_basic','M4-2-u4-C5',1,'sa','auto','한 변의 길이가 4 cm인 정육각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u4-C5","difficulty":1,"kind":"sa","stem":"한 변의 길이가 4 cm인 정육각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["정육각형은 변이 6개이고 길이가 모두 같아요.","모든 변의 길이의 합 = 한 변 × 변의 수예요.","4 × 6 = 24 cm예요."],"asset":{"type":"geo","items":[{"w":124.0,"h":117.8,"poly":[[[77.0,93.837168574],[31.0,93.837168574],[8.0,54.0],[31.0,14.162831426],[77.0,14.162831426],[100.0,54.0]]],"tick":[[[77.0,93.837168574],[31.0,93.837168574],1],[[31.0,93.837168574],[8.0,54.0],1],[[8.0,54.0],[31.0,14.162831426],1],[[31.0,14.162831426],[77.0,14.162831426],1],[[77.0,14.162831426],[100.0,54.0],1],[[100.0,54.0],[77.0,93.837168574],1]],"lab":[[[54.0,113.8],"4 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"한 변의 길이가 5 cm인 정팔각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["정팔각형은 변이 8개이고 길이가 모두 같아요.","모든 변의 길이의 합 = 한 변 × 변의 수예요.","5 × 8 = 40 cm예요."],"asset":null},{"stem":"한 변의 길이가 7 cm인 정오각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["정오각형은 변이 5개이고 길이가 모두 같아요.","모든 변의 길이의 합 = 한 변 × 변의 수예요.","7 × 5 = 35 cm예요."],"asset":{"type":"geo","items":[{"w":121.7,"h":115.2,"poly":[[[81.038121605,91.214781741],[26.961878395,91.214781741],[10.25140025,39.785218259],[54.0,8.0],[97.74859975,39.785218259]]],"tick":[[[81.038121605,91.214781741],[26.961878395,91.214781741],1],[[26.961878395,91.214781741],[10.25140025,39.785218259],1],[[10.25140025,39.785218259],[54.0,8.0],1],[[54.0,8.0],[97.74859975,39.785218259],1],[[97.74859975,39.785218259],[81.038121605,91.214781741],1]],"lab":[[[54.0,111.2],"7 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_basic#4','math',4,2,'u4','L04','g4_2_math_u4_L04_basic','lesson_basic','M4-2-u4-C5',1,'sa','auto','정오각형의 한 각의 크기가 108°예요. 다른 한 각의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u4-C5","difficulty":1,"kind":"sa","stem":"정오각형의 한 각의 크기가 108°예요. 다른 한 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["108"],"explanation":["정다각형은 각의 크기가 모두 같아요.","한 각이 108°이면 다른 각도 모두 108°예요.","답은 108°예요."],"variant_rule":{"alt":[{"stem":"정육각형의 한 각의 크기가 120°예요. 다른 한 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["정다각형은 각의 크기가 모두 같아요.","한 각이 120°이면 다른 각도 모두 120°예요.","답은 120°예요."],"asset":{"type":"geo","items":[{"w":202.0,"h":179.5,"poly":[[[136.0,155.492267836],[52.0,155.492267836],[10.0,82.746133918],[52.0,10.0],[136.0,10.0],[178.0,82.746133918]]],"tick":[[[136.0,155.492267836],[52.0,155.492267836],1],[[52.0,155.492267836],[10.0,82.746133918],1],[[10.0,82.746133918],[52.0,10.0],1],[[52.0,10.0],[136.0,10.0],1],[[136.0,10.0],[178.0,82.746133918],1],[[178.0,82.746133918],[136.0,155.492267836],1]],"lab":[[[126.0,138.2],"120°"],[[60.0,141.6],"?"]]}],"tag":false}},{"stem":"정팔각형의 한 각의 크기가 135°예요. 다른 한 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["135"],"explanation":["정다각형은 각의 크기가 모두 같아요.","한 각이 135°이면 다른 각도 모두 135°예요.","답은 135°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_basic#5','math',4,2,'u4','L04','g4_2_math_u4_L04_basic','lesson_basic','M4-2-u4-C5',2,'sa','auto','정칠각형의 모든 변의 길이의 합이 21 cm예요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u4-C5","difficulty":2,"kind":"sa","stem":"정칠각형의 모든 변의 길이의 합이 21 cm예요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["정칠각형은 변 7개의 길이가 모두 같아요.","한 변 = 합 ÷ 변의 수예요.","21 ÷ 7 = 3 cm예요."],"variant_rule":{"alt":[{"stem":"정팔각형의 모든 변의 길이의 합이 32 cm예요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["정팔각형은 변 8개의 길이가 모두 같아요.","한 변 = 합 ÷ 변의 수예요.","32 ÷ 8 = 4 cm예요."],"asset":null},{"stem":"정오각형의 모든 변의 길이의 합이 45 cm예요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["정오각형은 변 5개의 길이가 모두 같아요.","한 변 = 합 ÷ 변의 수예요.","45 ÷ 5 = 9 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_basic#6','math',4,2,'u4','L04','g4_2_math_u4_L04_basic','lesson_basic','M4-2-u4-C4',2,'mc','auto','네 변의 길이가 모두 같지만 네 각의 크기는 같지 않은 사각형이 있어요. 이 도형은 정사각형인가요?',ARRAY['M4-2-u4-X07','M4-2-u4-X04','M4-2-u4-X10']::text[],true,'{"seq":6,"concept":"M4-2-u4-C4","difficulty":2,"kind":"mc","stem":"네 변의 길이가 모두 같지만 네 각의 크기는 같지 않은 사각형이 있어요. 이 도형은 정사각형인가요?","options":[{"t":"각의 크기도 모두 같아야 하므로 정사각형이 아니에요","correct":true},{"t":"변이 모두 같으니 정사각형이에요","mis":"M4-2-u4-X07"},{"t":"변이 4개라서 정사각형이에요","mis":"M4-2-u4-X04"},{"t":"크기가 작아서 정사각형이 아니에요","mis":"M4-2-u4-X10"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같아야 해요.","이 도형은 각의 크기이(가) 모두 같지 않아요.","그래서 정사각형이 아니에요."],"asset":{"type":"geo","items":[{"w":160.0,"h":106.7,"poly":[[[10.0,82.746133918],[94.0,82.746133918],[136.0,10.0],[52.0,10.0]]],"tick":[[[10.0,82.746133918],[94.0,82.746133918],1],[[94.0,82.746133918],[136.0,10.0],1],[[136.0,10.0],[52.0,10.0],1],[[52.0,10.0],[10.0,82.746133918],1]],"lab":[[[23.9,74.7],"60°"],[[84.0,65.4],"120°"],[[122.1,18.0],"60°"],[[62.0,27.3],"120°"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"네 각의 크기가 모두 같지만 네 변의 길이는 같지 않은 사각형이 있어요. 이 도형은 정사각형인가요?","options":[{"t":"변의 길이도 모두 같아야 하므로 정사각형이 아니에요","correct":true},{"t":"각이 모두 같으니 정사각형이에요","mis":"M4-2-u4-X08"},{"t":"변이 4개라서 정사각형이에요","mis":"M4-2-u4-X04"},{"t":"크기가 작아서 정사각형이 아니에요","mis":"M4-2-u4-X10"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같아야 해요.","이 도형은 변의 길이이(가) 모두 같지 않아요.","그래서 정사각형이 아니에요."],"asset":{"type":"geo","items":[{"w":126.0,"h":80.0,"poly":[[[10.0,56.0],[102.0,56.0],[102.0,10.0],[10.0,10.0]]],"lab":[[[56.0,76.0],"6 cm"],[[122.0,33.0],"3 cm"]],"right":[[[10.0,10.0],[10.0,56.0],[102.0,56.0]],[[10.0,56.0],[102.0,56.0],[102.0,10.0]],[[102.0,56.0],[102.0,10.0],[10.0,10.0]],[[102.0,10.0],[10.0,10.0],[10.0,56.0]]]}],"tag":false}},{"stem":"여섯 변의 길이가 모두 같지만 각