INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_basic#8','math',4,2,'u4','L04','g4_2_math_u4_L04_basic','lesson_basic','M4-2-u4-C4',2,'ox','auto','크기가 다른 두 정육각형은 하나만 정육각형이에요.',ARRAY['M4-2-u4-X10']::text[],true,'{"seq":8,"concept":"M4-2-u4-C4","difficulty":2,"kind":"ox","stem":"크기가 다른 두 정육각형은 하나만 정육각형이에요.","answer":"X","reason_options":[{"t":"둘 다 변의 길이와 각의 크기가 모두 같아서","correct":true},{"t":"정육각형은 크기가 정해져 있어서","mis":"M4-2-u4-X10"}],"mis":"M4-2-u4-X10","explanation":["정다각형은 변의 길이·각의 크기로만 정해요.","크기나 놓인 방향은 상관없어요.","변이 모두 같고 각이 모두 같으면 정다각형이에요."],"asset":{"type":"geo","items":[{"w":124.0,"h":117.8,"poly":[[[77.0,93.837168574],[31.0,93.837168574],[8.0,54.0],[31.0,14.162831426],[77.0,14.162831426],[100.0,54.0]]],"tick":[[[77.0,93.837168574],[31.0,93.837168574],1],[[31.0,93.837168574],[8.0,54.0],1],[[8.0,54.0],[31.0,14.162831426],1],[[31.0,14.162831426],[77.0,14.162831426],1],[[77.0,14.162831426],[100.0,54.0],1],[[100.0,54.0],[77.0,93.837168574],1]]},{"w":87.1,"h":87.0,"poly":[[[43.56554672,62.958533024],[16.435998912,56.031222165],[8.870452192,29.072689141],[28.43445328,9.041466976],[55.564001088,15.968777835],[63.129547808,42.927310859]]],"tick":[[[43.56554672,62.958533024],[16.435998912,56.031222165],1],[[16.435998912,56.031222165],[8.870452192,29.072689141],1],[[8.870452192,29.072689141],[28.43445328,9.041466976],1],[[28.43445328,9.041466976],[55.564001088,15.968777835],1],[[55.564001088,15.968777835],[63.129547808,42.927310859],1],[[63.129547808,42.927310859],[43.56554672,62.958533024],1]]}]},"variant_rule":{"alt":[{"stem":"정사각형을 비스듬히 돌려 놓아도 정사각형이에요.","answer":"O","reason_options":[{"t":"변의 길이와 각의 크기는 그대로라서","correct":true},{"t":"반듯하게 놓여야 정사각형이라서","mis":"M4-2-u4-X10"}],"explanation":["정다각형은 변의 길이·각의 크기로만 정해요.","크기나 놓인 방향은 상관없어요.","변이 모두 같고 각이 모두 같으면 정다각형이에요."],"asset":{"type":"geo","items":[{"w":117.5,"h":117.5