INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_basic#9','math',4,2,'u4','L04','g4_2_math_u4_L04_basic','lesson_basic','M4-2-u4-C5',2,'sa','auto','한 변의 길이가 3 cm인 정칠각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u4-C5","difficulty":2,"kind":"sa","stem":"한 변의 길이가 3 cm인 정칠각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["정칠각형은 변이 7개이고 길이가 모두 같아요.","모든 변의 길이의 합 = 한 변 × 변의 수예요.","3 × 7 = 21 cm예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 6 cm인 정구각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["정구각형은 변이 9개이고 길이가 모두 같아요.","모든 변의 길이의 합 = 한 변 × 변의 수예요.","6 × 9 = 54 cm예요."],"asset":{"type":"geo","items":[{"w":123.3,"h":121.2,"poly":[[[69.732926593,97.225860556],[38.267073407,97.225860556],[14.162831426,77.0],[8.698843361,46.012183827],[24.431769954,18.761955617],[54.0,8.0],[83.568230046,18.761955617],[99.301156639,46.012183827],[93.837168574,77.0]]],"tick":[[[69.732926593,97.225860556],[38.267073407,97.225860556],1],[[38.267073407,97.225860556],[14.162831426,77.0],1],[[14.162831426,77.0],[8.698843361,46.012183827],1],[[8.698843361,46.012183827],[24.431769954,18.761955617],1],[[24.431769954,18.761955617],[54.0,8.0],1],[[54.0,8.0],[83.568230046,18.761955617],1],[[83.568230046,18.761955617],[99.301156639,46.012183827],1],[[99.301156639,46.012183827],[93.837168574,77.0],1],[[93.837168574,77.0],[69.732926593,97.225860556],1]],"lab":[[[54.0,117.2],"6 cm"]]}],"tag":false}},{"stem":"한 변의 길이가 9 cm인 정육각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["정육각형은 변이 6개이고 길이가 모두 같아요.","모든 변의 길이의 합 = 한 변 × 변의 수예요.","9 × 6 = 54 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_basic#10','math',4,2,'u4','L04','g4_2_math_u4_L04_basic','lesson_basic','M4-2-u4-C5',3,'sa','auto','정육각형의 한 각의 크기는 120°예요. 정육각형의 모든 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u4-C5","difficulty":3,"kind":"sa","stem":"정육각형의 한 각의 크기는 120°예요. 정육각형의 모든 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["720"],"explanation":["정육각형은 각이 6개이고 크기가 모두 같아요.","모든 각의 크기의 합 = 한 각 × 각의 수예요.","120° × 6 = 720°예요."],"variant_rule":{"alt":[{"stem":"정팔각형의 한 각의 크기는 135°예요. 정팔각형의 모든 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["1080"],"explanation":["정팔각형은 각이 8개이고 크기가 모두 같아요.","모든 각의 크기의 합 = 한 각 × 각의 수예요.","135° × 8 = 1080°예요."],"asset":null},{"stem":"정오각형의 한 각의 크기는 108°예요. 정오각형의 모든 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["540"],"explanation":["정오각형은 각이 5개이고 크기가 모두 같아요.","모든 각의 크기의 합 = 한 각 × 각의 수예요.","108° × 5 = 540°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_challenge#1','math',4,2,'u4','L04','g4_2_math_u4_L04_challenge','lesson_challenge','M4-2-u4-C4',2,'mc','auto','여섯 각의 크기가 모두 같지만 변의 길이는 같지 않은 육각형이 있어요. 이 도형은 정육각형인가요?',ARRAY['M4-2-u4-X08','M4-2-u4-X04','M4-2-u4-X10']::text[],true,'{"seq":1,"concept":"M4-2-u4-C4","difficulty":2,"kind":"mc","stem":"여섯 각의 크기가 모두 같지만 변의 길이는 같지 않은 육각형이 있어요. 이 도형은 정육각형인가요?","options":[{"t":"변의 길이도 모두 같아야 하므로 정육각형이 아니에요","correct":true},{"t":"각이 모두 같으니 정육각형이에요","mis":"M4-2-u4-X08"},{"t":"변이 6개라서 정육각형이에요","mis":"M4-2-u4-X04"},{"t":"크기가 작아서 정육각형이 아니에요","mis":"M4-2-u4-X10"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같아야 해요.","이 도형은 변의 길이이(가) 모두 같지 않아요.","그래서 정육각형이 아니에요."],"asset":{"type":"geo","items":[{"w":286.0,"h":252.2,"poly":[[[52.0,228.238401754],[220.0,228.238401754],[262.0,155.492267836],[178.0,10.0],[94.0,10.0],[10.0,155.492267836]]],"lab":[[[65.1,213.1],"120°"],[[206.9,213.1],"120°"],[[242.4,151.7],"120°"],[[171.5,28.9],"120°"],[[100.5,28.9],"120°"],[[29.6,151.7],"120°"],[[136.0,248.2],"6 cm"],[[258.3,201.9],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"두 변의 길이와 두 각의 크기만 같은 삼각형이 있어요. 이 도형은 정삼각형인가요?","options":[{"t":"각의 크기도 모두 같아야 하므로 정삼각형이 아니에요","correct":true},{"t":"변이 모두 같으니 정삼각형이에요","mis":"M4-2-u4-X07"},{"t":"변이 3개라서 정삼각형이에요","mis":"M4-2-u4-X04"},{"t":"크기가 작아서 정삼각형이 아니에요","mis":"M4-2-u4-X10"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같아야 해요.","이 도형은 각의 크기이(가) 모두 같지 않아요.","그래서 정삼각형이 아니에요."],"asset":{"type":"geo","items":[{"w":156.8,"h":112.9,"poly":[[[10.0,88.934180146],[132.799784807,88.934180146],[38.729692039,10.0]]],"tick":[[[10.0,88.934180146],[132.799784807,88.934180146],1],[[132.799784807,88.934180146],[38.729692039,10.0],1]],"lab":[[[24.2,81.5],"70°"],[[117.8,83.5],"40°"],[[44.8,24.8],"70°"]]}],"tag":false}},{"stem":"네 변의 길이가 모두 같지만 네 각의 크기는 같지 않은 사각형이 있어요. 이 도형은 정사각형인가요?","options":[{"t":"각의 크기도 모두 같아야 하므로 정사각형이 아니에요","correct":true},{"t":"변이 모두 같으니 정사각형이에요","mis":"M4-2-u4-X07"},{"t":"변이 4개라서 정사각형이에요","mis":"M4-2-u4-X04"},{"t":"크기가 작아서 정사각형이 아니에요","mis":"M4-2-u4-X10"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같아야 해요.","이 도형은 각의 크기이(가) 모두 같지 않아요.","그래서 정사각형이 아니에요."],"asset":{"type":"geo","items":[{"w":160.0,"h":106.7,"poly":[[[10.0,82.746133918],[94.0,82.746133918],[136.0,10.0],[52.0,10.0]]],"tick":[[[10.0,82.746133918],[94.0,82.746133918],1],[[94.0,82.746133918],[136.0,10.0],1],[[136.0,10.0],[52.0,10.0],1],[[52.0,10.0],[10.0,82.746133918],1]],"lab":[[[23.9,74.7],"60°"],[[84.0,65.4],"120°"],[[122.1,18.0],"60°"],[[62.0,27.3],"120°"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_challenge#2','math',4,2,'u4','L04','g4_2_math_u4_L04_challenge','lesson_challenge','M4-2-u4-C4',2,'mc','auto','정다각형은 어느 것인가요? (같은 표시가 있는 변은 길이가 같아요.)',ARRAY['M4-2-u4-X07','M4-2-u4-X08']::text[],true,'{"seq":2,"concept":"M4-2-u4-C4","difficulty":2,"kind":"mc","stem":"정다각형은 어느 것인가요? (같은 표시가 있는 변은 길이가 같아요.)","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-2-u4-X07"},{"t":"㉰","mis":"M4-2-u4-X07"},{"t":"㉱","mis":"M4-2-u4-X08"}],"explanation":["변의 길이와 각의 크기를 함께 봐요.","㉯은 같은 길이 표시가 모든 변에 있고 각의 크기도 모두 60°예요.","변만 같거나 각만 같은 도형은 정다각형이 아니에요."],"asset":{"type":"geo","items":[{"w":156.8,"h":112.9,"poly":[[[10.0,88.934180146],[132.799784807,88.934180146],[38.729692039,10.0]]],"tick":[[[10.0,88.934180146],[132.799784807,88.934180146],1],[[132.799784807,88.934180146],[38.729692039,10.0],1]],"lab":[[[24.2,81.5],"70°"],[[117.8,83.5],"40°"],[[44.8,24.8],"70°"]]},{"w":125.3,"h":107.0,"poly":[[[101.301270189,83.0],[14.698729811,83.0],[58.0,8.0]]],"tick":[[[101.301270189,83.0],[14.698729811,83.0],1],[[14.698729811,83.0],[58.0,8.0],1],[[58.0,8.0],[101.301270189,83.0],1]],"lab":[[[87.4,75.0],"60°"],[[28.6,75.0],"60°"],[[58.0,24.0],"60°"]]},{"w":160.0,"h":106.7,"poly":[[[10.0,82.746133918],[94.0,82.746133918],[136.0,10.0],[52.0,10.0]]],"tick":[[[10.0,82.746133918],[94.0,82.746133918],1],[[94.0,82.746133918],[136.0,10.0],1],[[136.0,10.0],[52.0,10.0],1],[[52.0,10.0],[10.0,82.746133918],1]],"lab":[[[23.9,74.7],"60°"],[[84.0,65.4],"120°"],[[122.1,18.0],"60°"],[[62.0,27.3],"120°"]]},{"w":286.0,"h":252.2,"poly":[[[52.0,228.238401754],[220.0,228.238401754],[262.0,155.492267836],[178.0,10.0],[94.0,10.0],[10.0,155.492267836]]],"lab":[[[65.1,213.1],"120°"],[[206.9,213.1],"120°"],[[242.4,151.7],"120°"],[[171.5,28.9],"120°"],[[100.5,28.9],"120°"],[[29.6,151.7],"120°"],[[136.0,248.2],"6 cm"