,24.8],"70°"]]},{"w":224.3,"h":160.7,"poly":[[[52.0,136.740293133],[136.000000001,136.740293133],[200.347733224,82.746133918],[158.347733224,10.0],[74.347733223,10.0],[10.0,63.994159213]]],"tick":[[[52.0,136.740293133],[136.000000001,136.740293133],1],[[136.000000001,136.740293133],[200.347733224,82.746133918],1],[[200.347733224,82.746133918],[158.347733224,10.0],1],[[158.347733224,10.0],[74.347733223,10.0],1],[[74.347733223,10.0],[10.0,63.994159213],1],[[10.0,63.994159213],[52.0,136.740293133],1]],"lab":[[[64.9,121.4],"120°"],[[127.3,118.8],"140°"],[[180.4,80.8],"100°"],[[145.5,25.3],"120°"],[[83.1,28.0],"140°"],[[29.9,66.0],"100°"]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_challenge#3','math',4,2,'u4','L04','g4_2_math_u4_L04_challenge','lesson_challenge','M4-2-u4-C4',3,'error','auto','정다각형에 대해 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u4-X07','M4-2-u4-X20']::text[],true,'{"seq":3,"concept":"M4-2-u4-C4","difficulty":3,"kind":"error","stem":"정다각형에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「마름모는 네 변이 모두 같으니까 정사각형이야.」","correct":true,"mis_target":"M4-2-u4-X07"},{"t":"준서 — 「정다각형은 변과 각이 모두 같아야 해.」","mis":"M4-2-u4-X20"},{"t":"민서 — 「정팔각형은 변이 8개야.」","mis":"M4-2-u4-X20"},{"t":"도윤 — 「작은 정삼각형도 정다각형이야.」","mis":"M4-2-u4-X20"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같은 다각형이에요.","지아의 말은 그 뜻(또는 계산)과 맞지 않아요.","둘레는 한 변 × 변의 수(정육각형은 6)로 구해요."],"variant_rule":{"alt":[{"stem":"정다각형에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「직사각형은 네 각이 모두 같으니까 정다각형이야.」","correct":true,"mis_target":"M4-2-u4-X08"},{"t":"민서 — 「정팔각형은 변이 8개야.」","mis":"M4-2-u4-X20"},{"t":"도윤 — 「작은 정삼각형도 정다각형이야.」","mis":"M4-2-u4-X20"},{"t":"서윤 — 「정다각형의 둘레는 한 변 × 변의 수야.」","mis":"M4-2-u4-X20"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같은 다각형이에요.","준서의 말은 그 뜻(또는 계산)과 맞지 않아요.","둘레는 한 변 × 변의 수(정육각형은 6)로 구해요."],"asset":null},{"stem":"정다각형에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「한 변이 5 cm인 정육각형의 둘레는 5 × 5 = 25 cm야.」","correct":true,"mis_target":"M4-2-u4-X09"},{"t":"도윤 — 「작은 정삼각형도 정다각형이야.」","mis":"M4-2-u4-X20"},{"t":"서윤 — 「정다각형의 둘레는 한 변 × 변의 수야.」","mis":"M4-2-u4-X20"},{"t":"시우 — 「정다각형은 변과 각이 모두 같아야 해.」","mis":"M4-2-u4-X20"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같은 다각형이에요.","민서의 말은 그 뜻(또는 계산)과 맞지 않아요.","둘레는 한 변 × 변의 수(정육각형은 6)로 구해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_challenge#4','math',4,2,'u4','L04','g4_2_math_u4_L04_challenge','lesson_challenge','M4-2-u4-C5',3,'mc','auto','모든 변의 길이의 합이 48 cm이고 한 변의 길이가 6 cm인 정다각형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X09','M4-2-u4-X07']::text[],true,'{"seq":4,"concept":"M4-2-u4-C5","difficulty":3,"kind":"mc","stem":"모든 변의 길이의 합이 48 cm이고 한 변의 길이가 6 cm인 정다각형의 이름은 무엇인가요?","options":[{"t":"정팔각형","correct":true},{"t":"정칠각형","mis":"M4-2-u4-X09"},{"t":"정구각형","mis":"M4-2-u4-X09"},{"t":"팔각형","mis":"M4-2-u4-X07"}],"explanation":["변의 수 = 합 ÷ 한 변이에요.","48 ÷ 6 = 8 — 변이 8개예요.","정다각형이니 정팔각형이에요."],"variant_rule":{"alt":[{"stem":"모든 변의 길이의 합이 35 cm이고 한 변의 길이가 5 cm인 정다각형의 이름은 무엇인가요?","options":[{"t":"정칠각형","correct":true},{"t":"정육각형","mis":"M4-2-u4-X09"},{"t":"정팔각형","mis":"M4-2-u4-X09"},{"t":"칠각형","mis":"M4-2-u4-X07"}],"explanation":["변의 수 = 합 ÷ 한 변이에요.","35 ÷ 5 = 7 — 변이 7개예요.","정다각형이니 정칠각형이에요."],"asset":null},{"stem":"모든 변의 길이의 합이 54 cm이고 한 변의 길이가 9 cm인 정다각형의 이름은 무엇인가요?","options":[{"t":"정육각형","correct":true},{"t":"정오각형","mis":"M4-2-u4-X09"},{"t":"정칠각형","mis":"M4-2-u4-X09"},{"t":"육각형","mis":"M4-2-u4-X07"}],"explanation":["변의 수 = 합 ÷ 한 변이에요.","54 ÷ 9 = 6 — 변이 6개예요.","정다각형이니 정육각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_challenge#5','math',4,2,'u4','L04','g4_2_math_u4_L04_challenge','lesson_challenge','M4-2-u4-C5',3,'sa','auto','정육각형의 모든 변의 길이의 합이 42 cm예요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u4-C5","difficulty":3,"kind":"sa","stem":"정육각형의 모든 변의 길이의 합이 42 cm예요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["정육각형은 변 6개의 길이가 모두 같아요.","한 변 = 합 ÷ 변의 수예요.","42 ÷ 6 = 7 cm예요."],"variant_rule":{"alt":[{"stem":"정구각형의 모든 변의 길이의 합이 45 cm예요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["정구각형은 변 9개의 길이가 모두 같아요.","한 변 = 합 ÷ 변의 수예요.","45 ÷ 9 = 5 cm예요."],"asset":null},{"stem":"정팔각형의 모든 변의 길이의 합이 48 cm예요. 한 변의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["정팔각형은 변 8개의 길이가 모두 같아요.","한 변 = 합 ÷ 변의 수예요.","48 ÷ 8 = 6 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_challenge#6','math',4,2,'u4','L04','g4_2_math_u4_L04_challenge','lesson_challenge','M4-2-u4-C5',3,'sa','auto','정육각형의 한 각의 크기는 120°예요. 정육각형의 모든 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u4-C5","difficulty":3,"kind":"sa","stem":"정육각형의 한 각의 크기는 120°예요. 정육각형의 모든 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["720"],"explanation":["정육각형은 각이 6개이고 크기가 모두 같아요.","모든 각의 크기의 합 = 한 각 × 각의 수예요.","120° × 6 = 720°예요."],"variant_rule":{"alt":[{"stem":"정팔각형의 한 각의 크기는 135°예요. 정팔각형의 모든 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["1080"],"explanation":["정팔각형은 각이 8개이고 크기가 모두 같아요.","모든 각의 크기의 합 = 한 각 × 각의 수예요.","135° × 8 = 1080°예요."],"asset":null},{"stem":"정오각형의 한 각의 크기는 108°예요. 정오각형의 모든 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["540"],"explanation":["정오각형은 각이 5개이고 크기가 모두 같아요.","모든 각의 크기의 합 = 한 각 × 각의 수예요.","108° × 5 = 540°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_challenge#7','math',4,2,'u4','L04','g4_2_math_u4_L04_challenge','lesson_challenge','M4-2-u4-C5',3,'sa','auto','철사 60 cm를 남김없이 모두 써서 한 변이 4 cm인 정오각형을 여러 개 만들었어요. 정오각형은 몇 개 만들었나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u4-C5","difficulty":3,"kind":"sa","stem":"철사 60 cm를 남김없이 모두 써서 한 변이 4 cm인 정오각형을 여러 개 만들었어요. 정오각형은 몇 개 만들었나요? 숫자로 쓰세요.","answer":["3"],"explanation":["정오각형 하나에 드는 철사: 4 × 5 = 20 cm.","60 cm를 20 cm씩 나눠요.","60 ÷ 20 = 3개예요."],"variant_rule":{"alt":[{"stem":"철사 72 cm를 남김없이 모두 써서 한 변이 3 cm인 정육각형을 여러 개 만들었어요. 정육각형은 몇 개 만들었나요? 숫자로 쓰세요.","answer":["4"],"explanation":["정육각형 하나에 드는 철사: 3 × 6 = 18 cm.","72 cm를 18 cm씩 나눠요.","72 ÷ 18 = 4개예요."],"asset":null},{"stem":"철사 96 cm를 남김없이 모두 써서 한 변이 2 cm인 정팔각형을 여러 개 만들었어요. 정팔각형은 몇 개 만들었나요? 숫자로 쓰세요.","answer":["6"],"explanation":["정팔각형 하나에 드는 철사: 2 × 8 = 16 cm.","96 cm를 16 cm씩 나눠요.","96 ÷ 16 = 6개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_challenge#8','math',4,2,'u4','L04','g4_2_math_u4_L04_challenge','lesson_challenge','M4-2-u4-C5',4,'sa','auto','한 변이 10 cm인 정삼각형과 모든 변의 길이의 합이 같은 정육각형이 있어요. 정육각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u4-C5","difficulty":4,"kind":"sa","stem":"한 변이 10 cm인 정삼각형과 모든 변의 길이의 합이 같은 정육각형이 있어요. 정육각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["정삼각형의 모든 변의 길이의 합: 10 × 3 = 30 cm.","정육각형도 합이 30 cm이고 변이 6개예요.","30 ÷ 6 = 5 cm예요."],"variant_rule":{"alt":[{"stem":"한 변이 6 cm인 정사각형과 모든 변의 길이의 합이 같은 정팔각형이 있어요. 정팔각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["정사각형의 모든 변의 길이의 합: 6 × 4 = 24 cm.","정팔각형도 합이 24 cm이고 변이 8개예요.","24 ÷ 8 = 3 cm예요."],"asset":null},{"stem":"한 변이 4 cm인 정육각형과 모든 변의 길이의 합이 같은 정팔각형이 있어요. 정팔각형의 한 변은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["정육각형의 모든 변의 길이의 합: 4 × 6 = 24 cm.","정팔각형도 합이 24 cm이고 변이 8개예요.","24 ÷ 8 = 3 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_challenge#9','math',4,2,'u4','L04','g4_2_math_u4_L04_challenge','lesson_challenge','M4-2-u4-C5',4,'sa','auto','정육각형의 한 꼭짓점에서 대각선을 그어 삼각형 4개로 나누었어요. 정육각형의 한 각의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u4-C5","difficulty":4,"kind":"sa","stem":"정육각형의 한 꼭짓점에서 대각선을 그어 삼각형 4개로 나누었어요. 정육각형의 한 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["모든 각의 합 = 180° × 4 = 720°예요.","정육각형은 각 6개의 크기가 모두 같아요.","720° ÷ 6 = 120°예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":125.3,"pts":{"ㄱ":[83.0,101.301270189],"ㄴ":[33.0,101.301270189],"ㄷ":[8.0,58.0],"ㄹ":[33.0,14.698729811],"ㅁ":[83.0,14.698729811],"ㅂ":[108.0,58.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"정육각형의 한 꼭짓점에서 대각선을 그어 삼각형 4개로 나누었어요. 정육각형의 모든 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["720"],"explanation":["삼각형 하나의 세 각의 합은 180°예요.","삼각형 4개의 각을 모두 모으면 정육각형의 모든 각이 돼요.","180° × 4 = 720°예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":125.3,"pts":{"ㄱ":[83.0,101.301270189],"ㄴ":[33.0,101.301270189],"ㄷ":[8.0,58.0],"ㄹ":[33.0,14.698729811],"ㅁ":[83.0,14.698729811],"ㅂ":[108.0,58.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"]]}],"tag":false}},{"stem":"정팔각형의 한 꼭짓점에서 대각선을 그어 삼각형 6개로 나누었어요. 정팔각형의 한 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["135"],"explanation":["모든 각의 합 = 180° × 6 = 1080°예요.","정팔각형은 각 8개의 크기가 모두 같아요.","1080° ÷ 8 = 135°예요."],"asset":{"type":"geo","items":[{"w":128.2,"h":128.2,"pts":{"ㄱ":[77.134171618,104.193976626],"ㄴ":[38.865828382,104.193976626],"ㄷ":[11.806023374,77.134171618],"ㄹ":[11.806023374,38.865828382],"ㅁ":[38.865828382,11.806023374],"ㅂ":[77.134171618,11.806023374],"ㅅ":[104.193976626,38.865828382],"ㅇ":[104.193976626,77.134171618]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅇ"]],"dash":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"],["ㄱ","ㅂ"],["ㄱ","ㅅ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L04_challenge#10','math',4,2,'u4','L04','g4_2_math_u4_L04_challenge','lesson_challenge','M4-2-u4-C4',4,'essay','teacher','아래 도형은 네 변의 길이가 모두 같아요. 이 도형이 정사각형인지 판단하고, 정다각형이 되려면 무엇을 더 확인해야 하는지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u4-C4","difficulty":4,"kind":"essay","stem":"아래 도형은 네 변의 길이가 모두 같아요. 이 도형이 정사각형인지 판단하고, 정다각형이 되려면 무엇을 더 확인해야 하는지 써 보세요.","answer_guide":{"answer":"예: 정사각형이 아니다. 네 변의 길이는 모두 같지만 네 각의 크기가 60°, 120°로 같지 않다. 정다각형이 되려면 변의 길이가 모두 같은 것뿐 아니라 각의 크기도 모두 같은지 확인해야 한다.","scoring_points":["정사각형이 아니라고 판단했는가","각의 크기가 같지 않다는 까닭을 썼는가","변의 길이와 각의 크기를 모두 확인해야 한다고 썼는가"]},"explanation":["네 변은 같지만 각은 60°, 120°예요.","정다각형은 변과 각이 모두 같아야 해요.","그래서 정사각형이 아니에요."],"asset":{"type":"geo","items":[{"w":160.0,"h":106.7,"poly":[[[10.0,82.746133918],[94.0,82.746133918],[136.0,10.0],[52.0,10.0]]],"tick":[[[10.0,82.746133918],[94.0,82.746133918],1],[[94.0,82.746133918],[136.0,10.0],1],[[136.0,10.0],[52.0,10.0],1],[[52.0,10.0],[10.0,82.746133918],1]],"lab":[[[23.9,74.7],"60°"],[[84.0,65.4],"120°"],[[122.1,18.0],"60°"],[[62.0,27.3],"120°"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_basic#1','math',4,2,'u4','L05','g4_2_math_u4_L05_basic','lesson_basic','M4-2-u4-C6',1,'mc','auto','대각선은 어떤 선분인가요?',ARRAY['M4-2-u4-X11','M4-2-u4-X12']::text[],true,'{"seq":1,"concept":"M4-2-u4-C6","difficulty":1,"kind":"mc","stem":"대각선은 어떤 선분인가요?","options":[{"t":"서로 이웃하지 않는 두 꼭짓점을 이은 선분","correct":true},{"t":"이웃한 두 꼭짓점을 이은 선분","mis":"M4-2-u4-X11"},{"t":"꼭짓점과 변의 가운데를 이은 선분","mis":"M4-2-u4-X12"},{"t":"도형을 가로지르는 모든 선","mis":"M4-2-u4-X12"}],"explanation":["조각보의 네모난 조각에서 마주 보는 꼭짓점끼리 이은 선처럼","서로 이웃하지 않는 두 꼭짓점을 이은 선분이 대각선이에요.","이웃한 꼭짓점을 이으면 변이고, 두 끝이 모두 꼭짓점이어야 해요."],"variant_rule":{"alt":[{"stem":"다각형에서 서로 이웃하지 않는 두 꼭짓점을 이은 선분을 무엇이라고 하나요?","options":[{"t":"대각선","correct":true},{"t":"변","mis":"M4-2-u4-X11"},{"t":"수선","mis":"M4-2-u4-X12"},{"t":"정다각형","mis":"M4-2-u4-X12"}],"explanation":["조각보의 네모난 조각에서 마주 보는 꼭짓점끼리 이은 선처럼","서로 이웃하지 않는 두 꼭짓점을 이은 선분이 대각선이에요.","이웃한 꼭짓점을 이으면 변이고, 두 끝이 모두 꼭짓점이어야 해요."],"asset":null},{"stem":"대각선을 바르게 그은 것은 어느 것인가요?","options":[{"t":"이웃하지 않는 두 꼭짓점을 이은 것","correct":true},{"t":"이웃한 두 꼭짓점을 이은 것","mis":"M4-2-u4-X11"},{"t":"꼭짓점과 변의 가운데를 이은 것","mis":"M4-2-u4-X12"},{"t":"변을 도형 밖으로 늘인 것","mis":"M4-2-u4-X12"}],"explanation":["조각보의 네모난 조각에서 마주 보는 꼭짓점끼리 이은 선처럼","서로 이웃하지 않는 두 꼭짓점을 이은 선분이 대각선이에요.","이웃한 꼭짓점을 이으면 변이고, 두 끝이 모두 꼭짓점이어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_basic#2','math',4,2,'u4','L05','g4_2_math_u4_L05_basic','lesson_basic','M4-2-u4-C6',1,'mc','auto','오각형 ㄱㄴㄷㄹㅁ에서 대각선은 어느 것인가요?',ARRAY['M4-2-u4-X11']::text[],true,'{"seq":2,"concept":"M4-2-u4-C6","difficulty":1,"kind":"mc","stem":"오각형 ㄱㄴㄷㄹㅁ에서 대각선은 어느 것인가요?","options":[{"t":"선분 ㄱㄷ","correct":true},{"t":"선분 ㄱㄴ","mis":"M4-2-u4-X11"},{"t":"선분 ㄴㄷ","mis":"M4-2-u4-X11"},{"t":"선분 ㄷㄹ","mis":"M4-2-u4-X11"}],"explanation":["꼭짓점 ㄱ과 이웃한 꼭짓점은 ㄴ, ㅁ이에요.","이웃하지 않는 꼭짓점 ㄷ과 이은 선분 ㄱㄷ이 대각선이에요.","이웃한 꼭짓점끼리 이은 선분은 변이에요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[9.5,85.5],"ㄴ":[9.5,38],"ㄷ":[57,9.5],"ㄹ":[104.5,38],"ㅁ":[104.5,85.5]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ에서 대각선은 어느 것인가요?","options":[{"t":"선분 ㄴㄹ","correct":true},{"t":"선분 ㄴㄷ","mis":"M4-2-u4-X11"},{"t":"선분 ㄷㄹ","mis":"M4-2-u4-X11"},{"t":"선분 ㄹㅁ","mis":"M4-2-u4-X11"}],"explanation":["꼭짓점 ㄴ과 이웃한 꼭짓점은 ㄷ, ㄱ이에요.","이웃하지 않는 꼭짓점 ㄹ과 이은 선분 ㄴㄹ이 대각선이에요.","이웃한 꼭짓점끼리 이은 선분은 변이에요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[9.5,38],"ㄴ":[57,9.5],"ㄷ":[104.5,38],"ㄹ":[104.5,66.5],"ㅁ":[57,85.5],"ㅂ":[9.5,66.5]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false}},{"stem":"사각형 ㄱㄴㄷㄹ에서 대각선은 어느 것인가요?","options":[{"t":"선분 ㄷㄱ","correct":true},{"t":"선분 ㄷㄹ","mis":"M4-2-u4-X11"},{"t":"선분 ㄹㄱ","mis":"M4-2-u4-X11"},{"t":"선분 ㄱㄴ","mis":"M4-2-u4-X11"}],"explanation":["꼭짓점 ㄷ과 이웃한 꼭짓점은 ㄹ, ㄴ이에요.","이웃하지 않는 꼭짓점 ㄱ과 이은 선분 ㄷㄱ이 대각선이에요.","이웃한 꼭짓점끼리 이은 선분은 변이에요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[19,19],"ㄴ":[95,9.5],"ㄷ":[104.5,85.5],"ㄹ":[9.5,76]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem