INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_basic#3','math',4,2,'u4','L05','g4_2_math_u4_L05_basic','lesson_basic','M4-2-u4-C6',1,'mc','auto','대각선을 그을 수 없는 다각형은 어느 것인가요?',ARRAY['M4-2-u4-X14']::text[],true,'{"seq":3,"concept":"M4-2-u4-C6","difficulty":1,"kind":"mc","stem":"대각선을 그을 수 없는 다각형은 어느 것인가요?","options":[{"t":"삼각형","correct":true},{"t":"사각형","mis":"M4-2-u4-X14"},{"t":"오각형","mis":"M4-2-u4-X14"},{"t":"육각형","mis":"M4-2-u4-X14"}],"explanation":["삼각형은 어느 꼭짓점을 잡아도 나머지 두 꼭짓점이 모두 이웃한 꼭짓점이에요.","이웃하지 않는 꼭짓점이 없어요.","그래서 삼각형에는 대각선을 그을 수 없어요(0개)."],"variant_rule":{"alt":[{"stem":"삼각형에 대각선을 그을 수 없는 까닭은 무엇인가요?","options":[{"t":"어느 꼭짓점을 잡아도 나머지 두 꼭짓점이 모두 이웃해서","correct":true},{"t":"변이 너무 짧아서","mis":"M4-2-u4-X14"},{"t":"각이 너무 뾰족해서","mis":"M4-2-u4-X02"},{"t":"삼각형은 다각형이 아니라서","mis":"M4-2-u4-X03"}],"explanation":["삼각형은 어느 꼭짓점을 잡아도 나머지 두 꼭짓점이 모두 이웃한 꼭짓점이에요.","이웃하지 않는 꼭짓점이 없어요.","그래서 삼각형에는 대각선을 그을 수 없어요(0개)."],"asset":null},{"stem":"대각선의 수가 0개인 다각형은 어느 것인가요?","options":[{"t":"삼각형","correct":true},{"t":"사각형","mis":"M4-2-u4-X14"},{"t":"정사각형","mis":"M4-2-u4-X14"},{"t":"오각형","mis":"M4-2-u4-X13"}],"explanation":["삼각형은 어느 꼭짓점을 잡아도 나머지 두 꼭짓점이 모두 이웃한 꼭짓점이에요.","이웃하지 않는 꼭짓점이 없어요.","그래서 삼각형에는 대각선을 그을 수 없어요(0개)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_basic#4','math',4,2,'u4','L05','g4_2_math_u4_L05_basic','lesson_basic','M4-2-u4-C7',1,'sa','auto','사각형에 대각선을 모두 그었어요. 대각선은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u4-C7","difficulty":1,"kind":"sa","stem":"사각형에 대각선을 모두 그었어요. 대각선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["한 꼭짓점을 잡고 이웃하지 않는 꼭짓점을 차례로 이어요.","이미 그은 대각선은 다시 세지 않아요.","사각형의 대각선은 2개예요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[19,19],"ㄴ":[95,9.5],"ㄷ":[104.5,85.5],"ㄹ":[9.5,76]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"dash":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"오각형에 대각선을 모두 그었어요. 대각선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 꼭짓점을 잡고 이웃하지 않는 꼭짓점을 차례로 이어요.","이미 그은 대각선은 다시 세지 않아요.","오각형의 대각선은 5개예요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[19,9.5],"ㄴ":[95,19],"ㄷ":[104.5,66.5],"ㄹ":[57,85.5],"ㅁ":[9.5,57]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"dash":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄴ","ㄹ"],["ㄴ","ㅁ"],["ㄷ","ㅁ"]]}],"tag":false}},{"stem":"육각형에 대각선을 모두 그었어요. 대각선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 꼭짓점을 잡고 이웃하지 않는 꼭짓점을 차례로 이어요.","이미 그은 대각선은 다시 세지 않아요.","육각형의 대각선은 9개예요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[28.5,9.5],"ㄴ":[85.5,9.5],"ㄷ":[104.5,47.5],"ㄹ":[85.5,85.5],"ㅁ":[28.5,85.5],"ㅂ":[9.5,47.5]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"],["ㄴ","ㄹ"],["ㄴ","ㅁ"],["ㄴ","ㅂ"],["ㄷ","ㅁ"],["ㄷ","ㅂ"],["ㄹ","ㅂ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
