INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_basic#6','math',4,2,'u4','L05','g4_2_math_u4_L05_basic','lesson_basic','M4-2-u4-C7',2,'sa','auto','오각형에 그을 수 있는 대각선은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u4-C7","difficulty":2,"kind":"sa","stem":"오각형에 그을 수 있는 대각선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 꼭짓점을 잡고 이웃하지 않는 꼭짓점을 차례로 이어요.","이미 그은 대각선은 다시 세지 않아요.","오각형의 대각선은 5개예요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[19,9.5],"ㄴ":[95,19],"ㄷ":[104.5,66.5],"ㄹ":[57,85.5],"ㅁ":[9.5,57]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"사각형에 그을 수 있는 대각선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["한 꼭짓점을 잡고 이웃하지 않는 꼭짓점을 차례로 이어요.","이미 그은 대각선은 다시 세지 않아요.","사각형의 대각선은 2개예요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[19,19],"ㄴ":[95,9.5],"ㄷ":[104.5,85.5],"ㄹ":[9.5,76]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}},{"stem":"육각형에 그을 수 있는 대각선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 꼭짓점을 잡고 이웃하지 않는 꼭짓점을 차례로 이어요.","이미 그은 대각선은 다시 세지 않아요.","육각형의 대각선은 9개예요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[9.5,38],"ㄴ":[57,9.5],"ㄷ":[104.5,38],"ㄹ":[104.5,66.5],"ㅁ":[57,85.5],"ㅂ":[9.5,66.5]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_basic#7','math',4,2,'u4','L05','g4_2_math_u4_L05_basic','lesson_basic','M4-2-u4-C7',2,'sa','auto','육각형의 한 꼭짓점에서 그을 수 있는 대각선은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u4-C7","difficulty":2,"kind":"sa","stem":"육각형의 한 꼭짓점에서 그을 수 있는 대각선은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["한 꼭짓점에서 자기 자신과 이웃한 꼭짓점 2개에는 대각선을 그을 수 없어요.","6 − 3 = 3개의 꼭짓점과 이을 수 있어요.","한 꼭짓점에서 대각선은 3개예요."],"variant_rule":{"alt":[{"stem":"팔각형의 한 꼭짓점에서 그을 수 있는 대각선은 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 꼭짓점에서 자기 자신과 이웃한 꼭짓점 2개에는 대각선을 그을 수 없어요.","8 − 3 = 5개의 꼭짓점과 이을 수 있어요.","한 꼭짓점에서 대각선은 5개예요."],"asset":null},{"stem":"칠각형의 한 꼭짓점에서 그을 수 있는 대각선은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 꼭짓점에서 자기 자신과 이웃한 꼭짓점 2개에는 대각선을 그을 수 없어요.","7 − 3 = 4개의 꼭짓점과 이을 수 있어요.","한 꼭짓점에서 대각선은 4개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_basic#8','math',4,2,'u4','L05','g4_2_math_u4_L05_basic','lesson_basic','M4-2-u4-C7',2,'ox','auto','사각형은 모양이 달라도 대각선을 2개 그을 수 있어요.',ARRAY['M4-2-u4-X13']::text[],true,'{"seq":8,"concept":"M4-2-u4-C7","difficulty":2,"kind":"ox","stem":"사각형은 모양이 달라도 대각선을 2개 그을 수 있어요.","answer":"O","reason_options":[{"t":"어느 사각형이든 마주 보는 꼭짓점 두 쌍을 이으니까","correct":true},{"t":"큰 사각형일수록 대각선이 많아서","mis":"M4-2-u4-X13"}],"mis":"M4-2-u4-X13","explanation":["대각선은 모든 꼭짓점에서 빠짐없이 그어 세요.","같은 대각선을 두 번 세지 않아요.","사각형은 언제나 2개, 오각형은 5개예요."],"variant_rule":{"alt":[{"stem":"정사각형에만 대각선을 2개 그을 수 있어요.","answer":"X","reason_options":[{"t":"모든 사각형에 대각선을 2개 그을 수 있어서","correct":true},{"t":"반듯한 사각형만 대각선이 2개라서","mis":"M4-2-u4-X05"}],"explanation":["대각선은 모든 꼭짓점에서 빠짐없이 그어 세요.","같은 대각선을 두 번 세지 않아요.","사각형은 언제나 2개, 오각형은 5개예요."],"asset":null},{"stem":"한 꼭짓점에서 그은 대각선의 수가 그 다각형의 대각선 수예요.","answer":"X","reason_options":[{"t":"다른 꼭짓점에서 그은 대각선도 함께 세야 해서","correct":true},{"t":"한 꼭짓점에서 그은 것만 세면 되어서","mis":"M4-2-u4-X13"}],"explanation":["대각선은 모든 꼭짓점에서 빠짐없이 그어 세요.","같은 대각선을 두 번 세지 않아요.","사각형은 언제나 2개, 오각형은 5개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_basic#9','math',4,2,'u4','L05','g4_2_math_u4_L05_basic','lesson_basic','M4-2-u4-C7',2,'sa','auto','직사각형 ㄱㄴㄷㄹ에서 대각선 ㄱㄷ의 길이가 10 cm예요. 대각선 ㄴㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u4-C7","difficulty":2,"kind":"sa","stem":"직사각형 ㄱㄴㄷㄹ에서 대각선 ㄱㄷ의 길이가 10 cm예요. 대각선 ㄴㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["직사각형의 두 대각선은 길이가 같아요.","대각선 ㄱㄷ = 대각선 ㄴㄹ이에요.","대각선 ㄴㄹ은 10 cm예요."],"asset":{"type":"geo","items":[{"w":125,"h":95,"pts":{"ㄱ":[10,10],"ㄴ":[110,10],"ㄷ":[110,70],"ㄹ":[10,70],"ㅇ":[60.0,40.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"show":["ㄱ","ㄴ","ㄷ","ㄹ"],"right":[["ㄹ","ㄱ","ㄴ"],["ㄱ","ㄴ","ㄷ"],["ㄴ","ㄷ","ㄹ"],["ㄷ","ㄹ","ㄱ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"정사각형 ㄱㄴㄷㄹ의 두 대각선이 만나는 점이 ㅇ이에요. 대각선 ㄴㄹ의 길이가 14 cm일 때 선분 ㄱㅇ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["정사각형의 두 대각선은 길이가 같고, 서로를 똑같이 반으로 나눠요.","선분 ㄱㅇ은 대각선 ㄱㄷ의 반이고, 대각선 ㄱㄷ = 대각선 ㄴㄹ = 14 cm예요.","14 ÷ 2 = 7 cm예요."],"asset":{"type":"geo","items":[{"w":100,"h":95,"pts":{"ㄱ":[10,10],"ㄴ":[80,10],"ㄷ":[80,80],"ㄹ":[10,80],"ㅇ":[45.0,45.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"show":["ㄱ","ㄴ","ㄷ","ㄹ","ㅇ"],"tick":[["ㄱ","ㄴ",1],["ㄴ","ㄷ",1],["ㄷ","ㄹ",1],["ㄹ","ㄱ",1]]}],"tag":false}},{"stem":"마름모 ㄱㄴㄷㄹ의 두 대각선이 만나는 점이 ㅇ이에요. 두 대각선이 만나서 이루는 각 ㄱㅇㄴ은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["마름모의 두 대각선은 서로 수직으로 만나요.","수직으로 만나서 이루는 각은 직각이에요.","각 ㄱㅇㄴ은 90°예요."],"asset":{"type":"geo","items":[{"w":100,"h":95,"pts":{"ㄱ":[55,8],"ㄴ":[95,48],"ㄷ":[55,88],"ㄹ":[15,48],"ㅇ":[55.0,48.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"show":["ㄱ","ㄴ","ㄷ","ㄹ","ㅇ"],"tick":[["ㄱ","ㄴ",1],["ㄴ","ㄷ",1],["ㄷ","ㄹ",1],["ㄹ","ㄱ",1]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_basic#10','math',4,2,'u4','L05','g4_2_math_u4_L05_basic','lesson_basic','M4-2-u4-C7',3,'sa','auto','오각형의 대각선의 수와 육각형의 대각선의 수를 더하면 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u4-C7","difficulty":3,"kind":"sa","stem":"오각형의 대각선의 수와 육각형의 대각선의 수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["대각선은 한 꼭짓점에서 (변의 수 − 3)개씩 그어 모두 모은 뒤 겹친 것을 빼요.","오각형 5개, 육각형 9개예요.","5 + 9 = 14개예요."],"variant_rule":{"alt":[{"stem":"팔각형의 변의 수와 팔각형에 그을 수 있는 대각선의 수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["대각선은 한 꼭짓점에서 (변의 수 − 3)개씩 그어 모두 모은 뒤 겹친 것을 빼요.","변 8개, 대각선 20개예요.","8 + 20 = 28개예요."],"asset":null},{"stem":"사각형의 대각선의 수와 칠각형의 대각선의 수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["대각선은 한 꼭짓점에서 (변의 수 − 3)개씩 그어 모두 모은 뒤 겹친 것을 빼요.","사각형 2개, 칠각형 14개예요.","2 + 14 = 16개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_challenge#1','math',4,2,'u4','L05','g4_2_math_u4_L05_challenge','lesson_challenge','M4-2-u4-C6',2,'mc','auto','육각형 안에 선분 ㉠, ㉡, ㉢, ㉣을 그었어요. 대각선은 어느 것인가요?',ARRAY['M4-2-u4-X12']::text[],true,'{"seq":1,"concept":"M4-2-u4-C6","difficulty":2,"kind":"mc","stem":"육각형 안에 선분 ㉠, ㉡, ㉢, ㉣을 그었어요. 대각선은 어느 것인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M4-2-u4-X12"},{"t":"㉢","mis":"M4-2-u4-X12"},{"t":"㉣","mis":"M4-2-u4-X12"}],"explanation":["대각선은 두 끝이 모두 꼭짓점이고, 두 꼭짓점이 서로 이웃하지 않아야 해요.","㉡만 두 끝이 모두 꼭짓점이에요.","변의 가운데나 도형 안의 점과 이은 선분은 대각선이 아니에요."],"asset":{"type":"geo","items":[{"w":145.0,"h":123.0,"poly":[[[11.0,44],[66,11.0],[121.0,44],[121.0,77.0],[66,99.0],[11.0,77.0]]],"seg":[[[11.0,44],[72.0,54.666667]],[[121.0,77.0],[11.0,77.0]],[[66,99.0],[38.5,27.5]],[[93.5,88.0],[11.0,60.5]]],"lab":[[[39.3,40.7],"㉠"],[[78.5,70.0],"㉡"],[[57.9,52.7],"㉢"],[[46.9,63.1],"㉣"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"사각형 안에 선분 ㉠, ㉡, ㉢, ㉣을 그었어요. 대각선은 어느 것인가요?","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"M4-2-u4-X12"},{"t":"㉢","mis":"M4-2-u4-X12"},{"t":"㉣","mis":"M4-2-u4-X12"}],"explanation":["대각선은 두 끝이 모두 꼭짓점이고, 두 꼭짓점이 서로 이웃하지 않아야 해요.","㉠만 두 끝이 모두 꼭짓점이에요.","변의 가운데나 도형 안의 점과 이은 선분은 대각선이 아니에요."],"asset":{"type":"geo","items":[{"w":145.0,"h":123.0,"poly":[[[22,22],[110,11.0],[121.0,99.0],[11.0,88]]],"seg":[[[22,22],[121.0,99.0]],[[110,11.0],[16.5,55.0]],[[66.0,16.5],[66.0,93.5]],[[11.0,88],[72.0,51.0]]],"lab":[[[63.6,42.0],"㉠"],[[74.9,23.8],"㉡"],[[73.0,51.9],"㉢"],[[57.6,57.0],"㉣"]]}],"tag":false}},{"stem":"칠각형 안에 선분 ㉠, ㉡, ㉢, ㉣을 그었어요. 대각선은 어느 것인가요?","options":[{"t":"㉣","correct":true},{"t":"㉠","mis":"M4-2-u4-X12"},{"t":"㉡","mis":"M4-2-u4-X12"},{"t":"㉢","mis":"M4-2-u4-X12"}],"explanation":["대각선은 두 끝이 모두 꼭짓점이고, 두 꼭짓점이 서로 이웃하지 않아야 해요.","㉣만 두 끝이 모두 꼭짓점이에요.","변의 가운데나 도형 안의 점과 이은 선분은 대각선이 아니에요."],"asset":{"type":"geo","items":[{"w":145.0,"h":123.0,"poly":[[[44,11.0],[88,11.0],[121.0,39.6],[116.6,79.2],[79.2,99.0],[35.2,94.6],[11.0,55.0]]],"seg":[[[11.0,55.0],[104.5,25.3]],[[23.1,74.8],[66.0,11.0]],[[88,11.0],[76.714286,51.628571]],[[35.2,94.6],[44,11.0]]],"lab":[[[50.7,37.6],"㉠"],[[49.4,39.1],"㉡"],[[88.8,26.3],"㉢"],[[47.9,33.3],"㉣"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_challenge#2','math',4,2,'u4','L05','g4_2_math_u4_L05_challenge','lesson_challenge','M4-2-u4-C7',2,'sa','auto','오각형의 한 꼭짓점에서 그을 수 있는 대각선은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u4-C7","difficulty":2,"kind":"sa","stem":"오각형의 한 꼭짓점에서 그을 수 있는 대각선은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["한 꼭짓점에서 자기 자신과 이웃한 꼭짓점 2개에는 대각선을 그을 수 없어요.","5 − 3 = 2개의 꼭짓점과 이을 수 있어요.","한 꼭짓점에서 대각선은 2개예요."],"variant_rule":{"alt":[{"stem":"구각형의 한 꼭짓점에서 그을 수 있는 대각선은 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 꼭짓점에서 자기 자신과 이웃한 꼭짓점 2개에는 대각선을 그을 수 없어요.","9 − 3 = 6개의 꼭짓점과 이을 수 있어요.","한 꼭짓점에서 대각선은 6개예요."],"asset":null},{"stem":"십각형의 한 꼭짓점에서 그을 수 있는 대각선은 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 꼭짓점에서 자기 자신과 이웃한 꼭짓점 2개에는 대각선을 그을 수 없어요.","10 − 3 = 7개의 꼭짓점과 이을 수 있어요.","한 꼭짓점에서 대각선은 7개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_challenge#3','math',4,2,'u4','L05','g4_2_math_u4_L05_challenge','lesson_challenge','M4-2-u4-C7',3,'mc','auto','두 대각선의 길이가 항상 같은 사각형은 어느 것인가요?',ARRAY['M4-2-u4-X15']::text[],true,'{"seq":3,"concept":"M4-2-u4-C7","difficulty":3,"kind":"mc","stem":"두 대각선의 길이가 항상 같은 사각형은 어느 것인가요?","options":[{"t":"직사각형","correct":true},{"t":"마름모","mis":"M4-2-u4-X15"},{"t":"평행사변형","mis":"M4-2-u4-X15"},{"t":"사다리꼴","mis":"M4-2-u4-X15"}],"explanation":["직사각형·정사각형은 두 대각선의 길이가 같아요.","마름모·정사각형은 두 대각선이 수직으로 만나요.","두 성질을 따로 확인해요 — 둘 다 갖춘 것은 정사각형이에요."],"variant_rule":{"alt":[{"stem":"두 대각선이 항상 서로 수직으로 만나는 사각형은 어느 것인가요?","options":[{"t":"마름모","correct":true},{"t":"직사각형","mis":"M4-2-u4-X15"},{"t":"평행사변형","mis":"M4-2-u4-X15"},{"t":"사다리꼴","mis":"M4-2-u4-X15"}],"explanation":["직사각형·정사각형은 두 대각선의 길이가 같아요.","마름모·정사각형은 두 대각선이 수직으로 만나요.","두 성질을 따로 확인해요 — 둘 다 갖춘 것은 정사각형이에요."],"asset":null},{"stem":"두 대각선의 길이가 같고 서로 수직으로 만나는 사각형은 어느 것인가요?","options":[{"t":"정사각형","correct":true},{"t":"직사각형","mis":"M4-2-u4-X15"},{"t":"마름모","mis":"M4-2-u4-X15"},{"t":"평행사변형","mis":"M4-2-u4-X15"}],"explanation":["직사각형·정사각형은 두 대각선의 길이가 같아요.","마름모·정사각형은 두 대각선이 수직으로 만나요.","두 성질을 따로 확인해요 — 둘 다 갖춘 것은 정사각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_challenge#4','math',4,2,'u4','L05','g4_2_math_u4_L05_challenge','lesson_challenge','M4-2-u4-C7',3,'error','auto','대각선에 대해 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u4-X13','M4-2-u4-X20']::text[],true,'{"seq":4,"concept":"M4-2-u4-C7","difficulty":3,"kind":"error","stem":"대각선에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「육각형은 한 꼭짓점에서 대각선을 3개 그을 수 있으니까 대각선이 모두 3개야.」","correct":true,"mis_target":"M4-2-u4-X13"},{"t":"은우 — 「삼각형에는 대각선이 없어.」","mis":"M4-2-u4-X20"},{"t":"하랑 — 「사각형은 모양이 달라도 대각선이 2개야.」","mis":"M4-2-u4-X20"},{"t":"지아 — 「대각선은 이웃하지 않는 두 꼭짓점을 이어.」","mis":"M4-2-u4-X20"}],"explanation":["대각선은 이웃하지 않는 두 꼭짓점을 이은 선분이에요.","시우의 말은 대각선의 뜻이나 세는 방법과 맞지 않아요.","모든 꼭짓점에서 그어 빠짐없이, 겹친 것은 한 번만 세요."],"variant_rule":{"alt":[{"stem":"대각선에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「사각형의 변도 꼭짓점끼리 이었으니 대각선이야.」","correct":true,"mis_target":"M4-2-u4-X11"},{"t":"하랑 — 「사각형은 모양이 달라도 대각선이 2개야.」","mis":"M4-2-u4-X20"},{"t":"지아 — 「대각선은 이웃하지 않는 두 꼭짓점을 이어.」","mis":"M4-2-u4-X20"},{"t":"준서 — 「오각형의 대각선은 5개야.」","mis":"M4-2-u4-X20"}],"explanation":["대각선은 이웃하지 않는 두 꼭짓점을 이은 선분이에요.","은우의 말은 대각선의 뜻이나 세는 방법과 맞지 않아요.","모든 꼭짓점에서 그어 빠짐없이, 겹친 것은 한 번만 세요."],"asset":null},{"stem":"대각선에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「꼭짓점에서 마주 보는 변의 가운데까지 이은 선분도 대각선이야.」","correct":true,"mis_target":"M4-2-u4-X12"},{"t":"지아 — 「대각선은 이웃하지 않는 두 꼭짓점을 이어.」","mis":"M4-2-u4-X20"},{"t":"준서 — 「오각형의 대각선은 5개야.」","mis":"M4-2-u4-X20"},{"t":"민서 — 「삼각형에는 대각선이 없어.」","mis":"M4-2-u4-X20"}],"explanation":["대각선은 이웃하지 않는 두 꼭짓점을 이은 선분이에요.","하랑의 말은 대각선의 뜻이나 세는 방법과 맞지 않아요.","모든 꼭짓점에서 그어 빠짐없이, 겹친 것은 한 번만 세요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_challenge#5','math',4,2,'u4','L05','g4_2_math_u4_L05_challenge','lesson_challenge','M4-2-u4-C7',3,'sa','auto','직사각형 ㄱㄴㄷㄹ의 두 대각선이 만나는 점이 ㅇ이에요. 선분 ㄱㅇ의 길이가 6 cm일 때 대각선 ㄴㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u4-C7","difficulty":3,"kind":"sa","stem":"직사각형 ㄱㄴㄷㄹ의 두 대각선이 만나는 점이 ㅇ이에요. 선분 ㄱㅇ의 길이가 6 cm일 때 대각선 ㄴㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["직사각형의 두 대각선은 서로를 반으로 나누고, 길이가 같아요.","대각선 ㄱㄷ = 6 × 2 = 12 cm예요.","대각선 ㄴㄹ도 12 cm예요."],"asset":{"type":"geo","items":[{"w":125,"h":95,"pts":{"ㄱ":[10,10],"ㄴ":[110,10],"ㄷ":[110,70],"ㄹ":[10,70],"ㅇ":[60.0,40.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"show":["ㄱ","ㄴ","ㄷ","ㄹ","ㅇ"],"right":[["ㄹ","ㄱ","ㄴ"],["ㄱ","ㄴ","ㄷ"],["ㄴ","ㄷ","ㄹ"],["ㄷ","ㄹ","ㄱ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"정사각형 ㄱㄴㄷㄹ의 두 대각선이 만나는 점이 ㅇ이에요. 대각선 ㄴㄹ의 길이가 12 cm일 때 선분 ㄱㅇ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["정사각형의 두 대각선은 길이가 같고, 서로를 똑같이 반으로 나눠요.","선분 ㄱㅇ은 대각선 ㄱㄷ의 반이고, 대각선 ㄱㄷ = 대각선 ㄴㄹ = 12 cm예요.","12 ÷ 2 = 6 cm예요."],"asset":{"type":"geo","items":[{"w":100,"h":95,"pts":{"ㄱ":[10,10],"ㄴ":[80,10],"ㄷ":[80,80],"ㄹ":[10,80],"ㅇ":[45.0,45.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"show":["ㄱ","ㄴ","ㄷ","ㄹ","ㅇ"],"tick":[["ㄱ","ㄴ",1],["ㄴ","ㄷ",1],["ㄷ","ㄹ",1],["ㄹ","ㄱ",1]]}],"tag":false}},{"stem":"직사각형 ㄱㄴㄷㄹ에서 대각선 ㄱㄷ의 길이가 16 cm예요. 대각선 ㄴㄹ의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["직사각형의 두 대각선은 길이가 같아요.","대각선 ㄱㄷ = 대각선 ㄴㄹ이에요.","대각선 ㄴㄹ은 16 cm예요."],"asset":{"type":"geo","items":[{"w":125,"h":95,"pts":{"ㄱ":[10,10],"ㄴ":[110,10],"ㄷ":[110,70],"ㄹ":[10,70],"ㅇ":[60.0,40.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]],"show":["ㄱ","ㄴ","ㄷ","ㄹ"],"right":[["ㄹ","ㄱ","ㄴ"],["ㄱ","ㄴ","ㄷ"],["ㄴ","ㄷ","ㄹ"],["ㄷ","ㄹ","ㄱ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_challenge#6','math',4,2,'u4','L05','g4_2_math_u4_L05_challenge','lesson_challenge','M4-2-u4-C7',3,'sa','auto','육각형의 변의 수와 육각형에 그을 수 있는 대각선의 수를 더하면 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u4-C7","difficulty":3,"kind":"sa","stem":"육각형의 변의 수와 육각형에 그을 수 있는 대각선의 수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["대각선은 한 꼭짓점에서 (변의 수 − 3)개씩 그어 모두 모은 뒤 겹친 것을 빼요.","변 6개, 대각선 9개예요.","6 + 9 = 15개예요."],"variant_rule":{"alt":[{"stem":"오각형의 대각선의 수와 팔각형의 대각선의 수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["대각선은 한 꼭짓점에서 (변의 수 − 3)개씩 그어 모두 모은 뒤 겹친 것을 빼요.","오각형 5개, 팔각형 20개예요.","5 + 20 = 25개예요."],"asset":null},{"stem":"칠각형의 변의 수와 칠각형에 그을 수 있는 대각선의 수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["대각선은 한 꼭짓점에서 (변의 수 − 3)개씩 그어 모두 모은 뒤 겹친 것을 빼요.","변 7개, 대각선 14개예요.","7 + 14 = 21개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_challenge#7','math',4,2,'u4','L05','g4_2_math_u4_L05_challenge','lesson_challenge','M4-2-u4-C7',3,'sa','auto','칠각형의 한 꼭짓점에서 대각선을 4개 그을 수 있어요. 꼭짓점 7개에서 모두 그은 뒤 겹친 것을 한 번만 세면 대각선은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u4-C7","difficulty":3,"kind":"sa","stem":"칠각형의 한 꼭짓점에서 대각선을 4개 그을 수 있어요. 꼭짓점 7개에서 모두 그은 뒤 겹친 것을 한 번만 세면 대각선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["꼭짓점마다 4개씩: 4 × 7 = 28개예요.","대각선 하나를 양 끝 꼭짓점에서 두 번 세었어요.","28 ÷ 2 = 14개예요."],"variant_rule":{"alt":[{"stem":"팔각형의 한 꼭짓점에서 대각선을 5개 그을 수 있어요. 꼭짓점 8개에서 모두 그은 뒤 겹친 것을 한 번만 세면 대각선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["꼭짓점마다 5개씩: 5 × 8 = 40개예요.","대각선 하나를 양 끝 꼭짓점에서 두 번 세었어요.","40 ÷ 2 = 20개예요."],"asset":null},{"stem":"구각형의 한 꼭짓점에서 대각선을 6개 그을 수 있어요. 꼭짓점 9개에서 모두 그은 뒤 겹친 것을 한 번만 세면 대각선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["꼭짓점마다 6개씩: 6 × 9 = 54개예요.","대각선 하나를 양 끝 꼭짓점에서 두 번 세었어요.","54 ÷ 2 = 27개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_challenge#8','math',4,2,'u4','L05','g4_2_math_u4_L05_challenge','lesson_challenge','M4-2-u4-C7',4,'mc','auto','대각선을 모두 14개 그을 수 있는 다각형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X13']::text[],true,'{"seq":8,"concept":"M4-2-u4-C7","difficulty":4,"kind":"mc","stem":"대각선을 모두 14개 그을 수 있는 다각형의 이름은 무엇인가요?","options":[{"t":"칠각형","correct":true},{"t":"육각형","mis":"M4-2-u4-X13"},{"t":"팔각형","mis":"M4-2-u4-X13"},{"t":"삼각형","mis":"M4-2-u4-X13"}],"explanation":["한 꼭짓점에서 (변의 수 − 3)개씩, 모두 모아 2로 나눠요.","칠각형: 7 × 4 ÷ 2 = 14개.","그래서 칠각형이에요."],"variant_rule":{"alt":[{"stem":"대각선을 모두 20개 그을 수 있는 다각형의 이름은 무엇인가요?","options":[{"t":"팔각형","correct":true},{"t":"칠각형","mis":"M4-2-u4-X13"},{"t":"구각형","mis":"M4-2-u4-X13"},{"t":"사각형","mis":"M4-2-u4-X13"}],"explanation":["한 꼭짓점에서 (변의 수 − 3)개씩, 모두 모아 2로 나눠요.","팔각형: 8 × 5 ÷ 2 = 20개.","그래서 팔각형이에요."],"asset":null},{"stem":"대각선을 모두 35개 그을 수 있는 다각형의 이름은 무엇인가요?","options":[{"t":"십각형","correct":true},{"t":"구각형","mis":"M4-2-u4-X13"},{"t":"십일각형","mis":"M4-2-u4-X13"},{"t":"오각형","mis":"M4-2-u4-X13"}],"explanation":["한 꼭짓점에서 (변의 수 − 3)개씩, 모두 모아 2로 나눠요.","십각형: 10 × 7 ÷ 2 = 35개.","그래서 십각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_challenge#9','math',4,2,'u4','L05','g4_2_math_u4_L05_challenge','lesson_challenge','M4-2-u4-C7',4,'sa','auto','친구 6명이 둥글게 앉았어요. 바로 옆에 앉은 친구를 빼고 다른 친구와만 한 번씩 악수를 하면 악수는 모두 몇 번인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u4-C7","difficulty":4,"kind":"sa","stem":"친구 6명이 둥글게 앉았어요. 바로 옆에 앉은 친구를 빼고 다른 친구와만 한 번씩 악수를 하면 악수는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["친구(나무)를 육각형의 꼭짓점, 옆끼리를 변이라고 생각해요.","옆이 아닌 둘을 잇는 것은 대각선과 같아요.","육각형의 대각선: 6 × 3 ÷ 2 = 9 — 9예요."],"variant_rule":{"alt":[{"stem":"공원에 나무 5그루가 둥글게 심어져 있어요. 바로 옆 나무끼리는 빼고, 나머지 나무끼리 두 그루씩 줄로 한 번씩 이으면 줄은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["친구(나무)를 오각형의 꼭짓점, 옆끼리를 변이라고 생각해요.","옆이 아닌 둘을 잇는 것은 대각선과 같아요.","오각형의 대각선: 5 × 2 ÷ 2 = 5 — 5예요."],"asset":null},{"stem":"친구 7명이 둥글게 앉았어요. 바로 옆에 앉은 친구를 빼고 다른 친구와만 한 번씩 악수를 하면 악수는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["친구(나무)를 칠각형의 꼭짓점, 옆끼리를 변이라고 생각해요.","옆이 아닌 둘을 잇는 것은 대각선과 같아요.","칠각형의 대각선: 7 × 4 ÷ 2 = 14 — 14예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L05_challenge#10','math',4,2,'u4','L05','g4_2_math_u4_L05_challenge','lesson_challenge','M4-2-u4-C7',4,'essay','teacher','육각형에 그을 수 있는 대각선의 수를 빠뜨리거나 두 번 세지 않고 구하는 방법을 쓰고, 대각선은 모두 몇 개인지 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u4-C7","difficulty":4,"kind":"essay","stem":"육각형에 그을 수 있는 대각선의 수를 빠뜨리거나 두 번 세지 않고 구하는 방법을 쓰고, 대각선은 모두 몇 개인지 구해 보세요.","answer_guide":{"answer":"예: 한 꼭짓점에서는 자기 자신과 이웃한 두 꼭짓점을 뺀 3개의 꼭짓점과 이을 수 있어 대각선이 3개이다. 꼭짓점이 6개이므로 3 × 6 = 18개인데, 대각선 하나를 양 끝에서 두 번 세었으므로 2로 나누면 18 ÷ 2 = 9개이다.","scoring_points":["한 꼭짓점에서 3개라고 썼는가","꼭짓점 6개에서 모두 세면 18개라고 썼는가","두 번 센 것을 2로 나누어 9개를 구했는가"]},"explanation":["한 꼭짓점에서 6 − 3 = 3개예요.","3 × 6 = 18 — 대각선마다 두 번 세었어요.","18 ÷ 2 = 9개예요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[28.5,9.5],"ㄴ":[85.5,9.5],"ㄷ":[104.5,47.5],"ㄹ":[85.5,85.5],"ㅁ":[28.5,85.5],"ㅂ":[9.5,47.5]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L06_basic#1','math',4,2,'u4','L06','g4_2_math_u4_L06_basic','lesson_basic','M4-2-u4-C8',1,'mc','auto','모양 조각을 이어 붙일 때 지켜야 할 것으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u4-X16','M4-2-u4-X18']::text[],true,'{"seq":1,"concept":"M4-2-u4-C8","difficulty":1,"kind":"mc","stem":"모양 조각을 이어 붙일 때 지켜야 할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"조각끼리 겹치지 않게 붙인다","correct":true},{"t":"조각끼리 겹치게 붙인다","mis":"M4-2-u4-X16"},{"t":"조각 사이를 넓게 벌린다","mis":"M4-2-u4-X16"},{"t":"같은 조각만 쓴다","mis":"M4-2-u4-X18"}],"explanation":["조각은 돌리거나 뒤집어도 돼요.","조각끼리 겹치지 않게, 길이가 같은 변끼리 맞대어 붙여요.","만든 모양은 쓴 조각과 그 수, 만든 도형의 이름(바깥쪽 변의 수)으로 설명해요."],"variant_rule":{"alt":[{"stem":"모양 조각을 맞대어 붙이는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"길이가 같은 변끼리 맞대어 붙인다","correct":true},{"t":"길이가 다른 변끼리 엇갈리게 붙인다","mis":"M4-2-u4-X16"},{"t":"꼭짓점 하나만 닿게 붙인다","mis":"M4-2-u4-X16"},{"t":"조각을 반쯤 겹쳐 붙인다","mis":"M4-2-u4-X16"}],"explanation":["조각은 돌리거나 뒤집어도 돼요.","조각끼리 겹치지 않게, 길이가 같은 변끼리 맞대어 붙여요.","만든 모양은 쓴 조각과 그 수, 만든 도형의 이름(바깥쪽 변의 수)으로 설명해요."],"asset":null},{"stem":"모양 조각으로 만든 모양을 설명하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"어떤 조각을 몇 개 썼는지와 만든 도형의 이름을 말한다","correct":true},{"t":"조각의 색깔만 말한다","mis":"M4-2-u4-X17"},{"t":"쓴 조각 수로 도형의 이름을 정한다","mis":"M4-2-u4-X17"},{"t":"조각끼리 맞댄 선까지 세어 이름을 정한다","mis":"M4-2-u4-X17"}],"explanation":["조각은 돌리거나 뒤집어도 돼요.","조각끼리 겹치지 않게, 길이가 같은 변끼리 맞대어 붙여요.","만든 모양은 쓴 조각과 그 수, 만든 도형의 이름(바깥쪽 변의 수)으로 설명해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L06_basic#2','math',4,2,'u4','L06','g4_2_math_u4_L06_basic','lesson_basic','M4-2-u4-C8',1,'sa','auto','모양 조각으로 사탕 모양을 만들었어요. 정삼각형 조각은 몇 개 썼나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u4-C8","difficulty":1,"kind":"sa","stem":"모양 조각으로 사탕 모양을 만들었어요. 정삼각형 조각은 몇 개 썼나요? 숫자로 쓰세요.","answer":["4"],"explanation":["정삼각형 조각의 모양을 떠올려요.","그림에서 그 모양인 조각을 하나씩 표시하며 세요.","정삼각형 조각은 4개예요."],"asset":{"type":"tiles","pieces":[{"p":[[1.5,-0.866],[1.0,-0.0],[2.0,0.0]]},{"p":[[1.0,-1.7321],[1.5,-0.866],[2.0,-1.7321]]},{"p":[[0.0,0.0],[1.0,0.0],[1.5,-0.866],[1.0,-1.7321],[0.0,-1.7321],[-0.5,-0.866]]},{"p":[[-0.5,-0.866],[0.0,-1.7321],[-1.0,-1.7321]]},{"p":[[0.0,0.0],[-0.5,-0.866],[-1.0,0.0]]}],"u":34},"variant_rule":{"alt":[{"stem":"모양 조각으로 꽃 모양을 만들었어요. 정삼각형 조각은 몇 개 썼나요? 숫자로 쓰세요.","answer":["6"],"explanation":["정삼각형 조각의 모양을 떠올려요.","그림에서 그 모양인 조각을 하나씩 표시하며 세요.","정삼각형 조각은 6개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.5,-0.866],[1.0,-1.7321],[0.0,-1.7321],[-0.5,-0.866]]},{"p":[[1.0,0.0],[0.0,0.0],[0.5,0.866]]},{"p":[[1.5,-0.866],[1.0,-0.0],[2.0,0.0]]},{"p":[[1.0,-1.7321],[1.5,-0.866],[2.0,-1.7321]]},{"p":[[0.0,-1.7321],[1.0,-1.7321],[0.5,-2.5981]]},{"p":[[-0.5,-0.866],[0.0,-1.7321],[-1.0,-1.7321]]},{"p":[[0.0,0.0],[-0.5,-0.866],[-1.0,0.0]]}],"u":34}},{"stem":"모양 조각으로 로켓 모양을 만들었어요. 정삼각형 조각은 몇 개 썼나요? 숫자로 쓰세요.","answer":["3"],"explanation":["정삼각형 조각의 모양을 떠올려요.","그림에서 그 모양인 조각을 하나씩 표시하며 세요.","정삼각형 조각은 3개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.0,-1.0],[0.0,-1.0]]},{"p":[[0.0,-1.0],[1.0,-1.0],[1.0,-2.0],[0.0,-2.0]]},{"p":[[0.0,-2.0],[1.0,-2.0],[0.5,-2.866]]},{"p":[[1.0,-1.0],[1.0,0.0],[1.866,-0.5]]},{"p":[[0.0,0.0],[0.0,-1.0],[-0.866,-0.5]]}],"u":34}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code