INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L06_basic#3','math',4,2,'u4','L06','g4_2_math_u4_L06_basic','lesson_basic','M4-2-u4-C8',1,'sa','auto','정육각형 조각 1개를 빈틈없이 덮으려면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u4-C8","difficulty":1,"kind":"sa","stem":"정육각형 조각 1개를 빈틈없이 덮으려면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["6"],"explanation":["정삼각형 조각을 하나의 단위로 생각해요.","정삼각형으로 덮으면 마름모 2개, 사다리꼴 3개, 정육각형 6개예요.","그래서 답은 6개예요."],"variant_rule":{"alt":[{"stem":"사다리꼴 조각 1개를 빈틈없이 덮으려면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["3"],"explanation":["정삼각형 조각을 하나의 단위로 생각해요.","정삼각형으로 덮으면 마름모 2개, 사다리꼴 3개, 정육각형 6개예요.","그래서 답은 3개예요."],"asset":null},{"stem":"마름모 조각 1개를 빈틈없이 덮으려면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["2"],"explanation":["정삼각형 조각을 하나의 단위로 생각해요.","정삼각형으로 덮으면 마름모 2개, 사다리꼴 3개, 정육각형 6개예요.","그래서 답은 2개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
