INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L06_basic#6','math',4,2,'u4','L06','g4_2_math_u4_L06_basic','lesson_basic','M4-2-u4-C8',2,'sa','auto','정삼각형 조각 2개를 이어 붙이면 마름모 조각 1개와 같은 모양이 돼요. 마름모 3개를 만들려면 정삼각형 조각은 모두 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u4-C8","difficulty":2,"kind":"sa","stem":"정삼각형 조각 2개를 이어 붙이면 마름모 조각 1개와 같은 모양이 돼요. 마름모 3개를 만들려면 정삼각형 조각은 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["6"],"explanation":["마름모 1개 = 정삼각형 2개예요.","마름모 3개는 정삼각형 2 × 3개예요.","2 × 3 = 6개예요."],"variant_rule":{"alt":[{"stem":"정삼각형 조각 3개를 이어 붙이면 사다리꼴 조각 1개와 같은 모양이 돼요. 사다리꼴 4개를 만들려면 정삼각형 조각은 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["12"],"explanation":["사다리꼴 1개 = 정삼각형 3개예요.","사다리꼴 4개는 정삼각형 3 × 4개예요.","3 × 4 = 12개예요."],"asset":null},{"stem":"정삼각형 조각 2개를 이어 붙이면 마름모 조각 1개와 같은 모양이 돼요. 마름모 5개를 만들려면 정삼각형 조각은 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["10"],"explanation":["마름모 1개 = 정삼각형 2개예요.","마름모 5개는 정삼각형 2 × 5개예요.","2 × 5 = 10개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L06_basic#7','math',4,2,'u4','L06','g4_2_math_u4_L06_basic','lesson_basic','M4-2-u4-C8',2,'ox','auto','같은 도형을 만드는 방법은 언제나 한 가지뿐이에요.',ARRAY['M4-2-u4-X18']::text[],true,'{"seq":7,"concept":"M4-2-u4-C8","difficulty":2,"kind":"ox","stem":"같은 도형을 만드는 방법은 언제나 한 가지뿐이에요.","answer":"X","reason_options":[{"t":"쓰는 조각과 붙이는 차례가 달라도 같은 도형을 만들 수 있어서","correct":true},{"t":"같은 도형이면 쓴 조각도 같아야 해서","mis":"M4-2-u4-X18"}],"mis":"M4-2-u4-X18","explanation":["같은 모양이라도 쓰는 조각과 붙이는 차례는 여러 가지예요.","마름모 = 정삼각형 2개, 사다리꼴 = 정삼각형 3개, 정육각형 = 정삼각형 6개예요.","겹치거나 빈틈 없이 같은 모양이면 모두 바른 방법이에요."],"variant_rule":{"alt":[{"stem":"정육각형은 사다리꼴 조각 2개로도, 마름모 조각 3개로도 만들 수 있어요.","answer":"O","reason_options":[{"t":"두 방법 모두 겹치거나 빈틈없이 정육각형이 되어서","correct":true},{"t":"정육각형은 정삼각형 조각으로만 만들 수 있어서","mis":"M4-2-u4-X18"}],"explanation":["같은 모양이라도 쓰는 조각과 붙이는 차례는 여러 가지예요.","마름모 = 정삼각형 2개, 사다리꼴 = 정삼각형 3개, 정육각형 = 정삼각형 6개예요.","겹치거나 빈틈 없이 같은 모양이면 모두 바른 방법이에요."],"asset":null},{"stem":"쓴 조각의 수가 다르면 같은 모양을 만들 수 없어요.","answer":"X","reason_options":[{"t":"조각 수가 달라도 같은 모양이 될 수 있어서","correct":true},{"t":"조각 수가 같아야 같은 모양이라서","mis":"M4-2-u4-X18"}],"explanation":["같은 모양이라도 쓰는 조각과 붙이는 차례는 여러 가지예요.","마름모 = 정삼각형 2개, 사다리꼴 = 정삼각형 3개, 정육각형 = 정삼각형 6개예요.","겹치거나 빈틈 없이 같은 모양이면 모두 바른 방법이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L06_basic#8','math',4,2,'u4','L06','g4_2_math_u4_L06_basic','lesson_basic','M4-2-u4-C8',2,'sa','auto','모양 조각으로 로켓 모양을 만들었어요. 정사각형 조각은 몇 개 썼나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u4-C8","difficulty":2,"kind":"sa","stem":"모양 조각으로 로켓 모양을 만들었어요. 정사각형 조각은 몇 개 썼나요? 숫자로 쓰세요.","answer":["2"],"explanation":["정사각형 조각의 모양을 떠올려요.","그림에서 그 모양인 조각을 하나씩 표시하며 세요.","정사각형 조각은 2개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.0,-1.0],[0.0,-1.0]]},{"p":[[0.0,-1.0],[1.0,-1.0],[1.0,-2.0],[0.0,-2.0]]},{"p":[[0.0,-2.0],[1.0,-2.0],[0.5,-2.866]]},{"p":[[1.0,-1.0],[1.0,0.0],[1.866,-0.5]]},{"p":[[0.0,0.0],[0.0,-1.0],[-0.866,-0.5]]}],"u":34},"variant_rule":{"alt":[{"stem":"모양 조각으로 집 모양을 만들었어요. 정사각형 조각은 몇 개 썼나요? 숫자로 쓰세요.","answer":["2"],"explanation":["정사각형 조각의 모양을 떠올려요.","그림에서 그 모양인 조각을 하나씩 표시하며 세요.","정사각형 조각은 2개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.0,-1.0],[0.0,-1.0]]},{"p":[[0.0,-1.0],[1.0,-1.0],[1.0,-2.0],[0.0,-2.0]]},{"p":[[0.0,-2.0],[1.0,-2.0],[0.5,-2.866]]}],"u":34}},{"stem":"모양 조각으로 물고기 모양을 만들었어요. 정삼각형 조각은 몇 개 썼나요? 숫자로 쓰세요.","answer":["3"],"explanation":["정삼각형 조각의 모양을 떠올려요.","그림에서 그 모양인 조각을 하나씩 표시하며 세요.","정삼각형 조각은 3개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.5,-0.866],[1.0,-1.7321],[0.0,-1.7321],[-0.5,-0.866]]},{"p":[[1.0,-1.7321],[1.5,-0.866],[2.0,-1.7321]]},{"p":[[1.5,-0.866],[1.0,-0.0],[2.0,0.0]]},{"p":[[0.0,0.0],[-0.5,-0.866],[-1.0,0.0]]}],"u":34}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L06_basic#9','math',4,2,'u4','L06','g4_2_math_u4_L06_basic','lesson_basic','M4-2-u4-C8',2,'sa','auto','정육각형 조각 1개를 빈틈없이 덮으려면 사다리꼴 조각이 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u4-C8","difficulty":2,"kind":"sa","stem":"정육각형 조각 1개를 빈틈없이 덮으려면 사다리꼴 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["2"],"explanation":["정삼각형 조각을 하나의 단위로 생각해요.","정삼각형으로 덮으면 마름모 2개, 사다리꼴 3개, 정육각형 6개예요.","그래서 답은 2개예요."],"variant_rule":{"alt":[{"stem":"정육각형 조각 1개를 빈틈없이 덮으려면 마름모 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["3"],"explanation":["정삼각형 조각을 하나의 단위로 생각해요.","정삼각형으로 덮으면 마름모 2개, 사다리꼴 3개, 정육각형 6개예요.","그래서 답은 3개예요."],"asset":null},{"stem":"사다리꼴 조각 2개를 빈틈없이 덮으려면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["6"],"explanation":["정삼각형 조각을 하나의 단위로 생각해요.","정삼각형으로 덮으면 마름모 2개, 사다리꼴 3개, 정육각형 6개예요.","그래서 답은 6개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L06_basic#10','math',4,2,'u4','L06','g4_2_math_u4_L06_basic','lesson_basic','M4-2-u4-C8',3,'sa','auto','아래 사탕 모양과 똑같은 모양을 정삼각형 조각으로만 만들려면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u4-C8","difficulty":3,"kind":"sa","stem":"아래 사탕 모양과 똑같은 모양을 정삼각형 조각으로만 만들려면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["10"],"explanation":["조각마다 정삼각형 몇 개와 같은지 바꿔요.","정삼각형 4개(정삼각형 4개), 정육각형 1개(정삼각형 6개)예요.","모두 정삼각형 10개예요."],"asset":{"type":"tiles","pieces":[{"p":[[1.5,-0.866],[1.0,-0.0],[2.0,0.0]]},{"p":[[1.0,-1.7321],[1.5,-0.866],[2.0,-1.7321]]},{"p":[[0.0,0.0],[1.0,0.0],[1.5,-0.866],[1.0,-1.7321],[0.0,-1.7321],[-0.5,-0.866]]},{"p":[[-0.5,-0.866],[0.0,-1.7321],[-1.0,-1.7321]]},{"p":[[0.0,0.0],[-0.5,-0.866],[-1.0,0.0]]}],"u":34},"variant_rule":{"alt":[{"stem":"아래 물고기 모양과 똑같은 모양을 정삼각형 조각으로만 만들려면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["9"],"explanation":["조각마다 정삼각형 몇 개와 같은지 바꿔요.","정삼각형 3개(정삼각형 3개), 정육각형 1개(정삼각형 6개)예요.","모두 정삼각형 9개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.5,-0.866],[1.0,-1.7321],[0.0,-1.7321],[-0.5,-0.866]]},{"p":[[1.0,-1.7321],[1.5,-0.866],[2.0,-1.7321]]},{"p":[[1.5,-0.866],[1.0,-0.0],[2.0,0.0]]},{"p":[[0.0,0.0],[-0.5,-0.866],[-1.0,0.0]]}],"u":34}},{"stem":"아래 큰 삼각형 모양과 똑같은 모양을 정삼각형 조각으로만 만들려면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["9"],"explanation":["조각마다 정삼각형 몇 개와 같은지 바꿔요.","정삼각형 3개(정삼각형 3개), 정육각형 1개(정삼각형 6개)예요.","모두 정삼각형 9개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.5,-0.866],[1.0,-1.7321],[0.0,-1.7321],[-0.5,-0.866]]},{"p":[[1.0,0.0],[0.0,0.0],[0.5,0.866]]},{"p":[[1.0,-1.7321],[1.5,-0.866],[2.0,-1.7321]]},{"p":[[-0.5,-0.866],[0.0,-1.7321],[-1.0,-1.7321]]}],"u":34}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=E