INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L06_challenge#2','math',4,2,'u4','L06','g4_2_math_u4_L06_challenge','lesson_challenge','M4-2-u4-C8',2,'ox','auto','정삼각형 조각 4개로 만든 모양을 마름모 조각 2개로도 만들 수 있어요.',ARRAY['M4-2-u4-X19']::text[],true,'{"seq":2,"concept":"M4-2-u4-C8","difficulty":2,"kind":"ox","stem":"정삼각형 조각 4개로 만든 모양을 마름모 조각 2개로도 만들 수 있어요.","answer":"O","reason_options":[{"t":"마름모 1개가 정삼각형 2개와 같은 모양이라서","correct":true},{"t":"마름모는 정삼각형과 크기 관계가 없어서","mis":"M4-2-u4-X19"}],"mis":"M4-2-u4-X19","explanation":["같은 모양이라도 쓰는 조각과 붙이는 차례는 여러 가지예요.","마름모 = 정삼각형 2개, 사다리꼴 = 정삼각형 3개, 정육각형 = 정삼각형 6개예요.","겹치거나 빈틈 없이 같은 모양이면 모두 바른 방법이에요."],"variant_rule":{"alt":[{"stem":"정육각형은 사다리꼴 조각 2개로도, 마름모 조각 3개로도 만들 수 있어요.","answer":"O","reason_options":[{"t":"두 방법 모두 겹치거나 빈틈없이 정육각형이 되어서","correct":true},{"t":"정육각형은 정삼각형 조각으로만 만들 수 있어서","mis":"M4-2-u4-X18"}],"explanation":["같은 모양이라도 쓰는 조각과 붙이는 차례는 여러 가지예요.","마름모 = 정삼각형 2개, 사다리꼴 = 정삼각형 3개, 정육각형 = 정삼각형 6개예요.","겹치거나 빈틈 없이 같은 모양이면 모두 바른 방법이에요."],"asset":null},{"stem":"쓴 조각의 수가 다르면 같은 모양을 만들 수 없어요.","answer":"X","reason_options":[{"t":"조각 수가 달라도 같은 모양이 될 수 있어서","correct":true},{"t":"조각 수가 같아야 같은 모양이라서","mis":"M4-2-u4-X18"}],"explanation":["같은 모양이라도 쓰는 조각과 붙이는 차례는 여러 가지예요.","마름모 = 정삼각형 2개, 사다리꼴 = 정삼각형 3개, 정육각형 = 정삼각형 6개예요.","겹치거나 빈틈 없이 같은 모양이면 모두 바른 방법이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L06_challenge#3','math',4,2,'u4','L06','g4_2_math_u4_L06_challenge','lesson_challenge','M4-2-u4-C8',3,'sa','auto','정육각형 조각과 똑같은 모양을 사다리꼴 1개와 마름모 1개에 정삼각형 조각을 더 붙여 만들려고 해요. 정삼각형 조각은 몇 개 더 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u4-C8","difficulty":3,"kind":"sa","stem":"정육각형 조각과 똑같은 모양을 사다리꼴 1개와 마름모 1개에 정삼각형 조각을 더 붙여 만들려고 해요. 정삼각형 조각은 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["정육각형 = 정삼각형 6개예요.","사다리꼴 1개와 마름모 1개 = 정삼각형 5개만큼이에요.","6 − 5 = 1개 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"정육각형 조각과 똑같은 모양을 마름모 2개에 정삼각형 조각을 더 붙여 만들려고 해요. 정삼각형 조각은 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["정육각형 = 정삼각형 6개예요.","마름모 2개 = 정삼각형 4개만큼이에요.","6 − 4 = 2개 더 있어야 해요."],"asset":null},{"stem":"정육각형 조각과 똑같은 모양을 사다리꼴 1개에 정삼각형 조각을 더 붙여 만들려고 해요. 정삼각형 조각은 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["정육각형 = 정삼각형 6개예요.","사다리꼴 1개 = 정삼각형 3개만큼이에요.","6 − 3 = 3개 더 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L06_challenge#4','math',4,2,'u4','L06','g4_2_math_u4_L06_challenge','lesson_challenge','M4-2-u4-C8',3,'sa','auto','아래 꽃 모양과 똑같은 모양을 정삼각형 조각으로만 만들려면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u4-C8","difficulty":3,"kind":"sa","stem":"아래 꽃 모양과 똑같은 모양을 정삼각형 조각으로만 만들려면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["12"],"explanation":["조각마다 정삼각형 몇 개와 같은지 바꿔요.","정삼각형 6개(정삼각형 6개), 정육각형 1개(정삼각형 6개)예요.","모두 정삼각형 12개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.5,-0.866],[1.0,-1.7321],[0.0,-1.7321],[-0.5,-0.866]]},{"p":[[1.0,0.0],[0.0,0.0],[0.5,0.866]]},{"p":[[1.5,-0.866],[1.0,-0.0],[2.0,0.0]]},{"p":[[1.0,-1.7321],[1.5,-0.866],[2.0,-1.7321]]},{"p":[[0.0,-1.7321],[1.0,-1.7321],[0.5,-2.5981]]},{"p":[[-0.5,-0.866],[0.0,-1.7321],[-1.0,-1.7321]]},{"p":[[0.0,0.0],[-0.5,-0.866],[-1.0,0.0]]}],"u":34},"variant_rule":{"alt":[{"stem":"아래 별 무늬 모양과 똑같은 모양을 정삼각형 조각으로만 만들려면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["6"],"explanation":["조각마다 정삼각형 몇 개와 같은지 바꿔요.","마름모 3개(정삼각형 6개)예요.","모두 정삼각형 6개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.5,-0.866],[-0.0,-0.0],[1.0,0.0],[1.5,-0.866]]},{"p":[[0.5,-0.866],[1.5,-0.866],[1.0,-1.7321],[0.0,-1.7321]]},{"p":[[0.5,-0.866],[0.0,-1.7321],[-0.5,-0.866],[-0.0,0.0]]}],"u":34}},{"stem":"아래 우산 모양과 똑같은 모양을 정삼각형 조각으로만 만들려면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["7"],"explanation":["조각마다 정삼각형 몇 개와 같은지 바꿔요.","정삼각형 1개(정삼각형 1개), 정육각형 1개(정삼각형 6개)예요.","모두 정삼각형 7개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.5,-0.866],[1.0,-1.7321],[0.0,-1.7321],[-0.5,-0.866]]},{"p":[[1.0,0.0],[0.0,0.0],[0.5,0.866]]}],"u":34}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, m