INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L06_challenge#5','math',4,2,'u4','L06','g4_2_math_u4_L06_challenge','lesson_challenge','M4-2-u4-C8',3,'sa','auto','정삼각형 조각 6개를 이어 붙이면 정육각형 조각 1개와 같은 모양이 돼요. 정육각형 2개를 만들려면 정삼각형 조각은 모두 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u4-C8","difficulty":3,"kind":"sa","stem":"정삼각형 조각 6개를 이어 붙이면 정육각형 조각 1개와 같은 모양이 돼요. 정육각형 2개를 만들려면 정삼각형 조각은 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["12"],"explanation":["정육각형 1개 = 정삼각형 6개예요.","정육각형 2개는 정삼각형 6 × 2개예요.","6 × 2 = 12개예요."],"variant_rule":{"alt":[{"stem":"정삼각형 조각 3개를 이어 붙이면 사다리꼴 조각 1개와 같은 모양이 돼요. 사다리꼴 3개를 만들려면 정삼각형 조각은 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["9"],"explanation":["사다리꼴 1개 = 정삼각형 3개예요.","사다리꼴 3개는 정삼각형 3 × 3개예요.","3 × 3 = 9개예요."],"asset":null},{"stem":"정삼각형 조각 2개를 이어 붙이면 마름모 조각 1개와 같은 모양이 돼요. 마름모 7개를 만들려면 정삼각형 조각은 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["14"],"explanation":["마름모 1개 = 정삼각형 2개예요.","마름모 7개는 정삼각형 2 × 7개예요.","2 × 7 = 14개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L06_challenge#6','math',4,2,'u4','L06','g4_2_math_u4_L06_challenge','lesson_challenge','M4-2-u4-C8',3,'mc','auto','조각 2개를 이어 붙여 만든 도형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X04','M4-2-u4-X17']::text[],true,'{"seq":6,"concept":"M4-2-u4-C8","difficulty":3,"kind":"mc","stem":"조각 2개를 이어 붙여 만든 도형의 이름은 무엇인가요?","options":[{"t":"사각형","correct":true},{"t":"오각형","mis":"M4-2-u4-X04"},{"t":"칠각형","mis":"M4-2-u4-X17"},{"t":"삼각형","mis":"M4-2-u4-X04"}],"explanation":["만든 도형의 바깥쪽 변만 세요 — 조각끼리 맞댄 안쪽 선은 변이 아니에요.","한 줄로 곧게 이어진 선은 변 하나예요. 바깥쪽 변은 4개예요.","그래서 사각형이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[2.0,0.0],[1.5,-0.866],[0.5,-0.866]]},{"p":[[1.5,-0.866],[2.0,0.0],[2.5,-0.866]]}],"u":34},"variant_rule":{"alt":[{"stem":"아래와 같이 조각을 이어 붙였어요. 만든 도형의 이름은 무엇인가요?","options":[{"t":"육각형","correct":true},{"t":"삼각형","mis":"M4-2-u4-X17"},{"t":"십이각형","mis":"M4-2-u4-X17"},{"t":"칠각형","mis":"M4-2-u4-X04"}],"explanation":["만든 도형의 바깥쪽 변만 세요 — 조각끼리 맞댄 안쪽 선은 변이 아니에요.","한 줄로 곧게 이어진 선은 변 하나예요. 바깥쪽 변은 6개예요.","그래서 육각형이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0.5,-0.866],[-0.0,-0.0],[1.0,0.0],[1.5,-0.866]]},{"p":[[0.5,-0.866],[1.5,-0.866],[1.0,-1.7321],[0.0,-1.7321]]},{"p":[[0.5,-0.866],[0.0,-1.7321],[-0.5,-0.866],[-0.0,0.0]]}],"u":34}},{"stem":"이번에는 다른 그림이에요. 조각 2개를 이어 붙여 만든 도형의 이름은 무엇인가요?","options":[{"t":"육각형","correct":true},{"t":"칠각형","mis":"M4-2-u4-X04"},{"t":"팔각형","mis":"M4-2-u4-X17"},{"t":"오각형","mis":"M4-2-u4-X04"}],"explanation":["만든 도형의 바깥쪽 변만 세요 — 조각끼리 맞댄 안쪽 선은 변이 아니에요.","한 줄로 곧게 이어진 선은 변 하나예요. 바깥쪽 변은 6개예요.","그래서 육각형이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[2.0,0.0],[1.5,-0.866],[0.5,-0.866]]},{"p":[[2.0,0.0],[0.0,0.0],[0.5,0.866],[1.5,0.866]]}],"u":34}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qk