INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L06_challenge#7','math',4,2,'u4','L06','g4_2_math_u4_L06_challenge','lesson_challenge','M4-2-u4-C8',3,'sa','auto','정육각형 조각과 똑같은 모양을 마름모 1개에 정삼각형 조각을 더 붙여 만들려고 해요. 정삼각형 조각은 몇 개 더 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u4-C8","difficulty":3,"kind":"sa","stem":"정육각형 조각과 똑같은 모양을 마름모 1개에 정삼각형 조각을 더 붙여 만들려고 해요. 정삼각형 조각은 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["정육각형 = 정삼각형 6개예요.","마름모 1개 = 정삼각형 2개만큼이에요.","6 − 2 = 4개 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"정육각형 조각과 똑같은 모양을 사다리꼴 1개와 정삼각형 1개에 정삼각형 조각을 더 붙여 만들려고 해요. 정삼각형 조각은 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["정육각형 = 정삼각형 6개예요.","사다리꼴 1개와 정삼각형 1개 = 정삼각형 4개만큼이에요.","6 − 4 = 2개 더 있어야 해요."],"asset":null},{"stem":"정육각형 조각과 똑같은 모양을 마름모 2개와 정삼각형 1개에 정삼각형 조각을 더 붙여 만들려고 해요. 정삼각형 조각은 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["1"],"explanation":["정육각형 = 정삼각형 6개예요.","마름모 2개와 정삼각형 1개 = 정삼각형 5개만큼이에요.","6 − 5 = 1개 더 있어야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L06_challenge#8','math',4,2,'u4','L06','g4_2_math_u4_L06_challenge','lesson_challenge','M4-2-u4-C8',4,'sa','auto','조각으로 만든 꽃 모양의 바깥쪽 변은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u4-C8","difficulty":4,"kind":"sa","stem":"조각으로 만든 꽃 모양의 바깥쪽 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["조각끼리 맞댄 안쪽 선은 세지 않아요.","바깥쪽을 한 바퀴 돌며 꺾이는 곳마다 표시해요 — 한 줄로 곧게 이어진 선은 변 하나예요.","바깥쪽 변은 12개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.5,-0.866],[1.0,-1.7321],[0.0,-1.7321],[-0.5,-0.866]]},{"p":[[1.0,0.0],[0.0,0.0],[0.5,0.866]]},{"p":[[1.5,-0.866],[1.0,-0.0],[2.0,0.0]]},{"p":[[1.0,-1.7321],[1.5,-0.866],[2.0,-1.7321]]},{"p":[[0.0,-1.7321],[1.0,-1.7321],[0.5,-2.5981]]},{"p":[[-0.5,-0.866],[0.0,-1.7321],[-1.0,-1.7321]]},{"p":[[0.0,0.0],[-0.5,-0.866],[-1.0,0.0]]}],"u":34},"variant_rule":{"alt":[{"stem":"조각으로 만든 로켓 모양의 바깥쪽 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["조각끼리 맞댄 안쪽 선은 세지 않아요.","바깥쪽을 한 바퀴 돌며 꺾이는 곳마다 표시해요 — 한 줄로 곧게 이어진 선은 변 하나예요.","바깥쪽 변은 9개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.0,-1.0],[0.0,-1.0]]},{"p":[[0.0,-1.0],[1.0,-1.0],[1.0,-2.0],[0.0,-2.0]]},{"p":[[0.0,-2.0],[1.0,-2.0],[0.5,-2.866]]},{"p":[[1.0,-1.0],[1.0,0.0],[1.866,-0.5]]},{"p":[[0.0,0.0],[0.0,-1.0],[-0.866,-0.5]]}],"u":34}},{"stem":"조각으로 만든 나무 모양의 바깥쪽 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["조각끼리 맞댄 안쪽 선은 세지 않아요.","바깥쪽을 한 바퀴 돌며 꺾이는 곳마다 표시해요 — 한 줄로 곧게 이어진 선은 변 하나예요.","바깥쪽 변은 7개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[2.0,0.0],[1.5,-0.866],[0.5,-0.866]]},{"p":[[0.5,-0.866],[1.5,-0.866],[1.0,-1.7321]]},{"p":[[1.5,0.0],[0.5,0.0],[0.5,1.0],[1.5,1.0]]}],"u":34}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L06_challenge#9','math',4,2,'u4','L06','g4_2_math_u4_L06_challenge','lesson_challenge','M4-2-u4-C8',4,'sa','auto','어떤 모양에 쓴 정육각형 조각 3개를 모두 같은 크기의 정삼각형 조각으로 바꾸어 붙였어요. 조각의 수는 몇 개 늘어났나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u4-C8","difficulty":4,"kind":"sa","stem":"어떤 모양에 쓴 정육각형 조각 3개를 모두 같은 크기의 정삼각형 조각으로 바꾸어 붙였어요. 조각의 수는 몇 개 늘어났나요? 숫자로 쓰세요.","answer":["15"],"explanation":["정육각형 1개 = 정삼각형 6개예요.","정육각형 3개 → 정삼각형 18개예요.","18 − 3 = 15개 늘어났어요."],"variant_rule":{"alt":[{"stem":"어떤 모양에 쓴 사다리꼴 조각 4개를 모두 같은 크기의 정삼각형 조각으로 바꾸어 붙였어요. 조각의 수는 몇 개 늘어났나요? 숫자로 쓰세요.","answer":["8"],"explanation":["사다리꼴 1개 = 정삼각형 3개예요.","사다리꼴 4개 → 정삼각형 12개예요.","12 − 4 = 8개 늘어났어요."],"asset":null},{"stem":"어떤 모양에 쓴 마름모 조각 5개를 모두 같은 크기의 정삼각형 조각으로 바꾸어 붙였어요. 조각의 수는 몇 개 늘어났나요? 숫자로 쓰세요.","answer":["5"],"explanation":["마름모 1개 = 정삼각형 2개예요.","마름모 5개 → 정삼각형 10개예요.","10 − 5 = 5개 늘어났어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L06_challenge#10','math',4,2,'u4','L06','g4_2_math_u4_L06_challenge','lesson_challenge','M4-2-u4-C8',4,'essay','teacher','정삼각형 조각 6개, 마름모 조각 3개, 사다리꼴 조각 2개로 각각 정육각형 조각과 똑같은 모양을 만들 수 있어요. 쓴 조각의 수가 다른데도 같은 모양이 되는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u4-C8","difficulty":4,"kind":"essay","stem":"정삼각형 조각 6개, 마름모 조각 3개, 사다리꼴 조각 2개로 각각 정육각형 조각과 똑같은 모양을 만들 수 있어요. 쓴 조각의 수가 다른데도 같은 모양이 되는 까닭을 써 보세요.","answer_guide":{"answer":"예: 마름모 1개는 정삼각형 2개, 사다리꼴 1개는 정삼각형 3개와 같은 모양이다. 그래서 마름모 3개는 정삼각형 6개, 사다리꼴 2개도 정삼각형 6개만큼이 되어 정육각형과 크기와 모양이 같다. 겹치지 않고 빈틈없이 붙이면 쓴 조각의 수가 달라도 같은 모양을 만들 수 있다.","scoring_points":["마름모 = 정삼각형 2개, 사다리꼴 = 정삼각형 3개를 썼는가","세 방법 모두 정삼각형 6개만큼이라고 썼는가","만드는 방법은 여러 가지라고 썼는가"]},"explanation":["마름모 = 정삼각형 2개, 사다리꼴 = 정삼각형 3개예요.","마름모 3개 = 사다리꼴 2개 = 정삼각형 6개.","조각 수가 달라도 같은 모양이 될 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L07_basic#1','math',4,2,'u4','L07','g4_2_math_u4_L07_basic','lesson_basic','M4-2-u4-C9',1,'mc','auto','모양을 바르게 채운 것은 어느 것인가요?',ARRAY['M4-2-u4-X16']::text[],true,'{"seq":1,"concept":"M4-2-u4-C9","difficulty":1,"kind":"mc","stem":"모양을 바르게 채운 것은 어느 것인가요?","options":[{"t":"조각끼리 겹치지 않고 빈틈도 없이 채운 것","correct":true},{"t":"조각끼리 겹치게 채운 것","mis":"M4-2-u4-X16"},{"t":"조각 사이에 빈틈을 남긴 것","mis":"M4-2-u4-X16"},{"t":"조각을 모양 밖으로 넘겨 채운 것","mis":"M4-2-u4-X16"}],"explanation":["모양을 채울 때는 조각끼리 겹치지 않게, 조각 사이에 빈틈도 없게 놓아요.","같은 모양도 쓰는 조각에 따라 채우는 방법이 여러 가지예요.","겹치지 않고 빈틈없이 평면을 채우는 일을 쪽매맞춤이라고 해요."],"variant_rule":{"alt":[{"stem":"같은 모양을 채우는 방법에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"쓰는 조각에 따라 여러 가지 방법이 있다","correct":true},{"t":"채우는 방법은 한 가지뿐이다","mis":"M4-2-u4-X18"},{"t":"조각이 적을수록 틀린 방법이다","mis":"M4-2-u4-X18"},{"t":"정삼각형 조각으로만 채울 수 있다","mis":"M4-2-u4-X18"}],"explanation":["모양을 채울 때는 조각끼리 겹치지 않게, 조각 사이에 빈틈도 없게 놓아요.","같은 모양도 쓰는 조각에 따라 채우는 방법이 여러 가지예요.","겹치지 않고 빈틈없이 평면을 채우는 일을 쪽매맞춤이라고 해요."],"asset":null},{"stem":"도형을 서로 겹치지 않으면서 빈틈없이 평면을 채우는 일을 무엇이라고 하나요?","options":[{"t":"쪽매맞춤","correct":true},{"t":"어림하기","mis":"M4-2-u4-X18"},{"t":"대각선 긋기","mis":"M4-2-u4-X11"},{"t":"각도 재기","mis":"M4-2-u4-X20"}],"explanation":["모양을 채울 때는 조각끼리 겹치지 않게, 조각 사이에 빈틈도 없게 놓아요.","같은 모양도 쓰는 조각에 따라 채우는 방법이 여러 가지예요.","겹치지 않고 빈틈없이 평면을 채우는 일을 쪽매맞춤이라고 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L07_basic#2','math',4,2,'u4','L07','g4_2_math_u4_L07_basic','lesson_basic','M4-2-u4-C9',1,'sa','auto','아래 정육각형 모양을 정삼각형 조각으로 빈틈없이 채우려고 해요. 점선을 보고, 정삼각형 조각이 몇 개 필요한지 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u4-C9","difficulty":1,"kind":"sa","stem":"아래 정육각형 모양을 정삼각형 조각으로 빈틈없이 채우려고 해요. 점선을 보고, 정삼각형 조각이 몇 개 필요한지 숫자로 쓰세요.","answer":["6"],"explanation":["점선으로 나뉜 작은 정삼각형 하나가 조각 하나예요.","한 줄씩 차례로 세면 빠뜨리지 않아요.","정삼각형 조각 6개가 필요해요."],"asset":{"type":"geo","items":[{"w":76.0,"h":68.0,"poly":[[[23.0,59.96],[53.0,59.96],[68.0,33.98],[53.0,8.0],[23.0,8.0],[8.0,33.98]]],"dash":[[[8.0,33.98],[38.0,33.98]],[[23.0,8.0],[38.0,33.98]],[[23.0,59.96],[38.0,33.98]],[[38.0,33.98],[53.0,8.0]],[[38.0,33.98],[53.0,59.96]],[[38.0,33.98],[68.0,33.98]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"아래 큰 마름모 모양을 정삼각형 조각으로 빈틈없이 채우려고 해요. 점선을 보고, 정삼각형 조각이 몇 개 필요한지 숫자로 쓰세요.","answer":["8"],"explanation":["점선으로 나뉜 작은 정삼각형 하나가 조각 하나예요.","한 줄씩 차례로 세면 빠뜨리지 않아요.","정삼각형 조각 8개가 필요해요."],"asset":{"type":"geo","items":[{"w":106.0,"h":68.0,"poly":[[[8.0,59.96],[68.0,59.96],[98.0,8.0],[38.0,8.0]]],"dash":[[[23.0,33.98],[38.0,59.96]],[[23.0,33.98],[53.0,33.98]],[[38.0,8.0],[53.0,33.98]],[[38.0,59.96],[53.0,33.98]],[[53.0,33.98],[68.0,8.0]],[[53.0,33.98],[68.0,59.96]],[[53.0,33.98],[83.0,33.98]],[[68.0,8.0],[83.0,33.98]]]}],"tag":false}},{"stem":"아래 큰 삼각형 모양을 정삼각형 조각으로 빈틈없이 채우려고 해요. 점선을 보고, 정삼각형 조각이 몇 개 필요한지 숫자로 쓰세요.","answer":["9"],"explanation":["점선으로 나뉜 작은 정삼각형 하나가 조각 하나예요.","한 줄씩 차례로 세면 빠뜨리지 않아요.","정삼각형 조각 9개가 필요해요."],"asset":{"type":"geo","items":[{"w":106.0,"h":93.9,"poly":[[[8.0,85.94],[98.0,85.94],[53.0,8.0]]],"dash":[[[23.0,59.96],[38.0,85.94]],[[23.0,59.96],[53.0,59.96]],[[38.0,33.98],[53.0,59.96]],[[38.0,33.98],[68.0,33.98]],[[38.0,85.94],[53.0,59.96]],[[53.0,59.96],[68.0,33.98]],[[53.0,5