INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L07_basic#3','math',4,2,'u4','L07','g4_2_math_u4_L07_basic','lesson_basic','M4-2-u4-C9',1,'sa','auto','정육각형 모양을 조각으로 빈틈없이 채웠어요. 조각을 모두 몇 개 썼나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u4-C9","difficulty":1,"kind":"sa","stem":"정육각형 모양을 조각으로 빈틈없이 채웠어요. 조각을 모두 몇 개 썼나요? 숫자로 쓰세요.","answer":["3"],"explanation":["조각마다 하나씩 표시하며 세요.","조각의 모양이 달라도 모두 세어요.","모두 3개예요."],"asset":{"type":"tiles","pieces":[{"p":[[2.0,-0.0],[2.5,-0.866],[1.5,-0.866],[1.0,0.0]]},{"p":[[1.5,-0.866],[2.5,-0.866],[2.0,-1.7321],[1.0,-1.7321]]},{"p":[[0.5,-0.866],[1.0,0.0],[1.5,-0.866],[1.0,-1.7321]]}],"u":34},"variant_rule":{"alt":[{"stem":"큰 삼각형 모양을 조각으로 빈틈없이 채웠어요. 조각을 모두 몇 개 썼나요? 숫자로 쓰세요.","answer":["3"],"explanation":["조각마다 하나씩 표시하며 세요.","조각의 모양이 달라도 모두 세어요.","모두 3개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,-0.0],[2.0,-0.0],[1.5,-0.866],[0.5,-0.866]]},{"p":[[3.0,-0.0],[2.0,-1.7321],[1.5,-0.866],[2.0,-0.0]]},{"p":[[1.5,-2.5981],[0.5,-0.866],[1.5,-0.866],[2.0,-1.7321]]}],"u":34}},{"stem":"큰 마름모 모양을 조각으로 빈틈없이 채웠어요. 조각을 모두 몇 개 썼나요? 숫자로 쓰세요.","answer":["4"],"explanation":["조각마다 하나씩 표시하며 세요.","조각의 모양이 달라도 모두 세어요.","모두 4개예요."],"asset":{"type":"tiles","pieces":[{"p":[[1.0,-0.0],[1.5,-0.866],[0.5,-0.866],[0.0,0.0]]},{"p":[[1.5,-0.866],[2.0,-1.7321],[1.0,-1.7321],[0.5,-0.866]]},{"p":[[2.0,-0.0],[2.5,-0.866],[1.5,-0.866],[1.0,0.0]]},{"p":[[2.5,-0.866],[3.0,-1.7321],[2.0,-1.7321],[1.5,-0.866]]}],"u":34}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L07_basic#4','math',4,2,'u4','L07','g4_2_math_u4_L07_basic','lesson_basic','M4-2-u4-C9',1,'mc','auto','인사말 타일 벽을 모양 조각으로 채우려고 해요. 지켜야 할 것으로 알맞은 것은 어느 것인가요?',ARRAY['M4-2-u4-X16','M4-2-u4-X18']::text[],true,'{"seq":4,"concept":"M4-2-u4-C9","difficulty":1,"kind":"mc","stem":"인사말 타일 벽을 모양 조각으로 채우려고 해요. 지켜야 할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"겹치지 않고 빈틈없이 놓는다","correct":true},{"t":"조각을 겹쳐서 놓는다","mis":"M4-2-u4-X16"},{"t":"조각 사이를 벌려 놓는다","mis":"M4-2-u4-X16"},{"t":"한 가지 조각만 쓴다","mis":"M4-2-u4-X18"}],"explanation":["모양을 채울 때는 조각끼리 겹치지 않게, 조각 사이에 빈틈도 없게 놓아요.","같은 모양도 쓰는 조각에 따라 채우는 방법이 여러 가지예요.","겹치지 않고 빈틈없이 평면을 채우는 일을 쪽매맞춤이라고 해요."],"variant_rule":{"alt":[{"stem":"모양을 바르게 채운 것은 어느 것인가요?","options":[{"t":"조각끼리 겹치지 않고 빈틈도 없이 채운 것","correct":true},{"t":"조각끼리 겹치게 채운 것","mis":"M4-2-u4-X16"},{"t":"조각 사이에 빈틈을 남긴 것","mis":"M4-2-u4-X16"},{"t":"조각을 모양 밖으로 넘겨 채운 것","mis":"M4-2-u4-X16"}],"explanation":["모양을 채울 때는 조각끼리 겹치지 않게, 조각 사이에 빈틈도 없게 놓아요.","같은 모양도 쓰는 조각에 따라 채우는 방법이 여러 가지예요.","겹치지 않고 빈틈없이 평면을 채우는 일을 쪽매맞춤이라고 해요."],"asset":null},{"stem":"도형을 서로 겹치지 않으면서 빈틈없이 평면을 채우는 일을 무엇이라고 하나요?","options":[{"t":"쪽매맞춤","correct":true},{"t":"어림하기","mis":"M4-2-u4-X18"},{"t":"대각선 긋기","mis":"M4-2-u4-X11"},{"t":"각도 재기","mis":"M4-2-u4-X20"}],"explanation":["모양을 채울 때는 조각끼리 겹치지 않게, 조각 사이에 빈틈도 없게 놓아요.","같은 모양도 쓰는 조각에 따라 채우는 방법이 여러 가지예요.","겹치지 않고 빈틈없이 평면을 채우는 일을 쪽매맞춤이라고 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L07_basic#5','math',4,2,'u4','L07','g4_2_math_u4_L07_basic','lesson_basic','M4-2-u4-C9',2,'sa','auto','아래 정육각형 모양은 정삼각형 조각 6개로 채울 수 있어요. 같은 모양을 마름모 조각으로만 빈틈없이 채우면 조각이 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u4-C9","difficulty":2,"kind":"sa","stem":"아래 정육각형 모양은 정삼각형 조각 6개로 채울 수 있어요. 같은 모양을 마름모 조각으로만 빈틈없이 채우면 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["3"],"explanation":["마름모 1개 = 정삼각형 2개예요.","정삼각형 6개만큼을 2개씩 묶어요.","6 ÷ 2 = 3개예요."],"asset":{"type":"geo","items":[{"w":76.0,"h":68.0,"poly":[[[23.0,59.96],[53.0,59.96],[68.0,33.98],[53.0,8.0],[23.0,8.0],[8.0,33.98]]],"dash":[[[8.0,33.98],[38.0,33.98]],[[23.0,8.0],[38.0,33.98]],[[23.0,59.96],[38.0,33.98]],[[38.0,33.98],[53.0,8.0]],[[38.0,33.98],[53.0,59.96]],[[38.0,33.98],[68.0,33.98]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"아래 정육각형 모양은 정삼각형 조각 6개로 채울 수 있어요. 같은 모양을 사다리꼴 조각으로만 빈틈없이 채우면 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["2"],"explanation":["사다리꼴 1개 = 정삼각형 3개예요.","정삼각형 6개만큼을 3개씩 묶어요.","6 ÷ 3 = 2개예요."],"asset":{"type":"geo","items":[{"w":76.0,"h":68.0,"poly":[[[23.0,59.96],[53.0,59.96],[68.0,33.98],[53.0,8.0],[23.0,8.0],[8.0,33.98]]],"dash":[[[8.0,33.98],[38.0,33.98]],[[23.0,8.0],[38.0,33.98]],[[23.0,59.96],[38.0,33.98]],[[38.0,33.98],[53.0,8.0]],[[38.0,33.98],[53.0,59.96]],[[38.0,33.98],[68.0,33.98]]]}],"tag":false}},{"stem":"아래 큰 마름모 모양은 정삼각형 조각 8개로 채울 수 있어요. 같은 모양을 마름모 조각으로만 빈틈없이 채우면 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["4"],"explanation":["마름모 1개 = 정삼각형 2개예요.","정삼각형 8개만큼을 2개씩 묶어요.","8 ÷ 2 = 4개예요."],"asset":{"type":"geo","items":[{"w":106.0,"h":68.0,"poly":[[[8.0,59.96],[68.0,59.96],[98.0,8.0],[38.0,8.0]]],"dash":[[[23.0,33.98],[38.0,59.96]],[[23.0,33.98],[53.0,33.98]],[[38.0,8.0],[53.0,33.98]],[[38.0,59.96],[53.0,33.98]],[[53.0,33.98],[68.0,8.0]],[[53.0,33.98],[68.0,59.96]],[[53.0,33.98],[83.0,33.98]],[[68.0,8.0],[83.0,33.98]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L07_basic#6','math',4,2,'u4','L07','g4_2_math_u4_L07_basic','lesson_basic','M4-2-u4-C9',2,'ox','auto','조각을 겹치게 놓아 빈틈을 없앴다면 바르게 채운 거예요.',ARRAY['M4-2-u4-X16']::text[],true,'{"seq":6,"concept":"M4-2-u4-C9","difficulty":2,"kind":"ox","stem":"조각을 겹치게 놓아 빈틈을 없앴다면 바르게 채운 거예요.","answer":"X","reason_options":[{"t":"겹친 부분이 있으면 바르게 채운 것이 아니라서","correct":true},{"t":"빈틈만 없으면 되어서","mis":"M4-2-u4-X16"}],"mis":"M4-2-u4-X16","explanation":["겹치지 않게, 빈틈없이 채워야 해요.","같은 모양도 쓰는 조각에 따라 방법과 조각 수가 달라져요.","큰 조각(정육각형 = 정삼각형 6개)으로 채우면 조각 수가 적어요."],"variant_rule":{"alt":[{"stem":"같은 정육각형 모양을 마름모 조각 3개로도, 사다리꼴 조각 2개로도 채울 수 있어요.","answer":"O","reason_options":[{"t":"두 방법 모두 겹치지 않고 빈틈없이 채워져서","correct":true},{"t":"정육각형은 한 가지 조각으로만 채워져서","mis":"M4-2-u4-X18"}],"explanation":["겹치지 않게, 빈틈없이 채워야 해요.","같은 모양도 쓰는 조각에 따라 방법과 조각 수가 달라져요.","큰 조각(정육각형 = 정삼각형 6개)으로 채우면 조각 수가 적어요."],"asset":null},{"stem":"조각 사이에 작은 빈틈이 있어도 겉보기에 다 덮였으면 채운 거예요.","answer":"X","reason_options":[{"t":"빈틈이 없어야 채운 것이라서","correct":true},{"t":"조금의 빈틈은 괜찮아서","mis":"M4-2-u4-X16"}],"explanation":["겹치지 않게, 빈틈없이 채워야 해요.","같은 모양도 쓰는 조각에 따라 방법과 조각 수가 달라져요.","큰 조각(정육각형 = 정삼각형 6개)으로 채우면 조각 수가 적어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
