INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L07_basic#8','math',4,2,'u4','L07','g4_2_math_u4_L07_basic','lesson_basic','M4-2-u4-C9',2,'sa','auto','쪽매맞춤에서 정삼각형 조각만으로 한 점을 빈틈없이 둘러싸려면 조각이 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u4-C9","difficulty":2,"kind":"sa","stem":"쪽매맞춤에서 정삼각형 조각만으로 한 점을 빈틈없이 둘러싸려면 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 점을 빈틈없이 둘러싸면 모인 각의 합이 360°예요.","정삼각형의 한 각은 60°예요.","360 ÷ 60 = 6개예요."],"variant_rule":{"alt":[{"stem":"쪽매맞춤에서 정사각형 조각만으로 한 점을 빈틈없이 둘러싸려면 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 점을 빈틈없이 둘러싸면 모인 각의 합이 360°예요.","정사각형의 한 각은 90°예요.","360 ÷ 90 = 4개예요."],"asset":null},{"stem":"쪽매맞춤에서 정육각형 조각만으로 한 점을 빈틈없이 둘러싸려면 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["3"],"explanation":["한 점을 빈틈없이 둘러싸면 모인 각의 합이 360°예요.","정육각형의 한 각은 120°예요.","360 ÷ 120 = 3개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
