INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L07_basic#10','math',4,2,'u4','L07','g4_2_math_u4_L07_basic','lesson_basic','M4-2-u4-C9',3,'sa','auto','큰 사다리꼴 모양을 여러 가지 조각으로 빈틈없이 채웠어요. 같은 모양을 정삼각형 조각으로만 다시 채우면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u4-C9","difficulty":3,"kind":"sa","stem":"큰 사다리꼴 모양을 여러 가지 조각으로 빈틈없이 채웠어요. 같은 모양을 정삼각형 조각으로만 다시 채우면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["12"],"explanation":["조각마다 정삼각형 몇 개와 같은지 바꿔요.","정삼각형 1개(정삼각형 1개), 정육각형 1개(정삼각형 6개), 사다리꼴 1개(정삼각형 3개), 마름모 1개(정삼각형 2개)예요.","모두 정삼각형 12개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.5,-0.866],[1.0,0.0],[2.0,-0.0],[2.5,-0.866],[2.0,-1.7321],[1.0,-1.7321]]},{"p":[[2.0,-0.0],[4.0,-0.0],[3.5,-0.866],[2.5,-0.866]]},{"p":[[1.0,-0.0],[0.5,-0.866],[-0.0,-0.0]]},{"p":[[2.5,-0.866],[3.5,-0.866],[3.0,-1.7321],[2.0,-1.7321]]}],"u":34},"variant_rule":{"alt":[{"stem":"큰 삼각형 모양을 여러 가지 조각으로 빈틈없이 채웠어요. 같은 모양을 정삼각형 조각으로만 다시 채우면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["9"],"explanation":["조각마다 정삼각형 몇 개와 같은지 바꿔요.","정삼각형 3개(정삼각형 3개), 정육각형 1개(정삼각형 6개)예요.","모두 정삼각형 9개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.5,-0.866],[1.0,0.0],[2.0,-0.0],[2.5,-0.866],[2.0,-1.7321],[1.0,-1.7321]]},{"p":[[1.0,-0.0],[0.5,-0.866],[-0.0,-0.0]]},{"p":[[3.0,-0.0],[2.5,-0.866],[2.0,-0.0]]},{"p":[[2.0,-1.7321],[1.5,-2.5981],[1.0,-1.7321]]}],"u":34}},{"stem":"삼각형 모양을 여러 가지 조각으로 빈틈없이 채웠어요. 같은 모양을 정삼각형 조각으로만 다시 채우면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["4"],"explanation":["조각마다 정삼각형 몇 개와 같은지 바꿔요.","정삼각형 1개(정삼각형 1개), 사다리꼴 1개(정삼각형 3개)예요.","모두 정삼각형 4개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,-0.0],[2.0,-0.0],[1.5,-0.866],[0.5,-0.866]]},{"p":[[1.5,-0.866],[1.0,-1.7321],[0.5,-0.866]]}],"u":34}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, g