INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L07_challenge#1','math',4,2,'u4','L07','g4_2_math_u4_L07_challenge','lesson_challenge','M4-2-u4-C9',2,'sa','auto','아래 큰 삼각형 모양은 정삼각형 조각 9개로 채울 수 있어요. 같은 모양을 사다리꼴 조각으로만 빈틈없이 채우면 조각이 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u4-C9","difficulty":2,"kind":"sa","stem":"아래 큰 삼각형 모양은 정삼각형 조각 9개로 채울 수 있어요. 같은 모양을 사다리꼴 조각으로만 빈틈없이 채우면 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["3"],"explanation":["사다리꼴 1개 = 정삼각형 3개예요.","정삼각형 9개만큼을 3개씩 묶어요.","9 ÷ 3 = 3개예요."],"asset":{"type":"geo","items":[{"w":106.0,"h":93.9,"poly":[[[8.0,85.94],[98.0,85.94],[53.0,8.0]]],"dash":[[[23.0,59.96],[38.0,85.94]],[[23.0,59.96],[53.0,59.96]],[[38.0,33.98],[53.0,59.96]],[[38.0,33.98],[68.0,33.98]],[[38.0,85.94],[53.0,59.96]],[[53.0,59.96],[68.0,33.98]],[[53.0,59.96],[68.0,85.94]],[[53.0,59.96],[83.0,59.96]],[[68.0,85.94],[83.0,59.96]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"아래 평행사변형 모양은 정삼각형 조각 6개로 채울 수 있어요. 같은 모양을 마름모 조각으로만 빈틈없이 채우면 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["3"],"explanation":["마름모 1개 = 정삼각형 2개예요.","정삼각형 6개만큼을 2개씩 묶어요.","6 ÷ 2 = 3개예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":42.0,"poly":[[[8.0,33.98],[98.0,33.98],[113.0,8.0],[23.0,8.0]]],"dash":[[[23.0,8.0],[38.0,33.98]],[[38.0,33.98],[53.0,8.0]],[[53.0,8.0],[68.0,33.98]],[[68.0,33.98],[83.0,8.0]],[[83.0,8.0],[98.0,33.98]]]}],"tag":false}},{"stem":"아래 평행사변형 모양은 정삼각형 조각 6개로 채울 수 있어요. 같은 모양을 사다리꼴 조각으로만 빈틈없이 채우면 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["2"],"explanation":["사다리꼴 1개 = 정삼각형 3개예요.","정삼각형 6개만큼을 3개씩 묶어요.","6 ÷ 3 = 2개예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":42.0,"poly":[[[8.0,33.98],[98.0,33.98],[113.0,8.0],[23.0,8.0]]],"dash":[[[23.0,8.0],[38.0,33.98]],[[38.0,33.98],[53.0,8.0]],[[53.0,8.0],[68.0,33.98]],[[68.0,33.98],[83.0,8.0]],[[83.0,8.0],[98.0,33.98]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (