INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L07_challenge#2','math',4,2,'u4','L07','g4_2_math_u4_L07_challenge','lesson_challenge','M4-2-u4-C9',2,'ox','auto','채우는 조각이 크면 조각 수가 적어지고, 작으면 조각 수가 많아져요.',ARRAY['M4-2-u4-X19']::text[],true,'{"seq":2,"concept":"M4-2-u4-C9","difficulty":2,"kind":"ox","stem":"채우는 조각이 크면 조각 수가 적어지고, 작으면 조각 수가 많아져요.","answer":"O","reason_options":[{"t":"같은 넓이를 큰 조각은 적게, 작은 조각은 많이 써서 덮어서","correct":true},{"t":"조각 크기와 조각 수는 관계가 없어서","mis":"M4-2-u4-X19"}],"mis":"M4-2-u4-X19","explanation":["겹치지 않게, 빈틈없이 채워야 해요.","같은 모양도 쓰는 조각에 따라 방법과 조각 수가 달라져요.","큰 조각(정육각형 = 정삼각형 6개)으로 채우면 조각 수가 적어요."],"variant_rule":{"alt":[{"stem":"같은 정육각형 모양을 마름모 조각 3개로도, 사다리꼴 조각 2개로도 채울 수 있어요.","answer":"O","reason_options":[{"t":"두 방법 모두 겹치지 않고 빈틈없이 채워져서","correct":true},{"t":"정육각형은 한 가지 조각으로만 채워져서","mis":"M4-2-u4-X18"}],"explanation":["겹치지 않게, 빈틈없이 채워야 해요.","같은 모양도 쓰는 조각에 따라 방법과 조각 수가 달라져요.","큰 조각(정육각형 = 정삼각형 6개)으로 채우면 조각 수가 적어요."],"asset":null},{"stem":"조각 사이에 작은 빈틈이 있어도 겉보기에 다 덮였으면 채운 거예요.","answer":"X","reason_options":[{"t":"빈틈이 없어야 채운 것이라서","correct":true},{"t":"조금의 빈틈은 괜찮아서","mis":"M4-2-u4-X16"}],"explanation":["겹치지 않게, 빈틈없이 채워야 해요.","같은 모양도 쓰는 조각에 따라 방법과 조각 수가 달라져요.","큰 조각(정육각형 = 정삼각형 6개)으로 채우면 조각 수가 적어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L07_challenge#3','math',4,2,'u4','L07','g4_2_math_u4_L07_challenge','lesson_challenge','M4-2-u4-C9',3,'sa','auto','정육각형 모양을 정삼각형 조각으로 채울 때와 마름모 조각으로 채울 때, 필요한 조각 수의 차는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u4-C9","difficulty":3,"kind":"sa","stem":"정육각형 모양을 정삼각형 조각으로 채울 때와 마름모 조각으로 채울 때, 필요한 조각 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["정삼각형으로는 6개예요.","마름모 1개 = 정삼각형 2개이니 마름모으로는 6 ÷ 2 = 3개예요.","6 − 3 = 3개예요."],"asset":{"type":"geo","items":[{"w":76.0,"h":68.0,"poly":[[[23.0,59.96],[53.0,59.96],[68.0,33.98],[53.0,8.0],[23.0,8.0],[8.0,33.98]]],"dash":[[[8.0,33.98],[38.0,33.98]],[[23.0,8.0],[38.0,33.98]],[[23.0,59.96],[38.0,33.98]],[[38.0,33.98],[53.0,8.0]],[[38.0,33.98],[53.0,59.96]],[[38.0,33.98],[68.0,33.98]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"정육각형 모양을 정삼각형 조각으로 채울 때와 사다리꼴 조각으로 채울 때, 필요한 조각 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["정삼각형으로는 6개예요.","사다리꼴 1개 = 정삼각형 3개이니 사다리꼴으로는 6 ÷ 3 = 2개예요.","6 − 2 = 4개예요."],"asset":{"type":"geo","items":[{"w":76.0,"h":68.0,"poly":[[[23.0,59.96],[53.0,59.96],[68.0,33.98],[53.0,8.0],[23.0,8.0],[8.0,33.98]]],"dash":[[[8.0,33.98],[38.0,33.98]],[[23.0,8.0],[38.0,33.98]],[[23.0,59.96],[38.0,33.98]],[[38.0,33.98],[53.0,8.0]],[[38.0,33.98],[53.0,59.96]],[[38.0,33.98],[68.0,33.98]]]}],"tag":false}},{"stem":"큰 마름모 모양을 정삼각형 조각으로 채울 때와 마름모 조각으로 채울 때, 필요한 조각 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["정삼각형으로는 8개예요.","마름모 1개 = 정삼각형 2개이니 마름모으로는 8 ÷ 2 = 4개예요.","8 − 4 = 4개예요."],"asset":{"type":"geo","items":[{"w":106.0,"h":68.0,"poly":[[[8.0,59.96],[68.0,59.96],[98.0,8.0],[38.0,8.0]]],"dash":[[[23.0,33.98],[38.0,59.96]],[[23.0,33.98],[53.0,33.98]],[[38.0,8.0],[53.0,33.98]],[[38.0,59.96],[53.0,33.98]],[[53.0,33.98],[68.0,8.0]],[[53.0,33.98],[68.0,59.96]],[[53.0,33.98],[83.0,33.98]],[[68.0,8.0],[83.0,33.98]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L07_challenge#4','math',4,2,'u4','L07','g4_2_math_u4_L07_challenge','lesson_challenge','M4-2-u4-C9',3,'sa','auto','정육각형 모양을 사다리꼴 조각으로 빈틈없이 채웠어요. 같은 모양을 정삼각형 조각으로만 다시 채우면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u4-C9","difficulty":3,"kind":"sa","stem":"정육각형 모양을 사다리꼴 조각으로 빈틈없이 채웠어요. 같은 모양을 정삼각형 조각으로만 다시 채우면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["6"],"explanation":["조각마다 정삼각형 몇 개와 같은지 바꿔요.","사다리꼴 2개(정삼각형 6개)예요.","모두 정삼각형 6개예요."],"asset":{"type":"tiles","pieces":[{"p":[[2.5,-0.866],[0.5,-0.866],[1.0,0.0],[2.0,0.0]]},{"p":[[0.5,-0.866],[2.5,-0.866],[2.0,-1.7321],[1.0,-1.7321]]}],"u":34},"variant_rule":{"alt":[{"stem":"평행사변형 모양을 마름모 조각으로 빈틈없이 채웠어요. 같은 모양을 정삼각형 조각으로만 다시 채우면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["6"],"explanation":["조각마다 정삼각형 몇 개와 같은지 바꿔요.","마름모 3개(정삼각형 6개)예요.","모두 정삼각형 6개예요."],"asset":{"type":"tiles","pieces":[{"p":[[1.0,-0.0],[1.5,-0.866],[0.5,-0.866],[0.0,0.0]]},{"p":[[2.0,-0.0],[2.5,-0.866],[1.5,-0.866],[1.0,0.0]]},{"p":[[3.0,-0.0],[3.5,-0.866],[2.5,-0.866],[2.0,0.0]]}],"u":34}},{"stem":"큰 마름모 모양을 마름모 조각으로 빈틈없이 채웠어요. 같은 모양을 정삼각형 조각으로만 다시 채우면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["8"],"explanation":["조각마다 정삼각형 몇 개와 같은지 바꿔요.","마름모 4개(정삼각형 8개)예요.","모두 정삼각형 8개예요."],"asset":{"type":"tiles","pieces":[{"p":[[1.0,-0.0],[1.5,-0.866],[0.5,-0.866],[0.0,0.0]]},{"p":[[1.5,-0.866],[2.0,-1.7321],[1.0,-1.7321],[0.5,-0.866]]},{"p":[[2.0,-0.0],[2.5,-0.866],[1.5,-0.866],[1.0,0.0]]},{"p":[[2.5,-0.866],[3.0,-1.7321],[2.0,-1.7321],[1.5,-0.866]]}],"u":34}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L07_challenge#5','math',4,2,'u4','L07','g4_2_math_u4_L07_challenge','lesson_challenge','M4-2-u4-C9',3,'sa','auto','정삼각형의 한 각은 60°예요. 정삼각형 조각 몇 개를 한 꼭짓점에 모으면 빈틈없이 한 바퀴(360°)가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u4-C9","difficulty":3,"kind":"sa","stem":"정삼각형의 한 각은 60°예요. 정삼각형 조각 몇 개를 한 꼭짓점에 모으면 빈틈없이 한 바퀴(360°)가 되나요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 점을 빈틈없이 둘러싸면 모인 각의 합이 360°예요.","정삼각형의 한 각은 60°예요.","360 ÷ 60 = 6개예요."],"variant_rule":{"alt":[{"stem":"정사각형의 한 각은 90°예요. 정사각형 조각 몇 개를 한 꼭짓점에 모으면 빈틈없이 한 바퀴(360°)가 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 점을 빈틈없이 둘러싸면 모인 각의 합이 360°예요.","정사각형의 한 각은 90°예요.","360 ÷ 90 = 4개예요."],"asset":null},{"stem":"정육각형의 한 각은 120°예요. 정육각형 조각 몇 개를 한 꼭짓점에 모으면 빈틈없이 한 바퀴(360°)가 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["한 점을 빈틈없이 둘러싸면 모인 각의 합이 360°예요.","정육각형의 한 각은 120°예요.","360 ÷ 120 = 3개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L07_challenge#6','math',4,2,'u4','L07','g4_2_math_u4_L07_challenge','lesson_challenge','M4-2-u4-C9',3,'mc','auto','같은 크기의 정다각형 한 가지만으로 바닥을 빈틈없이 채우려고 해요. 채울 수 없는 것은 어느 것인가요?',ARRAY['M4-2-u4-X20']::text[],true,'{"seq":6,"concept":"M4-2-u4-C9","difficulty":3,"kind":"mc","stem":"같은 크기의 정다각형 한 가지만으로 바닥을 빈틈없이 채우려고 해요. 채울 수 없는 것은 어느 것인가요?","options":[{"t":"정오각형","correct":true},{"t":"정삼각형","mis":"M4-2-u4-X20"},{"t":"정사각형","mis":"M4-2-u4-X20"},{"t":"정육각형","mis":"M4-2-u4-X20"}],"explanation":["한 꼭짓점에 모인 각의 합이 꼭 360°가 되어야 빈틈이 없어요.","정삼각형 60° × 6, 정사각형 90° × 4, 정육각형 120° × 3 = 360°예요.","정오각형 108°, 정팔각형 135°는 몇 개를 모아도 360°가 딱 되지 않아 빈틈이 생기거나 겹쳐요."],"variant_rule":{"alt":[{"stem":"같은 크기의 정다각형 한 가지만으로 바닥을 빈틈없이 채우려고 해요. 채울 수 없는 것은 어느 것인가요?","options":[{"t":"정팔각형","correct":true},{"t":"정사각형","mis":"M4-2-u4-X20"},{"t":"정삼각형","mis":"M4-2-u4-X20"},{"t":"정육각형","mis":"M4-2-u4-X20"}],"explanation":["한 꼭짓점에 모인 각의 합이 꼭 360°가 되어야 빈틈이 없어요.","정삼각형 60° × 6, 정사각형 90° × 4, 정육각형 120° × 3 = 360°예요.","정오각형 108°, 정팔각형 135°는 몇 개를 모아도 360°가 딱 되지 않아 빈틈이 생기거나 겹쳐요."],"asset":null},{"stem":"같은 크기의 정다각형 한 가지만으로 바닥을 빈틈없이 채울 수 있는 것은 어느 것인가요?","options":[{"t":"정육각형","correct":true},{"t":"정오각형","mis":"M4-2-u4-X16"},{"t":"정팔각형","mis":"M4-2-u4-X16"},{"t":"정칠각형","mis":"M4-2-u4-X16"}],"explanation":["한 꼭짓점에 모인 각의 합이 꼭 360°가 되어야 빈틈이 없어요.","정삼각형 60° × 6, 정사각형 90° × 4, 정육각형 120° × 3 = 360°예요.","정오각형 108°, 정팔각형 135°는 몇 개를 모아도 360°가 딱 되지 않아 빈틈이 생기거나 겹쳐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L07_challenge#7','math',4,2,'u4','L07','g4_2_math_u4_L07_challenge','lesson_challenge','M4-2-u4-C9',3,'sa','auto','큰 삼각형 모양을 정삼각형 조각으로 채울 때와 사다리꼴 조각으로 채울 때, 필요한 조각 수의 차는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u4-C9","difficulty":3,"kind":"sa","stem":"큰 삼각형 모양을 정삼각형 조각으로 채울 때와 사다리꼴 조각으로 채울 때, 필요한 조각 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["정삼각형으로는 9개예요.","사다리꼴 1개 = 정삼각형 3개이니 사다리꼴으로는 9 ÷ 3 = 3개예요.","9 − 3 = 6개예요."],"asset":{"type":"geo","items":[{"w":106.0,"h":93.9,"poly":[[[8.0,85.94],[98.0,85.94],[53.0,8.0]]],"dash":[[[23.0,59.96],[38.0,85.94]],[[23.0,59.96],[53.0,59.96]],[[38.0,33.98],[53.0,59.96]],[[38.0,33.98],[68.0,33.98]],[[38.0,85.94],[53.0,59.96]],[[53.0,59.96],[68.0,33.98]],[[53.0,59.96],[68.0,85.94]],[[53.0,59.96],[83.0,59.96]],[[68.0,85.94],[83.0,59.96]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"평행사변형 모양을 정삼각형 조각으로 채울 때와 마름모 조각으로 채울 때, 필요한 조각 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["정삼각형으로는 6개예요.","마름모 1개 = 정삼각형 2개이니 마름모으로는 6 ÷ 2 = 3개예요.","6 − 3 = 3개예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":42.0,"poly":[[[8.0,33.98],[98.0,33.98],[113.0,8.0],[23.0,8.0]]],"dash":[[[23.0,8.0],[38.0,33.98]],[[38.0,33.98],[53.0,8.0]],[[53.0,8.0],[68.0,33.98]],[[68.0,33.98],[83.0,8.0]],[[83.0,8.0],[98.0,33.98]]]}],"tag":false}},{"stem":"평행사변형 모양을 정삼각형 조각으로 채울 때와 사다리꼴 조각으로 채울 때, 필요한 조각 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["정삼각형으로는 6개예요.","사다리꼴 1개 = 정삼각형 3개이니 사다리꼴으로는 6 ÷ 3 = 2개예요.","6 − 2 = 4개예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":42.0,"poly":[[[8.0,33.98],[98.0,33.98],[113.0,8.0],[23.0,8.0]]],"dash":[[[23.0,8.0],[38.0,33.98]],[[38.0,33.98],[53.0,8.0]],[[53.0,8.0],[68.0,33.98]],[[68.0,33.98],[83.0,8.0]],[[83.0,8.0],[98.0,33.98]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L07_challenge#8','math',4,2,'u4','L07','g4_2_math_u4_L07_challenge','lesson_challenge','M4-2-u4-C9',4,'sa','auto','정오각형 조각 3개를 한 꼭짓점에 빈틈없이 붙여 모았더니 틈이 생겼어요. 정오각형의 한 각이 108°일 때 생긴 틈의 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u4-C9","difficulty":4,"kind":"sa","stem":"정오각형 조각 3개를 한 꼭짓점에 빈틈없이 붙여 모았더니 틈이 생겼어요. 정오각형의 한 각이 108°일 때 생긴 틈의 각은 몇 도인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["한 점을 둘러싼 한 바퀴는 360°예요.","정오각형 3개의 각: 108° × 3 = 324°예요.","틈: 360° − 324° = 36°예요."],"variant_rule":{"alt":[{"stem":"정팔각형 조각 2개를 한 꼭짓점에 빈틈없이 붙여 모았더니 틈이 생겼어요. 정팔각형의 한 각이 135°일 때 생긴 틈의 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["한 점을 둘러싼 한 바퀴는 360°예요.","정팔각형 2개의 각: 135° × 2 = 270°예요.","틈: 360° − 270° = 90°예요."],"asset":null},{"stem":"정십각형 조각 2개를 한 꼭짓점에 빈틈없이 붙여 모았더니 틈이 생겼어요. 정십각형의 한 각이 144°일 때 생긴 틈의 각은 몇 도인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["한 점을 둘러싼 한 바퀴는 360°예요.","정십각형 2개의 각: 144° × 2 = 288°예요.","틈: 360° − 288° = 72°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L07_challenge#9','math',4,2,'u4','L07','g4_2_math_u4_L07_challenge','lesson_challenge','M4-2-u4-C9',4,'sa','auto','한 꼭짓점에 정팔각형 2개와 정사각형 1개가 빈틈없이 모였어요. 정사각형의 한 각이 90°일 때 정팔각형의 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-2-u4-C9","difficulty":4,"kind":"sa","stem":"한 꼭짓점에 정팔각형 2개와 정사각형 1개가 빈틈없이 모였어요. 정사각형의 한 각이 90°일 때 정팔각형의 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["135"],"explanation":["빈틈없이 모인 각의 합은 360°예요.","정사각형 1개: 90° × 1 = 90°, 남은 각은 360° − 90° = 270°예요.","정팔각형 2개가 나누어 가지니 270 ÷ 2 = 135°예요."],"variant_rule":{"alt":[{"stem":"한 꼭짓점에 정삼각형 2개와 정육각형 2개가 빈틈없이 모였어요. 정육각형의 한 각이 120°일 때 정삼각형의 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["빈틈없이 모인 각의 합은 360°예요.","정육각형 2개: 120° × 2 = 240°, 남은 각은 360° − 240° = 120°예요.","정삼각형 2개가 나누어 가지니 120 ÷ 2 = 60°예요."],"asset":null},{"stem":"한 꼭짓점에 정삼각형 3개와 정사각형 2개가 빈틈없이 모였어요. 정사각형의 한 각이 90°일 때 정삼각형의 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["빈틈없이 모인 각의 합은 360°예요.","정사각형 2개: 90° × 2 = 180°, 남은 각은 360° − 180° = 180°예요.","정삼각형 3개가 나누어 가지니 180 ÷ 3 = 60°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L07_challenge#10','math',4,2,'u4','L07','g4_2_math_u4_L07_challenge','lesson_challenge','M4-2-u4-C9',4,'essay','teacher','정오각형의 한 각은 108°예요. 같은 크기의 정오각형만으로는 바닥을 빈틈없이 채울 수 없는 까닭을 각의 크기를 써서 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u4-C9","difficulty":4,"kind":"essay","stem":"정오각형의 한 각은 108°예요. 같은 크기의 정오각형만으로는 바닥을 빈틈없이 채울 수 없는 까닭을 각의 크기를 써서 설명해 보세요.","answer_guide":{"answer":"예: 바닥을 빈틈없이 채우려면 한 꼭짓점에 모인 각의 합이 360°가 되어야 한다. 정오각형 3개를 모으면 108° × 3 = 324°로 36°만큼 틈이 생기고, 4개를 모으면 432°로 360°를 넘어 겹친다. 그래서 정오각형만으로는 빈틈없이 채울 수 없다.","scoring_points":["한 점에 모인 각의 합이 360°가 되어야 한다고 썼는가","3개는 324°로 틈이 생긴다고 썼는가","4개는 360°를 넘어 겹친다고 썼는가"]},"explanation":["빈틈없이 채우려면 한 점에 모인 각의 합이 360°.","108° × 3 = 324°(틈 36°), 108° × 4 = 432°(겹침).","그래서 정오각형만으로는 채울 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L08_basic#1','math',4,2,'u4','L08','g4_2_math_u4_L08_basic','lesson_basic','M4-2-u4-C10',1,'mc','auto','오각형은 변이 몇 개인 다각형인가요?',ARRAY['M4-2-u4-X04','M4-2-u4-X06']::text[],true,'{"seq":1,"concept":"M4-2-u4-C10","difficulty":1,"kind":"mc","stem":"오각형은 변이 몇 개인 다각형인가요?","options":[{"t":"5개","correct":true},{"t":"4개","mis":"M4-2-u4-X04"},{"t":"6개","mis":"M4-2-u4-X06"},{"t":"3개","mis":"M4-2-u4-X04"}],"explanation":["오각형은 변이 5개, 꼭짓점이 5개인 다각형이에요.","조각을 모아 만든 도형은 바깥쪽 변만 세어 이름을 붙여요.","쓴 조각의 수나 안쪽 선은 이름과 상관없어요."],"variant_rule":{"alt":[{"stem":"조각을 모아 만든 도형이 오각형인지 알아보려면 무엇을 세어야 하나요?","options":[{"t":"바깥쪽 변의 수","correct":true},{"t":"쓴 조각의 수","mis":"M4-2-u4-X17"},{"t":"조각끼리 맞댄 선의 수","mis":"M4-2-u4-X17"},{"t":"조각의 색깔 수","mis":"M4-2-u4-X17"}],"explanation":["오각형은 변이 5개, 꼭짓점이 5개인 다각형이에요.","조각을 모아 만든 도형은 바깥쪽 변만 세어 이름을 붙여요.","쓴 조각의 수나 안쪽 선은 이름과 상관없어요."],"asset":null},{"stem":"조각을 모아 만든 도형의 이름을 정하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"바깥쪽 변의 수를 센다","correct":true},{"t":"쓴 조각의 수를 센다","mis":"M4-2-u4-X17"},{"t":"안쪽 선까지 모두 센다","mis":"M4-2-u4-X17"},{"t":"가장 큰 조각의 이름을 따른다","mis":"M4-2-u4-X17"}],"explanation":["오각형은 변이 5개, 꼭짓점이 5개인 다각형이에요.","조각을 모아 만든 도형은 바깥쪽 변만 세어 이름을 붙여요.","쓴 조각의 수나 안쪽 선은 이름과 상관없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L08_basic#2','math',4,2,'u4','L08','g4_2_math_u4_L08_basic','lesson_basic','M4-2-u4-C10',1,'sa','auto','아래는 조각 3개로 만든 오각형이에요. 정사각형 조각은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u4-C10","difficulty":1,"kind":"sa","stem":"아래는 조각 3개로 만든 오각형이에요. 정사각형 조각은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["정사각형 조각을 찾아 표시해요.","하나씩 세요.","정사각형 조각은 2개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.0,-1.0],[0.0,-1.0]]},{"p":[[0.0,-1.0],[1.0,-1.0],[1.0,-2.0],[0.0,-2.0]]},{"p":[[0.0,-2.0],[1.0,-2.0],[0.5,-2.866]]}],"u":34},"variant_rule":{"alt":[{"stem":"아래는 조각 4개로 만든 오각형이에요. 정사각형 조각은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["정사각형 조각을 찾아 표시해요.","하나씩 세요.","정사각형 조각은 3개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.0,-1.0],[0.0,-1.0]]},{"p":[[1.0,0.0],[2.0,0.0],[2.0,-1.0],[1.0,-1.0]]},{"p":[[2.0,0.0],[3.0,0.0],[3.0,-1.0],[2.0,-1.0]]},{"p":[[3.0,-1.0],[3.0,0.0],[3.866,-0.5]]}],"u":34}},{"stem":"아래는 조각 3개로 만든 오각형이에요. 정삼각형 조각은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["정삼각형 조각을 찾아 표시해요.","하나씩 세요.","정삼각형 조각은 1개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.0,-1.0],[0.0,-1.0]]},{"p":[[0.0,-1.0],[1.0,-1.0],[1.0,-2.0],[0.0,-2.0]]},{"p":[[0.0,-2.0],[1.0,-2.0],[0.5,-2.866]]}],"u":34}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L08_basic#3','math',4,2,'u4','L08','g4_2_math_u4_L08_basic','lesson_basic','M4-2-u4-C10',1,'sa','auto','조각 3개로 만든 오각형과 조각 4개로 만든 오각형이 있어요. 두 오각형에 쓴 조각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u4-C10","difficulty":1,"kind":"sa","stem":"조각 3개로 만든 오각형과 조각 4개로 만든 오각형이 있어요. 두 오각형에 쓴 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["첫째 오각형에 3개를 썼어요.","둘째 오각형에 4개를 썼어요.","3 + 4 = 7개예요."],"variant_rule":{"alt":[{"stem":"조각 2개로 만든 오각형과 조각 4개로 만든 오각형이 있어요. 두 오각형에 쓴 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["첫째 오각형에 2개를 썼어요.","둘째 오각형에 4개를 썼어요.","2 + 4 = 6개예요."],"asset":null},{"stem":"조각 3개로 만든 오각형과 조각 2개로 만든 오각형이 있어요. 두 오각형에 쓴 조각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["첫째 오각형에 3개를 썼어요.","둘째 오각형에 2개를 썼어요.","3 + 2 = 5개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
