INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L08_basic#5','math',4,2,'u4','L08','g4_2_math_u4_L08_basic','lesson_basic','M4-2-u4-C10',2,'mc','auto','조각 3개로 만든 오각형과 조각 4개로 만든 오각형의 공통점은 무엇인가요?',ARRAY['M4-2-u4-X17','M4-2-u4-X05','M4-2-u4-X07']::text[],true,'{"seq":5,"concept":"M4-2-u4-C10","difficulty":2,"kind":"mc","stem":"조각 3개로 만든 오각형과 조각 4개로 만든 오각형의 공통점은 무엇인가요?","options":[{"t":"변이 5개이고 꼭짓점도 5개이다","correct":true},{"t":"쓴 조각의 수가 같다","mis":"M4-2-u4-X17"},{"t":"모양과 크기가 같다","mis":"M4-2-u4-X05"},{"t":"정다각형이다","mis":"M4-2-u4-X07"}],"explanation":["조각의 수·모양·크기가 달라도","바깥쪽 변이 5개, 꼭짓점이 5개면","모두 오각형이에요."],"variant_rule":{"alt":[{"stem":"조각의 수를 늘려서도 오각형을 만들 수 있나요?","options":[{"t":"조각 수가 달라도 바깥쪽 변이 5개이면 오각형이다","correct":true},{"t":"조각이 3개일 때만 만들 수 있다","mis":"M4-2-u4-X18"},{"t":"조각이 많으면 오각형이 될 수 없다","mis":"M4-2-u4-X17"},{"t":"정사각형 조각으로만 만들 수 있다","mis":"M4-2-u4-X18"}],"explanation":["조각의 수·모양·크기가 달라도","바깥쪽 변이 5개, 꼭짓점이 5개면","모두 오각형이에요."],"asset":null},{"stem":"조각 2개로 만든 오각형과 조각 3개로 만든 오각형이 있어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 바깥쪽 변이 5개라서 오각형이다","correct":true},{"t":"조각이 3개인 것은 삼각형이다","mis":"M4-2-u4-X17"},{"t":"크기가 다르니 하나만 오각형이다","mis":"M4-2-u4-X05"},{"t":"조각 수가 적은 것만 오각형이다","mis":"M4-2-u4-X17"}],"explanation":["조각의 수·모양·크기가 달라도","바깥쪽 변이 5개, 꼭짓점이 5개면","모두 오각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L08_basic#6','math',4,2,'u4','L08','g4_2_math_u4_L08_basic','lesson_basic','M4-2-u4-C10',2,'mc','auto','조각 3개를 모아 만든 도형이에요. 이 도형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X17','M4-2-u4-X04']::text[],true,'{"seq":6,"concept":"M4-2-u4-C10","difficulty":2,"kind":"mc","stem":"조각 3개를 모아 만든 도형이에요. 이 도형의 이름은 무엇인가요?","options":[{"t":"오각형","correct":true},{"t":"삼각형","mis":"M4-2-u4-X17"},{"t":"십일각형","mis":"M4-2-u4-X17"},{"t":"육각형","mis":"M4-2-u4-X04"}],"explanation":["조각끼리 맞댄 점선은 세지 않아요.","바깥쪽을 한 바퀴 돌며 세면 변이 5개 — 곧게 이어진 선은 하나로 세요.","그래서 오각형이에요."],"asset":{"type":"geo","items":[{"w":42.0,"h":90.5,"poly":[[[8.0,30.52],[8.0,82.52],[34.0,82.52],[34.0,30.52],[21.0,8.0]]],"dash":[[[8.0,30.52],[34.0,30.52]],[[8.0,56.52],[34.0,56.52]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"조각 4개를 모아 만든 도형이에요. 이 도형의 이름은 무엇인가요?","options":[{"t":"오각형","correct":true},{"t":"사각형","mis":"M4-2-u4-X17"},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"칠각형","mis":"M4-2-u4-X04"}],"explanation":["조각끼리 맞댄 점선은 세지 않아요.","바깥쪽을 한 바퀴 돌며 세면 변이 5개 — 곧게 이어진 선은 하나로 세요.","그래서 오각형이에요."],"asset":{"type":"geo","items":[{"w":116.5,"h":42.0,"poly":[[[8.0,8.0],[8.0,34.0],[86.0,34.0],[108.52,21.0],[86.0,8.0]]],"dash":[[[34.0,8.0],[34.0,34.0]],[[60.0,8.0],[60.0,34.0]],[[86.0,8.0],[86.0,34.0]]]}],"tag":false}},{"stem":"조각 4개를 모아 만든 도형이에요. 이 도형의 이름은 무엇인가요?","options":[{"t":"오각형","correct":true},{"t":"사각형","mis":"M4-2-u4-X17"},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"칠각형","mis":"M4-2-u4-X04"}],"explanation":["조각끼리 맞댄 점선은 세지 않아요.","바깥쪽을 한 바퀴 돌며 세면 변이 5개 — 곧게 이어진 선은 하나로 세요.","그래서 오각형이에요."],"asset":{"type":"geo","items":[{"w":94.0,"h":61.0,"poly":[[[8.0,53.03],[86.0,53.03],[73.0,30.52],[86.0,8.0],[34.0,8.0]]],"dash":[[[21.0,30.52],[34.0,53.03]],[[60.0,8.0],[73.0,30.52]],[[60.0,53.03],[73.0,30.52]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UP