INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L08_basic#8','math',4,2,'u4','L08','g4_2_math_u4_L08_basic','lesson_basic','M4-2-u4-C10',2,'ox','auto','조각 4개로 만든 도형은 언제나 사각형이에요.',ARRAY['M4-2-u4-X17']::text[],true,'{"seq":8,"concept":"M4-2-u4-C10","difficulty":2,"kind":"ox","stem":"조각 4개로 만든 도형은 언제나 사각형이에요.","answer":"X","reason_options":[{"t":"도형의 이름은 조각 수가 아니라 바깥쪽 변의 수로 정해서","correct":true},{"t":"조각이 4개면 사각형이라서","mis":"M4-2-u4-X17"}],"mis":"M4-2-u4-X17","explanation":["조각을 모아 만든 도형의 변은 바깥쪽 선이에요.","조각끼리 맞댄 안쪽 선은 세지 않고, 곧게 이어진 선은 하나로 세요.","이름은 바깥쪽 변의 수로만 정해요."],"variant_rule":{"alt":[{"stem":"정사각형 조각 1개 위에 정삼각형 조각 1개를 붙이면 오각형이 돼요.","answer":"O","reason_options":[{"t":"바깥쪽 변이 5개라서","correct":true},{"t":"조각이 2개뿐이라 이각형이라서","mis":"M4-2-u4-X17"}],"explanation":["조각을 모아 만든 도형의 변은 바깥쪽 선이에요.","조각끼리 맞댄 안쪽 선은 세지 않고, 곧게 이어진 선은 하나로 세요.","이름은 바깥쪽 변의 수로만 정해요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.0,-1.0],[0.0,-1.0]]},{"p":[[0.0,-1.0],[1.0,-1.0],[0.5,-1.866]]}],"u":34}},{"stem":"정삼각형 조각 여러 개를 한 줄로 번갈아 이어 붙이면 조각 수만큼 변이 늘어요.","answer":"X","reason_options":[{"t":"맞댄 선은 변이 아니고 바깥쪽 변은 4개 그대로라서","correct":true},{"t":"조각마다 변이 3개씩 늘어서","mis":"M4-2-u4-X17"}],"explanation":["조각을 모아 만든 도형의 변은 바깥쪽 선이에요.","조각끼리 맞댄 안쪽 선은 세지 않고, 곧게 이어진 선은 하나로 세요.","이름은 바깥쪽 변의 수로만 정해요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[0.5,-0.866]]},{"p":[[1.5,-0.866],[0.5,-0.866],[1.0,0.0]]},{"p":[[1.0,0.0],[2.0,0.0],[1.5,-0.866]]},{"p":[[2.5,-0.866],[1.5,-0.866],[2.0,0.0]]},{"p":[[2.0,0.0],[3.0,0.0],[2.5,-0.866]]}],"u":34}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_acti