INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L08_challenge#4','math',4,2,'u4','L08','g4_2_math_u4_L08_challenge','lesson_challenge','M4-2-u4-C10',3,'error','auto','조각을 모아 만든 아래 도형을 보고 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u4-X17','M4-2-u4-X20']::text[],true,'{"seq":4,"concept":"M4-2-u4-C10","difficulty":3,"kind":"error","stem":"조각을 모아 만든 아래 도형을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「조각을 3개 썼으니까 삼각형이야.」","correct":true,"mis_target":"M4-2-u4-X17"},{"t":"민서 — 「바깥쪽 변을 세면 4개야.」","mis":"M4-2-u4-X20"},{"t":"도윤 — 「이 도형은 사각형이야.」","mis":"M4-2-u4-X20"},{"t":"서윤 — 「점선은 조각끼리 맞댄 선이라 세지 않아.」","mis":"M4-2-u4-X20"}],"explanation":["만든 도형의 변은 바깥쪽 선만 세요.","바깥쪽 변 = 꼭짓점 = 4개 — 사각형이에요.","준서의 말은 조각 수나 안쪽 선을 센 것이라 틀렸어요."],"asset":{"type":"geo","items":[{"w":68.0,"h":38.5,"poly":[[[8.0,30.52],[60.0,30.52],[47.0,8.0],[21.0,8.0]]],"dash":[[[21.0,8.0],[34.0,30.52]],[[34.0,30.52],[47.0,8.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 조각을 모아 만든 아래 도형을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「조각들의 변을 모두 더하면 9개니까 변이 9개야.」","correct":true,"mis_target":"M4-2-u4-X17"},{"t":"도윤 — 「이 도형은 오각형이야.」","mis":"M4-2-u4-X20"},{"t":"서윤 — 「점선은 조각끼리 맞댄 선이라 세지 않아.」","mis":"M4-2-u4-X20"},{"t":"시우 — 「꼭짓점도 5개야.」","mis":"M4-2-u4-X20"}],"explanation":["만든 도형의 변은 바깥쪽 선만 세요.","바깥쪽 변 = 꼭짓점 = 5개 — 오각형이에요.","민서의 말은 조각 수나 안쪽 선을 센 것이라 틀렸어요."],"asset":{"type":"geo","items":[{"w":68.0,"h":83.5,"poly":[[[60.0,30.52],[47.0,8.0],[21.0,8.0],[8.0,30.52],[34.0,75.55]]],"dash":[[[21.0,53.03],[47.0,53.03]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 조각을 모아 만든 아래 도형을 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「조각 4개의 꼭짓점을 모두 세면 15개니까 이 도형의 꼭짓점도 15개야.」","correct":true,"mis_target":"M4-2-u4-X17"},{"t":"서윤 — 「점선은 조각끼리 맞댄 선이라 세지 않아.」","mis":"M4-2-u4-X20"},{"t":"시우 — 「꼭짓점도 5개야.」","mis":"M4-2-u4-X20"},{"t":"은우 — 「바깥쪽 변을 세면 5개야.」","mis":"M4-2-u4-X20"}],"explanation":["