INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_L08_challenge#10','math',4,2,'u4','L08','g4_2_math_u4_L08_challenge','lesson_challenge','M4-2-u4-C10',4,'essay','teacher','정사각형 조각 2개와 정삼각형 조각 1개로 만든 도형, 정사각형 조각 3개와 정삼각형 조각 1개로 만든 도형이 있어요. 두 도형이 모두 오각형인 까닭과, 쓴 조각의 수로 이름을 정하면 안 되는 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-2-u4-C10","difficulty":4,"kind":"essay","stem":"정사각형 조각 2개와 정삼각형 조각 1개로 만든 도형, 정사각형 조각 3개와 정삼각형 조각 1개로 만든 도형이 있어요. 두 도형이 모두 오각형인 까닭과, 쓴 조각의 수로 이름을 정하면 안 되는 까닭을 써 보세요.","answer_guide":{"answer":"예: 두 도형 모두 바깥쪽 변을 세면 5개이고 꼭짓점도 5개라서 오각형이다. 조각끼리 맞댄 선은 도형의 안쪽에 있어 변이 아니고, 쓴 조각이 3개, 4개로 달라도 바깥쪽 변의 수가 같으면 이름이 같다. 그래서 이름은 조각의 수가 아니라 바깥쪽 변의 수로 정해야 한다.","scoring_points":["두 도형 모두 바깥쪽 변이 5개라고 썼는가","맞댄 선은 변이 아니라고 썼는가","이름은 조각 수가 아니라 변의 수로 정한다고 썼는가"]},"explanation":["두 도형 모두 바깥쪽 변이 5개예요.","조각끼리 맞댄 선은 안쪽 선이라 변이 아니에요.","이름은 바깥쪽 변의 수로 정해요."],"asset":{"type":"geo","items":[{"w":42.0,"h":90.5,"poly":[[[8.0,30.52],[8.0,82.52],[34.0,82.52],[34.0,30.52],[21.0,8.0]]],"dash":[[[8.0,30.52],[34.0,30.52]],[[8.0,56.52],[34.0,56.52]]],"cap":"조각 3개"},{"w":116.5,"h":42.0,"poly":[[[8.0,8.0],[8.0,34.0],[86.0,34.0],[108.52,21.0],[86.0,8.0]]],"dash":[[[34.0,8.0],[34.0,34.0]],[[60.0,8.0],[60.0,34.0]],[[86.0,8.0],[86.0,34.0]]],"cap":"조각 4개"}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_a#1','math',4,2,'u4','','g4_2_math_u4_review_a','unit_review','M4-2-u4-C1',1,'mc','auto','다각형인 것은 어느 것인가요?',ARRAY['M4-2-u4-X01']::text[],true,'{"seq":1,"concept":"M4-2-u4-C1","difficulty":1,"kind":"mc","stem":"다각형인 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-2-u4-X01"},{"t":"㉰","mis":"M4-2-u4-X01"},{"t":"㉱","mis":"M4-2-u4-X01"}],"explanation":["다각형은 선분으로만 둘러싸인 도형이에요.","㉯만 곡선 없이 선분으로 빈틈없이 둘러싸여 있어요.","곡선이 섞였거나 끝이 열린 도형은 다각형이 아니에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[8.0,72.0],[8.0,40.0]],[[88.0,40.0],[88.0,72.0]],[[8.0,72.0],[88.0,72.0]]],"curve":[[[8.0,40.0],[88.0,40.0],[48.0,-19.2]]]},{"w":96,"h":80,"poly":[[[8.0,72.0],[8.0,32.0],[48.0,8.0],[88.0,32.0],[88.0,72.0]]]},{"w":96,"h":80,"seg":[[[25.6,72.0],[8.0,72.0]],[[8.0,72.0],[8.0,32.0]],[[8.0,32.0],[48.0,8.0]],[[48.0,8.0],[88.0,32.0]],[[88.0,32.0],[88.0,72.0]],[[88.0,72.0],[54.4,72.0]]]},{"w":96,"h":80,"circle":[[[48.0,40.0],33.6]]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 다각형인 것은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"M4-2-u4-X01"},{"t":"㉯","mis":"M4-2-u4-X01"},{"t":"㉰","mis":"M4-2-u4-X01"}],"explanation":["다각형은 선분으로만 둘러싸인 도형이에요.","㉱만 곡선 없이 선분으로 빈틈없이 둘러싸여 있어요.","곡선이 섞였거나 끝이 열린 도형은 다각형이 아니에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[8.0,60.8],[88.0,60.8]]],"curve":[[[8.0,60.8],[88.0,60.8],[48.0,-12.8]]]},{"w":96,"h":80,"seg":[[[24.0,8.0],[72.0,8.0]],[[72.0,8.0],[88.0,40.0]],[[88.0,40.0],[72.0,72.0]],[[72.0,72.0],[24.0,72.0]],[[24.0,72.0],[8.0,40.0]]]},{"w":96,"h":80,"seg":[[[8.0,8.0],[88.0,8.0]],[[88.0,8.0],[88.0,72.0]],[[8.0,72.0],[8.0,8.0]]],"curve":[[[88.0,72.0],[8.0,72.0],[48.0,41.6]]]},{"w":96,"h":80,"poly":[[[8.0,72.0],[8.0,8.0],[32.0,32.0],[56.0,8.0],[88.0,40.0],[88.0,72.0]]]}]}},{"stem":"이번에는 다른 그림이에요. 다각형인 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-2-u4-X01"},{"t":"㉰","mis":"M4-2-u4-X01"},{"t":"㉱","mis":"M4-2-u4-X01"}],"explanation":["다각형은 선분으로만 둘러싸인 도형이에요.","㉮만 곡선 없이 선분으로 빈틈없이 둘러싸여 있어요.","곡선이 섞였거나 끝이 열린 도형은 다각형이 아니에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,72.0],[48.0,8.0],[88.0,72.0]]]},{"w":96,"h":80,"curve":[[[9.6,40.0],[86.4,40.0],[48.0,-6.4]],[[86.4,40.0],[9.6,40.0],[48.0,86.4]]]},{"w":96,"h":80,"seg":[[[8.0,72.0],[48.0,8.0]],[[48.0,8.0],[88.0,72.0]],[[88.0,72.0],[22.4,72.0]]]},{"w":96,"h":80,"seg":[[[8.0,72.0],[8.0,40.0]],[[88.0,40.0],[88.0,72.0]],[[8.0,72.0],[88.0,72.0]]],"curve":[[[8.0,40.0],[88.0,40.0],[48.0,-19.2]]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
