INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_a#3','math',4,2,'u4','','g4_2_math_u4_review_a','unit_review','M4-2-u4-C3',1,'mc','auto','변이 5개인 다각형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X04','M4-2-u4-X07']::text[],true,'{"seq":3,"concept":"M4-2-u4-C3","difficulty":1,"kind":"mc","stem":"변이 5개인 다각형의 이름은 무엇인가요?","options":[{"t":"오각형","correct":true},{"t":"사각형","mis":"M4-2-u4-X04"},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"정오각형","mis":"M4-2-u4-X07"}],"explanation":["다각형은 변의 수에 따라 이름을 붙여요.","변의 수와 꼭짓점의 수는 같아요 — 모두 5개예요.","그래서 오각형이에요."],"variant_rule":{"alt":[{"stem":"꼭짓점이 6개인 다각형의 이름은 무엇인가요?","options":[{"t":"육각형","correct":true},{"t":"오각형","mis":"M4-2-u4-X04"},{"t":"칠각형","mis":"M4-2-u4-X06"},{"t":"정육각형","mis":"M4-2-u4-X07"}],"explanation":["다각형은 변의 수에 따라 이름을 붙여요.","변의 수와 꼭짓점의 수는 같아요 — 모두 6개예요.","그래서 육각형이에요."],"asset":null},{"stem":"선분 7개로 둘러싸인 도형의 이름은 무엇인가요?","options":[{"t":"칠각형","correct":true},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"팔각형","mis":"M4-2-u4-X04"},{"t":"정칠각형","mis":"M4-2-u4-X07"}],"explanation":["다각형은 변의 수에 따라 이름을 붙여요.","변의 수와 꼭짓점의 수는 같아요 — 모두 7개예요.","그래서 칠각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_a#4','math',4,2,'u4','','g4_2_math_u4_review_a','unit_review','M4-2-u4-C4',1,'mc','auto','정다각형은 어떤 다각형인가요?',ARRAY['M4-2-u4-X07','M4-2-u4-X08','M4-2-u4-X02']::text[],true,'{"seq":4,"concept":"M4-2-u4-C4","difficulty":1,"kind":"mc","stem":"정다각형은 어떤 다각형인가요?","options":[{"t":"변의 길이가 모두 같고 각의 크기도 모두 같은 다각형","correct":true},{"t":"변의 길이가 모두 같은 다각형","mis":"M4-2-u4-X07"},{"t":"각의 크기가 모두 같은 다각형","mis":"M4-2-u4-X08"},{"t":"변이 다섯 개보다 많은 다각형","mis":"M4-2-u4-X02"}],"explanation":["정다각형은 변의 길이가 모두 같고, 그리고 각의 크기도 모두 같은 다각형이에요.","둘 가운데 하나만 같으면 정다각형이 아니에요.","자로 변의 길이를, 각도기로 각의 크기를 재어 확인해요."],"variant_rule":{"alt":[{"stem":"변의 길이가 모두 같고 각의 크기가 모두 같은 다각형을 무엇이라고 하나요?","options":[{"t":"정다각형","correct":true},{"t":"다각형","mis":"M4-2-u4-X07"},{"t":"대각선","mis":"M4-2-u4-X11"},{"t":"정사각형","mis":"M4-2-u4-X03"}],"explanation":["정다각형은 변의 길이가 모두 같고, 그리고 각의 크기도 모두 같은 다각형이에요.","둘 가운데 하나만 같으면 정다각형이 아니에요.","자로 변의 길이를, 각도기로 각의 크기를 재어 확인해요."],"asset":null},{"stem":"정다각형인지 알아보려면 무엇을 확인해야 하나요?","options":[{"t":"변의 길이와 각의 크기를 모두","correct":true},{"t":"변의 길이만","mis":"M4-2-u4-X07"},{"t":"각의 크기만","mis":"M4-2-u4-X08"},{"t":"도형의 크기만","mis":"M4-2-u4-X10"}],"explanation":["정다각형은 변의 길이가 모두 같고, 그리고 각의 크기도 모두 같은 다각형이에요.","둘 가운데 하나만 같으면 정다각형이 아니에요.","자로 변의 길이를, 각도기로 각의 크기를 재어 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_a#5','math',4,2,'u4','','g4_2_math_u4_review_a','unit_review','M4-2-u4-C5',1,'sa','auto','한 변의 길이가 4 cm인 정육각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u4-C5","difficulty":1,"kind":"sa","stem":"한 변의 길이가 4 cm인 정육각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["정육각형은 변이 6개이고 길이가 모두 같아요.","모든 변의 길이의 합 = 한 변 × 변의 수예요.","4 × 6 = 24 cm예요."],"asset":{"type":"geo","items":[{"w":124.0,"h":117.8,"poly":[[[77.0,93.837168574],[31.0,93.837168574],[8.0,54.0],[31.0,14.162831426],[77.0,14.162831426],[100.0,54.0]]],"tick":[[[77.0,93.837168574],[31.0,93.837168574],1],[[31.0,93.837168574],[8.0,54.0],1],[[8.0,54.0],[31.0,14.162831426],1],[[31.0,14.162831426],[77.0,14.162831426],1],[[77.0,14.162831426],[100.0,54.0],1],[[100.0,54.0],[77.0,93.837168574],1]],"lab":[[[54.0,113.8],"4 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"한 변의 길이가 5 cm인 정팔각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["정팔각형은 변이 8개이고 길이가 모두 같아요.","모든 변의 길이의 합 = 한 변 × 변의 수예요.","5 × 8 = 40 cm예요."],"asset":null},{"stem":"한 변의 길이가 7 cm인 정오각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["정오각형은 변이 5개이고 길이가 모두 같아요.","모든 변의 길이의 합 = 한 변 × 변의 수예요.","7 × 5 = 35 cm예요."],"asset":{"type":"geo","items":[{"w":121.7,"h":115.2,"poly":[[[81.038121605,91.214781741],[26.961878395,91.214781741],[10.25140025,39.785218259],[54.0,8.0],[97.74859975,39.785218259]]],"tick":[[[81.038121605,91.214781741],[26.961878395,91.214781741],1],[[26.961878395,91.214781741],[10.25140025,39.785218259],1],[[10.25140025,39.785218259],[54.0,8.0],1],[[54.0,8.0],[97.74859975,39.785218259],1],[[97.74859975,39.785218259],[81.038121605,91.214781741],1]],"lab":[[[54.0,111.2],"7 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_a#6','math',4,2,'u4','','g4_2_math_u4_review_a','unit_review','M4-2-u4-C6',1,'mc','auto','오각형 ㄱㄴㄷㄹㅁ에서 대각선은 어느 것인가요?',ARRAY['M4-2-u4-X11']::text[],true,'{"seq":6,"concept":"M4-2-u4-C6","difficulty":1,"kind":"mc","stem":"오각형 ㄱㄴㄷㄹㅁ에서 대각선은 어느 것인가요?","options":[{"t":"선분 ㄱㄷ","correct":true},{"t":"선분 ㄱㄴ","mis":"M4-2-u4-X11"},{"t":"선분 ㄴㄷ","mis":"M4-2-u4-X11"},{"t":"선분 ㄷㄹ","mis":"M4-2-u4-X11"}],"explanation":["꼭짓점 ㄱ과 이웃한 꼭짓점은 ㄴ, ㅁ이에요.","이웃하지 않는 꼭짓점 ㄷ과 이은 선분 ㄱㄷ이 대각선이에요.","이웃한 꼭짓점끼리 이은 선분은 변이에요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[9.5,85.5],"ㄴ":[9.5,38],"ㄷ":[57,9.5],"ㄹ":[104.5,38],"ㅁ":[104.5,85.5]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ에서 대각선은 어느 것인가요?","options":[{"t":"선분 ㄴㄹ","correct":true},{"t":"선분 ㄴㄷ","mis":"M4-2-u4-X11"},{"t":"선분 ㄷㄹ","mis":"M4-2-u4-X11"},{"t":"선분 ㄹㅁ","mis":"M4-2-u4-X11"}],"explanation":["꼭짓점 ㄴ과 이웃한 꼭짓점은 ㄷ, ㄱ이에요.","이웃하지 않는 꼭짓점 ㄹ과 이은 선분 ㄴㄹ이 대각선이에요.","이웃한 꼭짓점끼리 이은 선분은 변이에요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[9.5,38],"ㄴ":[57,9.5],"ㄷ":[104.5,38],"ㄹ":[104.5,66.5],"ㅁ":[57,85.5],"ㅂ":[9.5,66.5]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false}},{"stem":"사각형 ㄱㄴㄷㄹ에서 대각선은 어느 것인가요?","options":[{"t":"선분 ㄷㄱ","correct":true},{"t":"선분 ㄷㄹ","mis":"M4-2-u4-X11"},{"t":"선분 ㄹㄱ","mis":"M4-2-u4-X11"},{"t":"선분 ㄱㄴ","mis":"M4-2-u4-X11"}],"explanation":["꼭짓점 ㄷ과 이웃한 꼭짓점은 ㄹ, ㄴ이에요.","이웃하지 않는 꼭짓점 ㄱ과 이은 선분 ㄷㄱ이 대각선이에요.","이웃한 꼭짓점끼리 이은 선분은 변이에요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[19,19],"ㄴ":[95,9.5],"ㄷ":[104.5,85.5],"ㄹ":[9.5,76]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLU