INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_a#11','math',4,2,'u4','','g4_2_math_u4_review_a','unit_review','M4-2-u4-C4',2,'mc','auto','네 변의 길이가 모두 같지만 네 각의 크기는 같지 않은 사각형이 있어요. 이 도형은 정사각형인가요?',ARRAY['M4-2-u4-X07','M4-2-u4-X04','M4-2-u4-X10']::text[],true,'{"seq":11,"concept":"M4-2-u4-C4","difficulty":2,"kind":"mc","stem":"네 변의 길이가 모두 같지만 네 각의 크기는 같지 않은 사각형이 있어요. 이 도형은 정사각형인가요?","options":[{"t":"각의 크기도 모두 같아야 하므로 정사각형이 아니에요","correct":true},{"t":"변이 모두 같으니 정사각형이에요","mis":"M4-2-u4-X07"},{"t":"변이 4개라서 정사각형이에요","mis":"M4-2-u4-X04"},{"t":"크기가 작아서 정사각형이 아니에요","mis":"M4-2-u4-X10"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같아야 해요.","이 도형은 각의 크기이(가) 모두 같지 않아요.","그래서 정사각형이 아니에요."],"asset":{"type":"geo","items":[{"w":160.0,"h":106.7,"poly":[[[10.0,82.746133918],[94.0,82.746133918],[136.0,10.0],[52.0,10.0]]],"tick":[[[10.0,82.746133918],[94.0,82.746133918],1],[[94.0,82.746133918],[136.0,10.0],1],[[136.0,10.0],[52.0,10.0],1],[[52.0,10.0],[10.0,82.746133918],1]],"lab":[[[23.9,74.7],"60°"],[[84.0,65.4],"120°"],[[122.1,18.0],"60°"],[[62.0,27.3],"120°"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"네 각의 크기가 모두 같지만 네 변의 길이는 같지 않은 사각형이 있어요. 이 도형은 정사각형인가요?","options":[{"t":"변의 길이도 모두 같아야 하므로 정사각형이 아니에요","correct":true},{"t":"각이 모두 같으니 정사각형이에요","mis":"M4-2-u4-X08"},{"t":"변이 4개라서 정사각형이에요","mis":"M4-2-u4-X04"},{"t":"크기가 작아서 정사각형이 아니에요","mis":"M4-2-u4-X10"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같아야 해요.","이 도형은 변의 길이이(가) 모두 같지 않아요.","그래서 정사각형이 아니에요."],"asset":{"type":"geo","items":[{"w":126.0,"h":80.0,"poly":[[[10.0,56.0],[102.0,56.0],[102.0,10.0],[10.0,10.0]]],"lab":[[[56.0,76.0],"6 cm"],[[122.0,33.0],"3 cm"]],"right":[[[10.0,10.0],[10.0,56.0],[102.0,56.0]],[[10.0,56.0],[102.0,56.0],[102.0,10.0]],[[102.0,56.0],[102.0,10.0],[10.0,10.0]],[[102.0,10.0],[10.0,10.0],[10.0,56.0]]]}],"tag":false}},{"stem":"여섯 변의 길이가 모두 같지만 각의 크기는 같지 않은 육각형이 있어요. 이 도형은 정육각형인가요?","options":[{"t":"각의 크기도 모두 같아야 하므로 정육각형이 아니에요","correct":true},{"t":"변이 모두 같으니 정육각형이에요","mis":"M4-2-u4-X07"},{"t":"변이 6개라서 정육각형이에요","mis":"M4-2-u4-X04"},{"t":"크기가 작아서 정육각형이 아니에요","mis":"M4-2-u4-X10"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같아야 해요.","이 도형은 각의 크기이(가) 모두 같지 않아요.","그래서 정육각형이 아니에요."],"asset":{"type":"geo","items":[{"w":224.3,"h":160.7,"poly":[[[52.0,136.740293133],[136.000000001,136.740293133],[200.347733224,82.746133918],[158.347733224,10.0],[74.347733223,10.0],[10.0,63.994159213]]],"tick":[[[52.0,136.740293133],[136.000000001,136.740293133],1],[[136.000000001,136.740293133],[200.347733224,82.746133918],1],[[200.347733224,82.746133918],[158.347733224,10.0],1],[[158.347733224,10.0],[74.347733223,10.0],1],[[74.347733223,10.0],[10.0,63.994159213],1],[[10.0,63.994159213],[52.0,136.740293133],1]],"lab":[[[64.9,121.4],"120°"],[[127.3,118.8],"140°"],[[180.4,80.8],"100°"],[[145.5,25.3],"120°"],[[83.1,28.0],"140°"],[[29.9,66.0],"100°"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_a#12','math',4,2,'u4','','g4_2_math_u4_review_a','unit_review','M4-2-u4-C7',2,'sa','auto','사각형에 대각선을 모두 그었어요. 대각선은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M4-2-u4-C7","difficulty":2,"kind":"sa","stem":"사각형에 대각선을 모두 그었어요. 대각선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["한 꼭짓점을 잡고 이웃하지 않는 꼭짓점을 차례로 이어요.","이미 그은 대각선은 다시 세지 않아요.","사각형의 대각선은 2개예요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[19,19],"ㄴ":[95,9.5],"ㄷ":[104.5,85.5],"ㄹ":[9.5,76]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"dash":[["ㄱ","ㄷ"],["ㄴ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"오각형에 대각선을 모두 그었어요. 대각선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 꼭짓점을 잡고 이웃하지 않는 꼭짓점을 차례로 이어요.","이미 그은 대각선은 다시 세지 않아요.","오각형의 대각선은 5개예요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[19,9.5],"ㄴ":[95,19],"ㄷ":[104.5,66.5],"ㄹ":[57,85.5],"ㅁ":[9.5,57]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"dash":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄴ","ㄹ"],["ㄴ","ㅁ"],["ㄷ","ㅁ"]]}],"tag":false}},{"stem":"육각형에 대각선을 모두 그었어요. 대각선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 꼭짓점을 잡고 이웃하지 않는 꼭짓점을 차례로 이어요.","이미 그은 대각선은 다시 세지 않아요.","육각형의 대각선은 9개예요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[28.5,9.5],"ㄴ":[85.5,9.5],"ㄷ":[104.5,47.5],"ㄹ":[85.5,85.5],"ㅁ":[28.5,85.5],"ㅂ":[9.5,47.5]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"],["ㄴ","ㄹ"],["ㄴ","ㅁ"],["ㄴ","ㅂ"],["ㄷ","ㅁ"],["ㄷ","ㅂ"],["ㄹ","ㅂ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_a#13','math',4,2,'u4','','g4_2_math_u4_review_a','unit_review','M4-2-u4-C8',2,'mc','auto','조각 2개를 이어 붙여 만든 도형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X04','M4-2-u4-X17']::text[],true,'{"seq":13,"concept":"M4-2-u4-C8","difficulty":2,"kind":"mc","stem":"조각 2개를 이어 붙여 만든 도형의 이름은 무엇인가요?","options":[{"t":"육각형","correct":true},{"t":"칠각형","mis":"M4-2-u4-X04"},{"t":"팔각형","mis":"M4-2-u4-X17"},{"t":"오각형","mis":"M4-2-u4-X04"}],"explanation":["만든 도형의 바깥쪽 변만 세요 — 조각끼리 맞댄 안쪽 선은 변이 아니에요.","한 줄로 곧게 이어진 선은 변 하나예요. 바깥쪽 변은 6개예요.","그래서 육각형이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[2.0,0.0],[1.5,-0.866],[0.5,-0.866]]},{"p":[[2.0,0.0],[0.0,0.0],[0.5,0.866],[1.5,0.866]]}],"u":34},"variant_rule":{"alt":[{"stem":"아래와 같이 조각을 이어 붙였어요. 만든 도형의 이름은 무엇인가요?","options":[{"t":"오각형","correct":true},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"칠각형","mis":"M4-2-u4-X17"},{"t":"사각형","mis":"M4-2-u4-X04"}],"explanation":["만든 도형의 바깥쪽 변만 세요 — 조각끼리 맞댄 안쪽 선은 변이 아니에요.","한 줄로 곧게 이어진 선은 변 하나예요. 바깥쪽 변은 5개예요.","그래서 오각형이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.0,-1.0],[0.0,-1.0]]},{"p":[[0.0,-1.0],[1.0,-1.0],[0.5,-1.866]]}],"u":34}},{"stem":"이번에는 다른 그림이에요. 조각 2개를 이어 붙여 만든 도형의 이름은 무엇인가요?","options":[{"t":"오각형","correct":true},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"구각형","mis":"M4-2-u4-X17"},{"t":"사각형","mis":"M4-2-u4-X04"}],"explanation":["만든 도형의 바깥쪽 변만 세요 — 조각끼리 맞댄 안쪽 선은 변이 아니에요.","한 줄로 곧게 이어진 선은 변 하나예요. 바깥쪽 변은 5개예요.","그래서 오각형이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.5,-0.866],[1.0,-1.7321],[0.0,-1.7321],[-0.5,-0.866]]},{"p":[[1.0,0.0],[0.0,0.0],[0.5,0.866]]}],"u":34}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconcepti