INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_a#14','math',4,2,'u4','','g4_2_math_u4_review_a','unit_review','M4-2-u4-C9',2,'sa','auto','아래 정육각형 모양은 정삼각형 조각 6개로 채울 수 있어요. 같은 모양을 마름모 조각으로만 빈틈없이 채우면 조각이 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M4-2-u4-C9","difficulty":2,"kind":"sa","stem":"아래 정육각형 모양은 정삼각형 조각 6개로 채울 수 있어요. 같은 모양을 마름모 조각으로만 빈틈없이 채우면 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["3"],"explanation":["마름모 1개 = 정삼각형 2개예요.","정삼각형 6개만큼을 2개씩 묶어요.","6 ÷ 2 = 3개예요."],"asset":{"type":"geo","items":[{"w":76.0,"h":68.0,"poly":[[[23.0,59.96],[53.0,59.96],[68.0,33.98],[53.0,8.0],[23.0,8.0],[8.0,33.98]]],"dash":[[[8.0,33.98],[38.0,33.98]],[[23.0,8.0],[38.0,33.98]],[[23.0,59.96],[38.0,33.98]],[[38.0,33.98],[53.0,8.0]],[[38.0,33.98],[53.0,59.96]],[[38.0,33.98],[68.0,33.98]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"아래 정육각형 모양은 정삼각형 조각 6개로 채울 수 있어요. 같은 모양을 사다리꼴 조각으로만 빈틈없이 채우면 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["2"],"explanation":["사다리꼴 1개 = 정삼각형 3개예요.","정삼각형 6개만큼을 3개씩 묶어요.","6 ÷ 3 = 2개예요."],"asset":{"type":"geo","items":[{"w":76.0,"h":68.0,"poly":[[[23.0,59.96],[53.0,59.96],[68.0,33.98],[53.0,8.0],[23.0,8.0],[8.0,33.98]]],"dash":[[[8.0,33.98],[38.0,33.98]],[[23.0,8.0],[38.0,33.98]],[[23.0,59.96],[38.0,33.98]],[[38.0,33.98],[53.0,8.0]],[[38.0,33.98],[53.0,59.96]],[[38.0,33.98],[68.0,33.98]]]}],"tag":false}},{"stem":"아래 큰 마름모 모양은 정삼각형 조각 8개로 채울 수 있어요. 같은 모양을 마름모 조각으로만 빈틈없이 채우면 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["4"],"explanation":["마름모 1개 = 정삼각형 2개예요.","정삼각형 8개만큼을 2개씩 묶어요.","8 ÷ 2 = 4개예요."],"asset":{"type":"geo","items":[{"w":106.0,"h":68.0,"poly":[[[8.0,59.96],[68.0,59.96],[98.0,8.0],[38.0,8.0]]],"dash":[[[23.0,33.98],[38.0,59.96]],[[23.0,33.98],[53.0,33.98]],[[38.0,8.0],[53.0,33.98]],[[38.0,59.96],[53.0,33.98]],[[53.0,33.98],[68.0,8.0]],[[53.0,33.98],[68.0,59.96]],[[53.0,33.98],[83.0,33.98]],[[68.0,8.0],[83.0,33.98]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_a#15','math',4,2,'u4','','g4_2_math_u4_review_a','unit_review','M4-2-u4-C10',2,'sa','auto','조각을 모아 만든 아래 도형의 바깥쪽 변은 모두 몇 개인가요? 숫자로 쓰세요. (점선은 조각끼리 맞댄 선이에요.)','{}'::text[],true,'{"seq":15,"concept":"M4-2-u4-C10","difficulty":2,"kind":"sa","stem":"조각을 모아 만든 아래 도형의 바깥쪽 변은 모두 몇 개인가요? 숫자로 쓰세요. (점선은 조각끼리 맞댄 선이에요.)","answer":["7"],"explanation":["점선(안쪽 선)은 세지 않아요.","한 줄로 곧게 이어진 선은 조각이 둘이어도 변 하나예요.","바깥쪽 변은 7개예요."],"asset":{"type":"geo","items":[{"w":68.0,"h":87.0,"poly":[[[34.0,8.0],[8.0,53.03],[21.0,53.03],[21.0,79.03],[47.0,79.03],[47.0,53.03],[60.0,53.03]]],"dash":[[[8.0,53.03],[60.0,53.03]],[[21.0,30.52],[47.0,30.52]],[[21.0,53.03],[47.0,53.03]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 조각을 모아 만든 아래 도형의 바깥쪽 변은 모두 몇 개인가요? 숫자로 쓰세요. (점선은 조각끼리 맞댄 선이에요.)","answer":["6"],"explanation":["점선(안쪽 선)은 세지 않아요.","한 줄로 곧게 이어진 선은 조각이 둘이어도 변 하나예요.","바깥쪽 변은 6개예요."],"asset":{"type":"geo","items":[{"w":94.0,"h":61.0,"poly":[[[8.0,8.0],[21.0,30.52],[8.0,53.03],[86.0,53.03],[73.0,30.52],[86.0,8.0]]],"dash":[[[21.0,30.52],[34.0,8.0]],[[21.0,30.52],[34.0,53.03]],[[60.0,8.0],[73.0,30.52]],[[60.0,53.03],[73.0,30.52]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 조각을 모아 만든 아래 도형의 바깥쪽 변은 모두 몇 개인가요? 숫자로 쓰세요. (점선은 조각끼리 맞댄 선이에요.)","answer":["9"],"explanation":["점선(안쪽 선)은 세지 않아요.","한 줄로 곧게 이어진 선은 조각이 둘이어도 변 하나예요.","바깥쪽 변은 9개예요."],"asset":{"type":"geo","items":[{"w":87.0,"h":90.5,"poly":[[[30.52,30.52],[30.52,56.52],[8.0,69.52],[30.52,82.52],[56.52,82.52],[79.03,69.52],[56.52,56.52],[56.52,30.52],[43.52,8.0]]],"dash":[[[30.52,30.52],[56.52,30.52]],[[30.52,56.52],[30.52,82.52]],[[30.52,56.52],[56.52,56.52]],[[56.52,56.52],[56.52,82.52]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLU