INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_a#18','math',4,2,'u4','','g4_2_math_u4_review_a','unit_review','M4-2-u4-C5',3,'mc','auto','모든 변의 길이의 합이 48 cm이고 한 변의 길이가 6 cm인 정다각형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X09','M4-2-u4-X07']::text[],true,'{"seq":18,"concept":"M4-2-u4-C5","difficulty":3,"kind":"mc","stem":"모든 변의 길이의 합이 48 cm이고 한 변의 길이가 6 cm인 정다각형의 이름은 무엇인가요?","options":[{"t":"정팔각형","correct":true},{"t":"정칠각형","mis":"M4-2-u4-X09"},{"t":"정구각형","mis":"M4-2-u4-X09"},{"t":"팔각형","mis":"M4-2-u4-X07"}],"explanation":["변의 수 = 합 ÷ 한 변이에요.","48 ÷ 6 = 8 — 변이 8개예요.","정다각형이니 정팔각형이에요."],"variant_rule":{"alt":[{"stem":"모든 변의 길이의 합이 35 cm이고 한 변의 길이가 5 cm인 정다각형의 이름은 무엇인가요?","options":[{"t":"정칠각형","correct":true},{"t":"정육각형","mis":"M4-2-u4-X09"},{"t":"정팔각형","mis":"M4-2-u4-X09"},{"t":"칠각형","mis":"M4-2-u4-X07"}],"explanation":["변의 수 = 합 ÷ 한 변이에요.","35 ÷ 5 = 7 — 변이 7개예요.","정다각형이니 정칠각형이에요."],"asset":null},{"stem":"모든 변의 길이의 합이 54 cm이고 한 변의 길이가 9 cm인 정다각형의 이름은 무엇인가요?","options":[{"t":"정육각형","correct":true},{"t":"정오각형","mis":"M4-2-u4-X09"},{"t":"정칠각형","mis":"M4-2-u4-X09"},{"t":"육각형","mis":"M4-2-u4-X07"}],"explanation":["변의 수 = 합 ÷ 한 변이에요.","54 ÷ 9 = 6 — 변이 6개예요.","정다각형이니 정육각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_a#19','math',4,2,'u4','','g4_2_math_u4_review_a','unit_review','M4-2-u4-C7',3,'sa','auto','오각형의 대각선의 수와 육각형의 대각선의 수를 더하면 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M4-2-u4-C7","difficulty":3,"kind":"sa","stem":"오각형의 대각선의 수와 육각형의 대각선의 수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["대각선은 한 꼭짓점에서 (변의 수 − 3)개씩 그어 모두 모은 뒤 겹친 것을 빼요.","오각형 5개, 육각형 9개예요.","5 + 9 = 14개예요."],"variant_rule":{"alt":[{"stem":"팔각형의 변의 수와 팔각형에 그을 수 있는 대각선의 수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["대각선은 한 꼭짓점에서 (변의 수 − 3)개씩 그어 모두 모은 뒤 겹친 것을 빼요.","변 8개, 대각선 20개예요.","8 + 20 = 28개예요."],"asset":null},{"stem":"사각형의 대각선의 수와 칠각형의 대각선의 수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["대각선은 한 꼭짓점에서 (변의 수 − 3)개씩 그어 모두 모은 뒤 겹친 것을 빼요.","사각형 2개, 칠각형 14개예요.","2 + 14 = 16개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_a#20','math',4,2,'u4','','g4_2_math_u4_review_a','unit_review','M4-2-u4-C9',3,'sa','auto','큰 사다리꼴 모양을 여러 가지 조각으로 빈틈없이 채웠어요. 같은 모양을 정삼각형 조각으로만 다시 채우면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M4-2-u4-C9","difficulty":3,"kind":"sa","stem":"큰 사다리꼴 모양을 여러 가지 조각으로 빈틈없이 채웠어요. 같은 모양을 정삼각형 조각으로만 다시 채우면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["12"],"explanation":["조각마다 정삼각형 몇 개와 같은지 바꿔요.","정삼각형 1개(정삼각형 1개), 정육각형 1개(정삼각형 6개), 사다리꼴 1개(정삼각형 3개), 마름모 1개(정삼각형 2개)예요.","모두 정삼각형 12개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.5,-0.866],[1.0,0.0],[2.0,-0.0],[2.5,-0.866],[2.0,-1.7321],[1.0,-1.7321]]},{"p":[[2.0,-0.0],[4.0,-0.0],[3.5,-0.866],[2.5,-0.866]]},{"p":[[1.0,-0.0],[0.5,-0.866],[-0.0,-0.0]]},{"p":[[2.5,-0.866],[3.5,-0.866],[3.0,-1.7321],[2.0,-1.7321]]}],"u":34},"variant_rule":{"alt":[{"stem":"큰 삼각형 모양을 여러 가지 조각으로 빈틈없이 채웠어요. 같은 모양을 정삼각형 조각으로만 다시 채우면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["9"],"explanation":["조각마다 정삼각형 몇 개와 같은지 바꿔요.","정삼각형 3개(정삼각형 3개), 정육각형 1개(정삼각형 6개)예요.","모두 정삼각형 9개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.5,-0.866],[1.0,0.0],[2.0,-0.0],[2.5,-0.866],[2.0,-1.7321],[1.0,-1.7321]]},{"p":[[1.0,-0.0],[0.5,-0.866],[-0.0,-0.0]]},{"p":[[3.0,-0.0],[2.5,-0.866],[2.0,-0.0]]},{"p":[[2.0,-1.7321],[1.5,-2.5981],[1.0,-1.7321]]}],"u":34}},{"stem":"삼각형 모양을 여러 가지 조각으로 빈틈없이 채웠어요. 같은 모양을 정삼각형 조각으로만 다시 채우면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["4"],"explanation":["조각마다 정삼각형 몇 개와 같은지 바꿔요.","정삼각형 1개(정삼각형 1개), 사다리꼴 1개(정삼각형 3개)예요.","모두 정삼각형 4개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,-0.0],[2.0,-0.0],[1.5,-0.866],[0.5,-0.866]]},{"p":[[1.5,-0.866],[1.0,-1.7321],[0.5,-0.866]]}],"u":34}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading