INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_a#22','math',4,2,'u4','','g4_2_math_u4_review_a','unit_review','M4-2-u4-C4',3,'error','auto','정다각형에 대해 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u4-X07','M4-2-u4-X20']::text[],true,'{"seq":22,"concept":"M4-2-u4-C4","difficulty":3,"kind":"error","stem":"정다각형에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「마름모는 네 변이 모두 같으니까 정사각형이야.」","correct":true,"mis_target":"M4-2-u4-X07"},{"t":"준서 — 「정다각형은 변과 각이 모두 같아야 해.」","mis":"M4-2-u4-X20"},{"t":"민서 — 「정팔각형은 변이 8개야.」","mis":"M4-2-u4-X20"},{"t":"도윤 — 「작은 정삼각형도 정다각형이야.」","mis":"M4-2-u4-X20"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같은 다각형이에요.","지아의 말은 그 뜻(또는 계산)과 맞지 않아요.","둘레는 한 변 × 변의 수(정육각형은 6)로 구해요."],"variant_rule":{"alt":[{"stem":"정다각형에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「직사각형은 네 각이 모두 같으니까 정다각형이야.」","correct":true,"mis_target":"M4-2-u4-X08"},{"t":"민서 — 「정팔각형은 변이 8개야.」","mis":"M4-2-u4-X20"},{"t":"도윤 — 「작은 정삼각형도 정다각형이야.」","mis":"M4-2-u4-X20"},{"t":"서윤 — 「정다각형의 둘레는 한 변 × 변의 수야.」","mis":"M4-2-u4-X20"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같은 다각형이에요.","준서의 말은 그 뜻(또는 계산)과 맞지 않아요.","둘레는 한 변 × 변의 수(정육각형은 6)로 구해요."],"asset":null},{"stem":"정다각형에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「한 변이 5 cm인 정육각형의 둘레는 5 × 5 = 25 cm야.」","correct":true,"mis_target":"M4-2-u4-X09"},{"t":"도윤 — 「작은 정삼각형도 정다각형이야.」","mis":"M4-2-u4-X20"},{"t":"서윤 — 「정다각형의 둘레는 한 변 × 변의 수야.」","mis":"M4-2-u4-X20"},{"t":"시우 — 「정다각형은 변과 각이 모두 같아야 해.」","mis":"M4-2-u4-X20"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같은 다각형이에요.","민서의 말은 그 뜻(또는 계산)과 맞지 않아요.","둘레는 한 변 × 변의 수(정육각형은 6)로 구해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_a#23','math',4,2,'u4','','g4_2_math_u4_review_a','unit_review','M4-2-u4-C5',4,'sa','auto','정육각형의 한 꼭짓점에서 대각선을 그어 삼각형 4개로 나누었어요. 정육각형의 한 각의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-2-u4-C5","difficulty":4,"kind":"sa","stem":"정육각형의 한 꼭짓점에서 대각선을 그어 삼각형 4개로 나누었어요. 정육각형의 한 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["모든 각의 합 = 180° × 4 = 720°예요.","정육각형은 각 6개의 크기가 모두 같아요.","720° ÷ 6 = 120°예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":125.3,"pts":{"ㄱ":[83.0,101.301270189],"ㄴ":[33.0,101.301270189],"ㄷ":[8.0,58.0],"ㄹ":[33.0,14.698729811],"ㅁ":[83.0,14.698729811],"ㅂ":[108.0,58.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"정육각형의 한 꼭짓점에서 대각선을 그어 삼각형 4개로 나누었어요. 정육각형의 모든 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["720"],"explanation":["삼각형 하나의 세 각의 합은 180°예요.","삼각형 4개의 각을 모두 모으면 정육각형의 모든 각이 돼요.","180° × 4 = 720°예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":125.3,"pts":{"ㄱ":[83.0,101.301270189],"ㄴ":[33.0,101.301270189],"ㄷ":[8.0,58.0],"ㄹ":[33.0,14.698729811],"ㅁ":[83.0,14.698729811],"ㅂ":[108.0,58.0]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"]]}],"tag":false}},{"stem":"정팔각형의 한 꼭짓점에서 대각선을 그어 삼각형 6개로 나누었어요. 정팔각형의 한 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["135"],"explanation":["모든 각의 합 = 180° × 6 = 1080°예요.","정팔각형은 각 8개의 크기가 모두 같아요.","1080° ÷ 8 = 135°예요."],"asset":{"type":"geo","items":[{"w":128.2,"h":128.2,"pts":{"ㄱ":[77.134171618,104.193976626],"ㄴ":[38.865828382,104.193976626],"ㄷ":[11.806023374,77.134171618],"ㄹ":[11.806023374,38.865828382],"ㅁ":[38.865828382,11.806023374],"ㅂ":[77.134171618,11.806023374],"ㅅ":[104.193976626,38.865828382],"ㅇ":[104.193976626,77.134171618]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅇ"]],"dash":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"],["ㄱ","ㅂ"],["ㄱ","ㅅ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_a#24','math',4,2,'u4','','g4_2_math_u4_review_a','unit_review','M4-2-u4-C7',4,'sa','auto','친구 6명이 둥글게 앉았어요. 바로 옆에 앉은 친구를 빼고 다른 친구와만 한 번씩 악수를 하면 악수는 모두 몇 번인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-2-u4-C7","difficulty":4,"kind":"sa","stem":"친구 6명이 둥글게 앉았어요. 바로 옆에 앉은 친구를 빼고 다른 친구와만 한 번씩 악수를 하면 악수는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["친구(나무)를 육각형의 꼭짓점, 옆끼리를 변이라고 생각해요.","옆이 아닌 둘을 잇는 것은 대각선과 같아요.","육각형의 대각선: 6 × 3 ÷ 2 = 9 — 9예요."],"variant_rule":{"alt":[{"stem":"공원에 나무 5그루가 둥글게 심어져 있어요. 바로 옆 나무끼리는 빼고, 나머지 나무끼리 두 그루씩 줄로 한 번씩 이으면 줄은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["친구(나무)를 오각형의 꼭짓점, 옆끼리를 변이라고 생각해요.","옆이 아닌 둘을 잇는 것은 대각선과 같아요.","오각형의 대각선: 5 × 2 ÷ 2 = 5 — 5예요."],"asset":null},{"stem":"친구 7명이 둥글게 앉았어요. 바로 옆에 앉은 친구를 빼고 다른 친구와만 한 번씩 악수를 하면 악수는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["친구(나무)를 칠각형의 꼭짓점, 옆끼리를 변이라고 생각해요.","옆이 아닌 둘을 잇는 것은 대각선과 같아요.","칠각형의 대각선: 7 × 4 ÷ 2 = 14 — 14예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_a#25','math',4,2,'u4','','g4_2_math_u4_review_a','unit_review','M4-2-u4-C1',4,'essay','teacher','아래 두 도형 가운데 다각형을 고르고, 다른 하나가 다각형이 아닌 까닭을 써 보세요. 그리고 다각형의 이름도 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u4-C1","difficulty":4,"kind":"essay","stem":"아래 두 도형 가운데 다각형을 고르고, 다른 하나가 다각형이 아닌 까닭을 써 보세요. 그리고 다각형의 이름도 써 보세요.","answer_guide":{"answer":"예: ㉯가 다각형이다. ㉮는 한 부분이 곡선이라 선분으로만 둘러싸여 있지 않으므로 다각형이 아니다. ㉯는 선분 6개로 둘러싸여 있으므로 육각형이다.","scoring_points":["㉯를 다각형으로 골랐는가","㉮는 곡선이 섞여 다각형이 아니라고 썼는가","㉯의 이름을 변의 수로 육각형이라고 썼는가"]},"explanation":["㉮는 위쪽이 곡선이에요.","㉯는 선분 6개로 둘러싸여 있어요.","다각형은 ㉯, 이름은 육각형이에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[8.0,72.0],[8.0,40.0]],[[88.0,40.0],[88.0,72.0]],[[8.0,72.0],[88.0,72.0]]],"curve":[[[8.0,40.0],[88.0,40.0],[48.0,-19.2]]]},{"w":96,"h":80,"poly":[[[8.0,8.0],[40.0,8.0],[40.0,40.0],[88.0,40.0],[88.0,72.0],[8.0,72.0]]]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_b#1','math',4,2,'u4','','g4_2_math_u4_review_b','unit_review','M4-2-u4-C1',1,'mc','auto','다각형인 것은 어느 것인가요?',ARRAY['M4-2-u4-X01']::text[],true,'{"seq":1,"concept":"M4-2-u4-C1","difficulty":1,"kind":"mc","stem":"다각형인 것은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"M4-2-u4-X01"},{"t":"㉯","mis":"M4-2-u4-X01"},{"t":"㉰","mis":"M4-2-u4-X01"}],"explanation":["다각형은 선분으로만 둘러싸인 도형이에요.","㉱만 곡선 없이 선분으로 빈틈없이 둘러싸여 있어요.","곡선이 섞였거나 끝이 열린 도형은 다각형이 아니에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[8.0,60.8],[88.0,60.8]]],"curve":[[[8.0,60.8],[88.0,60.8],[48.0,-12.8]]]},{"w":96,"h":80,"seg":[[[24.0,8.0],[72.0,8.0]],[[72.0,8.0],[88.0,40.0]],[[88.0,40.0],[72.0,72.0]],[[72.0,72.0],[24.0,72.0]],[[24.0,72.0],[8.0,40.0]]]},{"w":96,"h":80,"seg":[[[8.0,8.0],[88.0,8.0]],[[88.0,8.0],[88.0,72.0]],[[8.0,72.0],[8.0,8.0]]],"curve":[[[88.0,72.0],[8.0,72.0],[48.0,41.6]]]},{"w":96,"h":80,"poly":[[[8.0,72.0],[8.0,8.0],[32.0,32.0],[56.0,8.0],[88.0,40.0],[88.0,72.0]]]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 다각형인 것은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-2-u4-X01"},{"t":"㉰","mis":"M4-2-u4-X01"},{"t":"㉱","mis":"M4-2-u4-X01"}],"explanation":["다각형은 선분으로만 둘러싸인 도형이에요.","㉮만 곡선 없이 선분으로 빈틈없이 둘러싸여 있어요.","곡선이 섞였거나 끝이 열린 도형은 다각형이 아니에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,72.0],[48.0,8.0],[88.0,72.0]]]},{"w":96,"h":80,"curve":[[[9.6,40.0],[86.4,40.0],[48.0,-6.4]],[[86.4,40.0],[9.6,40.0],[48.0,86.4]]]},{"w":96,"h":80,"seg":[[[8.0,72.0],[48.0,8.0]],[[48.0,8.0],[88.0,72.0]],[[88.0,72.0],[22.4,72.0]]]},{"w":96,"h":80,"seg":[[[8.0,72.0],[8.0,40.0]],[[88.0,40.0],[88.0,72.0]],[[8.0,72.0],[88.0,72.0]]],"curve":[[[8.0,40.0],[88.0,40.0],[48.0,-19.2]]]}]}},{"stem":"이번에는 다른 그림이에요. 다각형인 것은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M4-2-u4-X01"},{"t":"㉯","mis":"M4-2-u4-X01"},{"t":"㉱","mis":"M4-2-u4-X01"}],"explanation":["다각형은 선분으로만 둘러싸인 도형이에요.","㉰만 곡선 없이 선분으로 빈틈없이 둘러싸여 있어요.","곡선이 섞였거나 끝이 열린 도형은 다각형이 아니에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[25.6,72.0],[8.0,72.0]],[[8.0,72.0],[8.0,32.0]],[[8.0,32.0],[48.0,8.0]],[[48.0,8.0],[88.0,32.0]],[[88.0,32.0],[88.0,72.0]],[[88.0,72.0],[54.4,72.0]]]},{"w":96,"h":80,"seg":[[[8.0,8.0],[88.0,8.0]],[[88.0,8.0],[88.0,72.0]],[[8.0,72.0],[8.0,8.0]]],"curve":[[[88.0,72.0],[8.0,72.0],[48.0,41.6]]]},{"w":96,"h":80,"poly":[[[8.0,8.0],[88.0,8.0],[88.0,32.0],[64.0,32.0],[64.0,72.0],[32.0,72.0],[32.0,32.0],[8.0,32.0]]]},{"w":96,"h":80,"seg":[[[8.0,60.8],[88.0,60.8]]],"curve":[[[8.0,60.8],[88.0,60.8],[48.0,-12.8]]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_b#2','math',4,2,'u4','','g4_2_math_u4_review_b','unit_review','M4-2-u4-C2',1,'sa','auto','세계 전통 가옥 체험장에서 찾은 도형이에요. 이 도형의 변은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u4-C2","difficulty":1,"kind":"sa","stem":"세계 전통 가옥 체험장에서 찾은 도형이에요. 이 도형의 변은 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 꼭짓점에서 시작해 한 방향으로 돌며 변에 표시를 해요.","빠뜨리거나 두 번 세지 않게 끝까지 세요.","변은 6개예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,8.0],[40.0,8.0],[40.0,40.0],[88.0,40.0],[88.0,72.0],[8.0,72.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"아래 도형은 변이 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 꼭짓점에서 시작해 한 방향으로 돌며 변에 표시를 해요.","빠뜨리거나 두 번 세지 않게 끝까지 세요.","변은 7개예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[32.0,8.0],[64.0,8.0],[88.0,28.8],[84.8,57.6],[57.6,72.0],[25.6,68.8],[8.0,40.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 세계 전통 가옥 체험장에서 찾은 도형이에요. 이 도형의 변은 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 꼭짓점에서 시작해 한 방향으로 돌며 변에 표시를 해요.","빠뜨리거나 두 번 세지 않게 끝까지 세요.","변은 8개예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,8.0],[32.0,8.0],[32.0,32.0],[64.0,32.0],[64.0,8.0],[88.0,8.0],[88.0,72.0],[8.0,72.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_b#3','math',4,2,'u4','','g4_2_math_u4_review_b','unit_review','M4-2-u4-C3',1,'mc','auto','꼭짓점이 6개인 다각형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X04','M4-2-u4-X06','M4-2-u4-X07']::text[],true,'{"seq":3,"concept":"M4-2-u4-C3","difficulty":1,"kind":"mc","stem":"꼭짓점이 6개인 다각형의 이름은 무엇인가요?","options":[{"t":"육각형","correct":true},{"t":"오각형","mis":"M4-2-u4-X04"},{"t":"칠각형","mis":"M4-2-u4-X06"},{"t":"정육각형","mis":"M4-2-u4-X07"}],"explanation":["다각형은 변의 수에 따라 이름을 붙여요.","변의 수와 꼭짓점의 수는 같아요 — 모두 6개예요.","그래서 육각형이에요."],"variant_rule":{"alt":[{"stem":"선분 7개로 둘러싸인 도형의 이름은 무엇인가요?","options":[{"t":"칠각형","correct":true},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"팔각형","mis":"M4-2-u4-X04"},{"t":"정칠각형","mis":"M4-2-u4-X07"}],"explanation":["다각형은 변의 수에 따라 이름을 붙여요.","변의 수와 꼭짓점의 수는 같아요 — 모두 7개예요.","그래서 칠각형이에요."],"asset":null},{"stem":"변이 8개인 다각형의 이름은 무엇인가요?","options":[{"t":"팔각형","correct":true},{"t":"칠각형","mis":"M4-2-u4-X04"},{"t":"구각형","mis":"M4-2-u4-X04"},{"t":"정팔각형","mis":"M4-2-u4-X07"}],"explanation":["다각형은 변의 수에 따라 이름을 붙여요.","변의 수와 꼭짓점의 수는 같아요 — 모두 8개예요.","그래서 팔각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_b#4','math',4,2,'u4','','g4_2_math_u4_review_b','unit_review','M4-2-u4-C4',1,'mc','auto','변의 길이가 모두 같고 각의 크기가 모두 같은 다각형을 무엇이라고 하나요?',ARRAY['M4-2-u4-X07','M4-2-u4-X11','M4-2-u4-X03']::text[],true,'{"seq":4,"concept":"M4-2-u4-C4","difficulty":1,"kind":"mc","stem":"변의 길이가 모두 같고 각의 크기가 모두 같은 다각형을 무엇이라고 하나요?","options":[{"t":"정다각형","correct":true},{"t":"다각형","mis":"M4-2-u4-X07"},{"t":"대각선","mis":"M4-2-u4-X11"},{"t":"정사각형","mis":"M4-2-u4-X03"}],"explanation":["정다각형은 변의 길이가 모두 같고, 그리고 각의 크기도 모두 같은 다각형이에요.","둘 가운데 하나만 같으면 정다각형이 아니에요.","자로 변의 길이를, 각도기로 각의 크기를 재어 확인해요."],"variant_rule":{"alt":[{"stem":"정다각형인지 알아보려면 무엇을 확인해야 하나요?","options":[{"t":"변의 길이와 각의 크기를 모두","correct":true},{"t":"변의 길이만","mis":"M4-2-u4-X07"},{"t":"각의 크기만","mis":"M4-2-u4-X08"},{"t":"도형의 크기만","mis":"M4-2-u4-X10"}],"explanation":["정다각형은 변의 길이가 모두 같고, 그리고 각의 크기도 모두 같은 다각형이에요.","둘 가운데 하나만 같으면 정다각형이 아니에요.","자로 변의 길이를, 각도기로 각의 크기를 재어 확인해요."],"asset":null},{"stem":"정다각형은 어떤 다각형인가요?","options":[{"t":"변의 길이가 모두 같고 각의 크기도 모두 같은 다각형","correct":true},{"t":"변의 길이가 모두 같은 다각형","mis":"M4-2-u4-X07"},{"t":"각의 크기가 모두 같은 다각형","mis":"M4-2-u4-X08"},{"t":"변이 다섯 개보다 많은 다각형","mis":"M4-2-u4-X02"}],"explanation":["정다각형은 변의 길이가 모두 같고, 그리고 각의 크기도 모두 같은 다각형이에요.","둘 가운데 하나만 같으면 정다각형이 아니에요.","자로 변의 길이를, 각도기로 각의 크기를 재어 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_b#5','math',4,2,'u4','','g4_2_math_u4_review_b','unit_review','M4-2-u4-C5',1,'sa','auto','한 변의 길이가 5 cm인 정팔각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u4-C5","difficulty":1,"kind":"sa","stem":"한 변의 길이가 5 cm인 정팔각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["정팔각형은 변이 8개이고 길이가 모두 같아요.","모든 변의 길이의 합 = 한 변 × 변의 수예요.","5 × 8 = 40 cm예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 7 cm인 정오각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["정오각형은 변이 5개이고 길이가 모두 같아요.","모든 변의 길이의 합 = 한 변 × 변의 수예요.","7 × 5 = 35 cm예요."],"asset":{"type":"geo","items":[{"w":121.7,"h":115.2,"poly":[[[81.038121605,91.214781741],[26.961878395,91.214781741],[10.25140025,39.785218259],[54.0,8.0],[97.74859975,39.785218259]]],"tick":[[[81.038121605,91.214781741],[26.961878395,91.214781741],1],[[26.961878395,91.214781741],[10.25140025,39.785218259],1],[[10.25140025,39.785218259],[54.0,8.0],1],[[54.0,8.0],[97.74859975,39.785218259],1],[[97.74859975,39.785218259],[81.038121605,91.214781741],1]],"lab":[[[54.0,111.2],"7 cm"]]}],"tag":false}},{"stem":"한 변의 길이가 3 cm인 정칠각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["정칠각형은 변이 7개이고 길이가 모두 같아요.","모든 변의 길이의 합 = 한 변 × 변의 수예요.","3 × 7 = 21 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_b#6','math',4,2,'u4','','g4_2_math_u4_review_b','unit_review','M4-2-u4-C6',1,'mc','auto','육각형 ㄱㄴㄷㄹㅁㅂ에서 대각선은 어느 것인가요?',ARRAY['M4-2-u4-X11']::text[],true,'{"seq":6,"concept":"M4-2-u4-C6","difficulty":1,"kind":"mc","stem":"육각형 ㄱㄴㄷㄹㅁㅂ에서 대각선은 어느 것인가요?","options":[{"t":"선분 ㄴㄹ","correct":true},{"t":"선분 ㄴㄷ","mis":"M4-2-u4-X11"},{"t":"선분 ㄷㄹ","mis":"M4-2-u4-X11"},{"t":"선분 ㄹㅁ","mis":"M4-2-u4-X11"}],"explanation":["꼭짓점 ㄴ과 이웃한 꼭짓점은 ㄷ, ㄱ이에요.","이웃하지 않는 꼭짓점 ㄹ과 이은 선분 ㄴㄹ이 대각선이에요.","이웃한 꼭짓점끼리 이은 선분은 변이에요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[9.5,38],"ㄴ":[57,9.5],"ㄷ":[104.5,38],"ㄹ":[104.5,66.5],"ㅁ":[57,85.5],"ㅂ":[9.5,66.5]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"사각형 ㄱㄴㄷㄹ에서 대각선은 어느 것인가요?","options":[{"t":"선분 ㄷㄱ","correct":true},{"t":"선분 ㄷㄹ","mis":"M4-2-u4-X11"},{"t":"선분 ㄹㄱ","mis":"M4-2-u4-X11"},{"t":"선분 ㄱㄴ","mis":"M4-2-u4-X11"}],"explanation":["꼭짓점 ㄷ과 이웃한 꼭짓점은 ㄹ, ㄴ이에요.","이웃하지 않는 꼭짓점 ㄱ과 이은 선분 ㄷㄱ이 대각선이에요.","이웃한 꼭짓점끼리 이은 선분은 변이에요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[19,19],"ㄴ":[95,9.5],"ㄷ":[104.5,85.5],"ㄹ":[9.5,76]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false}},{"stem":"오각형 ㄱㄴㄷㄹㅁ에서 대각선은 어느 것인가요?","options":[{"t":"선분 ㄹㄱ","correct":true},{"t":"선분 ㄹㅁ","mis":"M4-2-u4-X11"},{"t":"선분 ㅁㄱ","mis":"M4-2-u4-X11"},{"t":"선분 ㄱㄴ","mis":"M4-2-u4-X11"}],"explanation":["꼭짓점 ㄹ과 이웃한 꼭짓점은 ㅁ, ㄷ이에요.","이웃하지 않는 꼭짓점 ㄱ과 이은 선분 ㄹㄱ이 대각선이에요.","이웃한 꼭짓점끼리 이은 선분은 변이에요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[19,9.5],"ㄴ":[95,19],"ㄷ":[104.5,66.5],"ㄹ":[57,85.5],"ㅁ":[9.5,57]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED