INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_b#7','math',4,2,'u4','','g4_2_math_u4_review_b','unit_review','M4-2-u4-C8',1,'sa','auto','모양 조각으로 꽃 모양을 만들었어요. 정삼각형 조각은 몇 개 썼나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u4-C8","difficulty":1,"kind":"sa","stem":"모양 조각으로 꽃 모양을 만들었어요. 정삼각형 조각은 몇 개 썼나요? 숫자로 쓰세요.","answer":["6"],"explanation":["정삼각형 조각의 모양을 떠올려요.","그림에서 그 모양인 조각을 하나씩 표시하며 세요.","정삼각형 조각은 6개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.5,-0.866],[1.0,-1.7321],[0.0,-1.7321],[-0.5,-0.866]]},{"p":[[1.0,0.0],[0.0,0.0],[0.5,0.866]]},{"p":[[1.5,-0.866],[1.0,-0.0],[2.0,0.0]]},{"p":[[1.0,-1.7321],[1.5,-0.866],[2.0,-1.7321]]},{"p":[[0.0,-1.7321],[1.0,-1.7321],[0.5,-2.5981]]},{"p":[[-0.5,-0.866],[0.0,-1.7321],[-1.0,-1.7321]]},{"p":[[0.0,0.0],[-0.5,-0.866],[-1.0,0.0]]}],"u":34},"variant_rule":{"alt":[{"stem":"모양 조각으로 로켓 모양을 만들었어요. 정삼각형 조각은 몇 개 썼나요? 숫자로 쓰세요.","answer":["3"],"explanation":["정삼각형 조각의 모양을 떠올려요.","그림에서 그 모양인 조각을 하나씩 표시하며 세요.","정삼각형 조각은 3개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.0,-1.0],[0.0,-1.0]]},{"p":[[0.0,-1.0],[1.0,-1.0],[1.0,-2.0],[0.0,-2.0]]},{"p":[[0.0,-2.0],[1.0,-2.0],[0.5,-2.866]]},{"p":[[1.0,-1.0],[1.0,0.0],[1.866,-0.5]]},{"p":[[0.0,0.0],[0.0,-1.0],[-0.866,-0.5]]}],"u":34}},{"stem":"모양 조각으로 로켓 모양을 만들었어요. 정사각형 조각은 몇 개 썼나요? 숫자로 쓰세요.","answer":["2"],"explanation":["정사각형 조각의 모양을 떠올려요.","그림에서 그 모양인 조각을 하나씩 표시하며 세요.","정사각형 조각은 2개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.0,-1.0],[0.0,-1.0]]},{"p":[[0.0,-1.0],[1.0,-1.0],[1.0,-2.0],[0.0,-2.0]]},{"p":[[0.0,-2.0],[1.0,-2.0],[0.5,-2.866]]},{"p":[[1.0,-1.0],[1.0,0.0],[1.866,-0.5]]},{"p":[[0.0,0.0],[0.0,-1.0],[-0.866,-0.5]]}],"u":34}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLU