INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_b#11','math',4,2,'u4','','g4_2_math_u4_review_b','unit_review','M4-2-u4-C4',2,'mc','auto','네 각의 크기가 모두 같지만 네 변의 길이는 같지 않은 사각형이 있어요. 이 도형은 정사각형인가요?',ARRAY['M4-2-u4-X08','M4-2-u4-X04','M4-2-u4-X10']::text[],true,'{"seq":11,"concept":"M4-2-u4-C4","difficulty":2,"kind":"mc","stem":"네 각의 크기가 모두 같지만 네 변의 길이는 같지 않은 사각형이 있어요. 이 도형은 정사각형인가요?","options":[{"t":"변의 길이도 모두 같아야 하므로 정사각형이 아니에요","correct":true},{"t":"각이 모두 같으니 정사각형이에요","mis":"M4-2-u4-X08"},{"t":"변이 4개라서 정사각형이에요","mis":"M4-2-u4-X04"},{"t":"크기가 작아서 정사각형이 아니에요","mis":"M4-2-u4-X10"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같아야 해요.","이 도형은 변의 길이이(가) 모두 같지 않아요.","그래서 정사각형이 아니에요."],"asset":{"type":"geo","items":[{"w":126.0,"h":80.0,"poly":[[[10.0,56.0],[102.0,56.0],[102.0,10.0],[10.0,10.0]]],"lab":[[[56.0,76.0],"6 cm"],[[122.0,33.0],"3 cm"]],"right":[[[10.0,10.0],[10.0,56.0],[102.0,56.0]],[[10.0,56.0],[102.0,56.0],[102.0,10.0]],[[102.0,56.0],[102.0,10.0],[10.0,10.0]],[[102.0,10.0],[10.0,10.0],[10.0,56.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"여섯 변의 길이가 모두 같지만 각의 크기는 같지 않은 육각형이 있어요. 이 도형은 정육각형인가요?","options":[{"t":"각의 크기도 모두 같아야 하므로 정육각형이 아니에요","correct":true},{"t":"변이 모두 같으니 정육각형이에요","mis":"M4-2-u4-X07"},{"t":"변이 6개라서 정육각형이에요","mis":"M4-2-u4-X04"},{"t":"크기가 작아서 정육각형이 아니에요","mis":"M4-2-u4-X10"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같아야 해요.","이 도형은 각의 크기이(가) 모두 같지 않아요.","그래서 정육각형이 아니에요."],"asset":{"type":"geo","items":[{"w":224.3,"h":160.7,"poly":[[[52.0,136.740293133],[136.000000001,136.740293133],[200.347733224,82.746133918],[158.347733224,10.0],[74.347733223,10.0],[10.0,63.994159213]]],"tick":[[[52.0,136.740293133],[136.000000001,136.740293133],1],[[136.000000001,136.740293133],[200.347733224,82.746133918],1],[[200.347733224,82.746133918],[158.347733224,10.0],1],[[158.347733224,10.0],[74.347733223,10