INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_b#12','math',4,2,'u4','','g4_2_math_u4_review_b','unit_review','M4-2-u4-C7',2,'sa','auto','오각형에 대각선을 모두 그었어요. 대각선은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M4-2-u4-C7","difficulty":2,"kind":"sa","stem":"오각형에 대각선을 모두 그었어요. 대각선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 꼭짓점을 잡고 이웃하지 않는 꼭짓점을 차례로 이어요.","이미 그은 대각선은 다시 세지 않아요.","오각형의 대각선은 5개예요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[19,9.5],"ㄴ":[95,19],"ㄷ":[104.5,66.5],"ㄹ":[57,85.5],"ㅁ":[9.5,57]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"dash":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄴ","ㄹ"],["ㄴ","ㅁ"],["ㄷ","ㅁ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"육각형에 대각선을 모두 그었어요. 대각선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 꼭짓점을 잡고 이웃하지 않는 꼭짓점을 차례로 이어요.","이미 그은 대각선은 다시 세지 않아요.","육각형의 대각선은 9개예요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[28.5,9.5],"ㄴ":[85.5,9.5],"ㄷ":[104.5,47.5],"ㄹ":[85.5,85.5],"ㅁ":[28.5,85.5],"ㅂ":[9.5,47.5]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]],"dash":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"],["ㄴ","ㄹ"],["ㄴ","ㅁ"],["ㄴ","ㅂ"],["ㄷ","ㅁ"],["ㄷ","ㅂ"],["ㄹ","ㅂ"]]}],"tag":false}},{"stem":"오각형에 그을 수 있는 대각선은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 꼭짓점을 잡고 이웃하지 않는 꼭짓점을 차례로 이어요.","이미 그은 대각선은 다시 세지 않아요.","오각형의 대각선은 5개예요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[19,9.5],"ㄴ":[95,19],"ㄷ":[104.5,66.5],"ㄹ":[57,85.5],"ㅁ":[9.5,57]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_b#13','math',4,2,'u4','','g4_2_math_u4_review_b','unit_review','M4-2-u4-C8',2,'mc','auto','아래와 같이 조각을 이어 붙였어요. 만든 도형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X04','M4-2-u4-X17']::text[],true,'{"seq":13,"concept":"M4-2-u4-C8","difficulty":2,"kind":"mc","stem":"아래와 같이 조각을 이어 붙였어요. 만든 도형의 이름은 무엇인가요?","options":[{"t":"오각형","correct":true},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"칠각형","mis":"M4-2-u4-X17"},{"t":"사각형","mis":"M4-2-u4-X04"}],"explanation":["만든 도형의 바깥쪽 변만 세요 — 조각끼리 맞댄 안쪽 선은 변이 아니에요.","한 줄로 곧게 이어진 선은 변 하나예요. 바깥쪽 변은 5개예요.","그래서 오각형이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.0,-1.0],[0.0,-1.0]]},{"p":[[0.0,-1.0],[1.0,-1.0],[0.5,-1.866]]}],"u":34},"variant_rule":{"alt":[{"stem":"조각 2개를 이어 붙여 만든 도형의 이름은 무엇인가요?","options":[{"t":"오각형","correct":true},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"구각형","mis":"M4-2-u4-X17"},{"t":"사각형","mis":"M4-2-u4-X04"}],"explanation":["만든 도형의 바깥쪽 변만 세요 — 조각끼리 맞댄 안쪽 선은 변이 아니에요.","한 줄로 곧게 이어진 선은 변 하나예요. 바깥쪽 변은 5개예요.","그래서 오각형이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.5,-0.866],[1.0,-1.7321],[0.0,-1.7321],[-0.5,-0.866]]},{"p":[[1.0,0.0],[0.0,0.0],[0.5,0.866]]}],"u":34}},{"stem":"이번에는 다른 그림이에요. 아래와 같이 조각을 이어 붙였어요. 만든 도형의 이름은 무엇인가요?","options":[{"t":"육각형","correct":true},{"t":"삼각형","mis":"M4-2-u4-X17"},{"t":"십일각형","mis":"M4-2-u4-X17"},{"t":"칠각형","mis":"M4-2-u4-X04"}],"explanation":["만든 도형의 바깥쪽 변만 세요 — 조각끼리 맞댄 안쪽 선은 변이 아니에요.","한 줄로 곧게 이어진 선은 변 하나예요. 바깥쪽 변은 6개예요.","그래서 육각형이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.0,-1.0],[0.0,-1.0]]},{"p":[[1.0,0.0],[2.0,0.0],[2.0,-1.0],[1.0,-1.0]]},{"p":[[0.0,-1.0],[1.0,-1.0],[0.5,-1.866]]}],"u":34}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_b#14','math',4,2,'u4','','g4_2_math_u4_review_b','unit_review','M4-2-u4-C9',2,'sa','auto','아래 정육각형 모양은 정삼각형 조각 6개로 채울 수 있어요. 같은 모양을 사다리꼴 조각으로만 빈틈없이 채우면 조각이 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M4-2-u4-C9","difficulty":2,"kind":"sa","stem":"아래 정육각형 모양은 정삼각형 조각 6개로 채울 수 있어요. 같은 모양을 사다리꼴 조각으로만 빈틈없이 채우면 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["2"],"explanation":["사다리꼴 1개 = 정삼각형 3개예요.","정삼각형 6개만큼을 3개씩 묶어요.","6 ÷ 3 = 2개예요."],"asset":{"type":"geo","items":[{"w":76.0,"h":68.0,"poly":[[[23.0,59.96],[53.0,59.96],[68.0,33.98],[53.0,8.0],[23.0,8.0],[8.0,33.98]]],"dash":[[[8.0,33.98],[38.0,33.98]],[[23.0,8.0],[38.0,33.98]],[[23.0,59.96],[38.0,33.98]],[[38.0,33.98],[53.0,8.0]],[[38.0,33.98],[53.0,59.96]],[[38.0,33.98],[68.0,33.98]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"아래 큰 마름모 모양은 정삼각형 조각 8개로 채울 수 있어요. 같은 모양을 마름모 조각으로만 빈틈없이 채우면 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["4"],"explanation":["마름모 1개 = 정삼각형 2개예요.","정삼각형 8개만큼을 2개씩 묶어요.","8 ÷ 2 = 4개예요."],"asset":{"type":"geo","items":[{"w":106.0,"h":68.0,"poly":[[[8.0,59.96],[68.0,59.96],[98.0,8.0],[38.0,8.0]]],"dash":[[[23.0,33.98],[38.0,59.96]],[[23.0,33.98],[53.0,33.98]],[[38.0,8.0],[53.0,33.98]],[[38.0,59.96],[53.0,33.98]],[[53.0,33.98],[68.0,8.0]],[[53.0,33.98],[68.0,59.96]],[[53.0,33.98],[83.0,33.98]],[[68.0,8.0],[83.0,33.98]]]}],"tag":false}},{"stem":"아래 큰 삼각형 모양은 정삼각형 조각 9개로 채울 수 있어요. 같은 모양을 사다리꼴 조각으로만 빈틈없이 채우면 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["3"],"explanation":["사다리꼴 1개 = 정삼각형 3개예요.","정삼각형 9개만큼을 3개씩 묶어요.","9 ÷ 3 = 3개예요."],"asset":{"type":"geo","items":[{"w":106.0,"h":93.9,"poly":[[[8.0,85.94],[98.0,85.94],[53.0,8.0]]],"dash":[[[23.0,59.96],[38.0,85.94]],[[23.0,59.96],[53.0,59.96]],[[38.0,33.98],[53.0,59.96]],[[38.0,33.98],[68.0,33.98]],[[38.0,85.94],[53.0,59.96]],[[53.0,59.96],[68.0,33.98]],[[53.0,59.96],[68.0,85.94]],[[53.0,59.96],[83.0,59.96]],[[68.0,85.94],[83.0,59.96]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
