INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_c#6','math',4,2,'u4','','g4_2_math_u4_review_c','unit_review','M4-2-u4-C6',1,'mc','auto','사각형 ㄱㄴㄷㄹ에서 대각선은 어느 것인가요?',ARRAY['M4-2-u4-X11']::text[],true,'{"seq":6,"concept":"M4-2-u4-C6","difficulty":1,"kind":"mc","stem":"사각형 ㄱㄴㄷㄹ에서 대각선은 어느 것인가요?","options":[{"t":"선분 ㄷㄱ","correct":true},{"t":"선분 ㄷㄹ","mis":"M4-2-u4-X11"},{"t":"선분 ㄹㄱ","mis":"M4-2-u4-X11"},{"t":"선분 ㄱㄴ","mis":"M4-2-u4-X11"}],"explanation":["꼭짓점 ㄷ과 이웃한 꼭짓점은 ㄹ, ㄴ이에요.","이웃하지 않는 꼭짓점 ㄱ과 이은 선분 ㄷㄱ이 대각선이에요.","이웃한 꼭짓점끼리 이은 선분은 변이에요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[19,19],"ㄴ":[95,9.5],"ㄷ":[104.5,85.5],"ㄹ":[9.5,76]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"오각형 ㄱㄴㄷㄹㅁ에서 대각선은 어느 것인가요?","options":[{"t":"선분 ㄹㄱ","correct":true},{"t":"선분 ㄹㅁ","mis":"M4-2-u4-X11"},{"t":"선분 ㅁㄱ","mis":"M4-2-u4-X11"},{"t":"선분 ㄱㄴ","mis":"M4-2-u4-X11"}],"explanation":["꼭짓점 ㄹ과 이웃한 꼭짓점은 ㅁ, ㄷ이에요.","이웃하지 않는 꼭짓점 ㄱ과 이은 선분 ㄹㄱ이 대각선이에요.","이웃한 꼭짓점끼리 이은 선분은 변이에요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[19,9.5],"ㄴ":[95,19],"ㄷ":[104.5,66.5],"ㄹ":[57,85.5],"ㅁ":[9.5,57]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]]}],"tag":false}},{"stem":"육각형 ㄱㄴㄷㄹㅁㅂ에서 대각선은 어느 것인가요?","options":[{"t":"선분 ㅁㄱ","correct":true},{"t":"선분 ㅁㅂ","mis":"M4-2-u4-X11"},{"t":"선분 ㅂㄱ","mis":"M4-2-u4-X11"},{"t":"선분 ㄱㄴ","mis":"M4-2-u4-X11"}],"explanation":["꼭짓점 ㅁ과 이웃한 꼭짓점은 ㅂ, ㄹ이에요.","이웃하지 않는 꼭짓점 ㄱ과 이은 선분 ㅁㄱ이 대각선이에요.","이웃한 꼭짓점끼리 이은 선분은 변이에요."],"asset":{"type":"geo","items":[{"w":128.5,"h":109.5,"pts":{"ㄱ":[28.5,9.5],"ㄴ":[85.5,9.5],"ㄷ":[104.5,47.5],"ㄹ":[85.5,85.5],"ㅁ":[28.5,85.5],"ㅂ":[9.5,47.5]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXC