INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_c#13','math',4,2,'u4','','g4_2_math_u4_review_c','unit_review','M4-2-u4-C8',2,'mc','auto','조각 2개를 이어 붙여 만든 도형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X04','M4-2-u4-X17']::text[],true,'{"seq":13,"concept":"M4-2-u4-C8","difficulty":2,"kind":"mc","stem":"조각 2개를 이어 붙여 만든 도형의 이름은 무엇인가요?","options":[{"t":"오각형","correct":true},{"t":"육각형","mis":"M4-2-u4-X04"},{"t":"구각형","mis":"M4-2-u4-X17"},{"t":"사각형","mis":"M4-2-u4-X04"}],"explanation":["만든 도형의 바깥쪽 변만 세요 — 조각끼리 맞댄 안쪽 선은 변이 아니에요.","한 줄로 곧게 이어진 선은 변 하나예요. 바깥쪽 변은 5개예요.","그래서 오각형이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.5,-0.866],[1.0,-1.7321],[0.0,-1.7321],[-0.5,-0.866]]},{"p":[[1.0,0.0],[0.0,0.0],[0.5,0.866]]}],"u":34},"variant_rule":{"alt":[{"stem":"아래와 같이 조각을 이어 붙였어요. 만든 도형의 이름은 무엇인가요?","options":[{"t":"육각형","correct":true},{"t":"삼각형","mis":"M4-2-u4-X17"},{"t":"십일각형","mis":"M4-2-u4-X17"},{"t":"칠각형","mis":"M4-2-u4-X04"}],"explanation":["만든 도형의 바깥쪽 변만 세요 — 조각끼리 맞댄 안쪽 선은 변이 아니에요.","한 줄로 곧게 이어진 선은 변 하나예요. 바깥쪽 변은 6개예요.","그래서 육각형이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[1.0,-1.0],[0.0,-1.0]]},{"p":[[1.0,0.0],[2.0,0.0],[2.0,-1.0],[1.0,-1.0]]},{"p":[[0.0,-1.0],[1.0,-1.0],[0.5,-1.866]]}],"u":34}},{"stem":"조각 3개를 이어 붙여 만든 도형의 이름은 무엇인가요?","options":[{"t":"사각형","correct":true},{"t":"삼각형","mis":"M4-2-u4-X17"},{"t":"구각형","mis":"M4-2-u4-X17"},{"t":"오각형","mis":"M4-2-u4-X04"}],"explanation":["만든 도형의 바깥쪽 변만 세요 — 조각끼리 맞댄 안쪽 선은 변이 아니에요.","한 줄로 곧게 이어진 선은 변 하나예요. 바깥쪽 변은 4개예요.","그래서 사각형이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,0.0],[1.0,0.0],[0.5,-0.866]]},{"p":[[1.5,-0.866],[0.5,-0.866],[1.0,0.0]]},{"p":[[1.0,0.0],[2.0,0.0],[1.5,-0.866]]}],"u":34}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, g