INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_c#17','math',4,2,'u4','','g4_2_math_u4_review_c','unit_review','M4-2-u4-C2',3,'sa','auto','두 다각형 ㉮와 ㉯의 변은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M4-2-u4-C2","difficulty":3,"kind":"sa","stem":"두 다각형 ㉮와 ㉯의 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["㉮의 변을 세면 7개예요.","㉯의 변을 세면 5개예요.","모두 7 + 5 = 12개예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,8.0],[88.0,8.0],[88.0,72.0],[64.0,72.0],[64.0,40.0],[32.0,40.0],[8.0,72.0]]]},{"w":96,"h":80,"poly":[[[8.0,8.0],[88.0,8.0],[88.0,72.0],[48.0,40.0],[8.0,72.0]]]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 두 다각형 ㉮와 ㉯의 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["㉮의 변을 세면 8개예요.","㉯의 변을 세면 6개예요.","모두 8 + 6 = 14개예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[32.0,8.0],[64.0,8.0],[88.0,32.0],[88.0,48.0],[64.0,72.0],[32.0,72.0],[8.0,48.0],[8.0,32.0]]]},{"w":96,"h":80,"poly":[[[8.0,72.0],[8.0,8.0],[32.0,32.0],[56.0,8.0],[88.0,40.0],[88.0,72.0]]]}]}},{"stem":"이번에는 다른 그림이에요. 두 다각형 ㉮와 ㉯의 변은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["㉮의 변을 세면 6개예요.","㉯의 변을 세면 5개예요.","모두 6 + 5 = 11개예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,8.0],[40.0,8.0],[40.0,40.0],[88.0,40.0],[88.0,72.0],[8.0,72.0]]]},{"w":96,"h":80,"poly":[[[8.0,40.0],[40.0,8.0],[88.0,8.0],[88.0,72.0],[40.0,72.0]]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_c#18','math',4,2,'u4','','g4_2_math_u4_review_c','unit_review','M4-2-u4-C5',3,'mc','auto','모든 변의 길이의 합이 54 cm이고 한 변의 길이가 9 cm인 정다각형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X09','M4-2-u4-X07']::text[],true,'{"seq":18,"concept":"M4-2-u4-C5","difficulty":3,"kind":"mc","stem":"모든 변의 길이의 합이 54 cm이고 한 변의 길이가 9 cm인 정다각형의 이름은 무엇인가요?","options":[{"t":"정육각형","correct":true},{"t":"정오각형","mis":"M4-2-u4-X09"},{"t":"정칠각형","mis":"M4-2-u4-X09"},{"t":"육각형","mis":"M4-2-u4-X07"}],"explanation":["변의 수 = 합 ÷ 한 변이에요.","54 ÷ 9 = 6 — 변이 6개예요.","정다각형이니 정육각형이에요."],"variant_rule":{"alt":[{"stem":"모든 변의 길이의 합이 28 cm이고 한 변의 길이가 4 cm인 정다각형의 이름은 무엇인가요?","options":[{"t":"정칠각형","correct":true},{"t":"정육각형","mis":"M4-2-u4-X09"},{"t":"정팔각형","mis":"M4-2-u4-X09"},{"t":"칠각형","mis":"M4-2-u4-X07"}],"explanation":["변의 수 = 합 ÷ 한 변이에요.","28 ÷ 4 = 7 — 변이 7개예요.","정다각형이니 정칠각형이에요."],"asset":null},{"stem":"모든 변의 길이의 합이 60 cm이고 한 변의 길이가 6 cm인 정다각형의 이름은 무엇인가요?","options":[{"t":"정십각형","correct":true},{"t":"정구각형","mis":"M4-2-u4-X09"},{"t":"정십일각형","mis":"M4-2-u4-X09"},{"t":"십각형","mis":"M4-2-u4-X07"}],"explanation":["변의 수 = 합 ÷ 한 변이에요.","60 ÷ 6 = 10 — 변이 10개예요.","정다각형이니 정십각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_c#19','math',4,2,'u4','','g4_2_math_u4_review_c','unit_review','M4-2-u4-C7',3,'sa','auto','사각형의 대각선의 수와 칠각형의 대각선의 수를 더하면 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M4-2-u4-C7","difficulty":3,"kind":"sa","stem":"사각형의 대각선의 수와 칠각형의 대각선의 수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["대각선은 한 꼭짓점에서 (변의 수 − 3)개씩 그어 모두 모은 뒤 겹친 것을 빼요.","사각형 2개, 칠각형 14개예요.","2 + 14 = 16개예요."],"variant_rule":{"alt":[{"stem":"육각형의 변의 수와 육각형에 그을 수 있는 대각선의 수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["대각선은 한 꼭짓점에서 (변의 수 − 3)개씩 그어 모두 모은 뒤 겹친 것을 빼요.","변 6개, 대각선 9개예요.","6 + 9 = 15개예요."],"asset":null},{"stem":"오각형의 대각선의 수와 팔각형의 대각선의 수를 더하면 몇 개인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["대각선은 한 꼭짓점에서 (변의 수 − 3)개씩 그어 모두 모은 뒤 겹친 것을 빼요.","오각형 5개, 팔각형 20개예요.","5 + 20 = 25개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_c#20','math',4,2,'u4','','g4_2_math_u4_review_c','unit_review','M4-2-u4-C9',3,'sa','auto','삼각형 모양을 여러 가지 조각으로 빈틈없이 채웠어요. 같은 모양을 정삼각형 조각으로만 다시 채우면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M4-2-u4-C9","difficulty":3,"kind":"sa","stem":"삼각형 모양을 여러 가지 조각으로 빈틈없이 채웠어요. 같은 모양을 정삼각형 조각으로만 다시 채우면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["4"],"explanation":["조각마다 정삼각형 몇 개와 같은지 바꿔요.","정삼각형 1개(정삼각형 1개), 사다리꼴 1개(정삼각형 3개)예요.","모두 정삼각형 4개예요."],"asset":{"type":"tiles","pieces":[{"p":[[0.0,-0.0],[2.0,-0.0],[1.5,-0.866],[0.5,-0.866]]},{"p":[[1.5,-0.866],[1.0,-1.7321],[0.5,-0.866]]}],"u":34},"variant_rule":{"alt":[{"stem":"정육각형 모양을 사다리꼴 조각으로 빈틈없이 채웠어요. 같은 모양을 정삼각형 조각으로만 다시 채우면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["6"],"explanation":["조각마다 정삼각형 몇 개와 같은지 바꿔요.","사다리꼴 2개(정삼각형 6개)예요.","모두 정삼각형 6개예요."],"asset":{"type":"tiles","pieces":[{"p":[[2.5,-0.866],[0.5,-0.866],[1.0,0.0],[2.0,0.0]]},{"p":[[0.5,-0.866],[2.5,-0.866],[2.0,-1.7321],[1.0,-1.7321]]}],"u":34}},{"stem":"평행사변형 모양을 마름모 조각으로 빈틈없이 채웠어요. 같은 모양을 정삼각형 조각으로만 다시 채우면 정삼각형 조각이 몇 개 필요한가요? 숫자로 쓰세요.","answer":["6"],"explanation":["조각마다 정삼각형 몇 개와 같은지 바꿔요.","마름모 3개(정삼각형 6개)예요.","모두 정삼각형 6개예요."],"asset":{"type":"tiles","pieces":[{"p":[[1.0,-0.0],[1.5,-0.866],[0.5,-0.866],[0.0,0.0]]},{"p":[[2.0,-0.0],[2.5,-0.866],[1.5,-0.866],[1.0,0.0]]},{"p":[[3.0,-0.0],[3.5,-0.866],[2.5,-0.866],[2.0,0.0]]}],"u":34}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
