INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_c#22','math',4,2,'u4','','g4_2_math_u4_review_c','unit_review','M4-2-u4-C4',3,'error','auto','정다각형에 대해 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u4-X09','M4-2-u4-X20']::text[],true,'{"seq":22,"concept":"M4-2-u4-C4","difficulty":3,"kind":"error","stem":"정다각형에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「한 변이 5 cm인 정육각형의 둘레는 5 × 5 = 25 cm야.」","correct":true,"mis_target":"M4-2-u4-X09"},{"t":"도윤 — 「작은 정삼각형도 정다각형이야.」","mis":"M4-2-u4-X20"},{"t":"서윤 — 「정다각형의 둘레는 한 변 × 변의 수야.」","mis":"M4-2-u4-X20"},{"t":"시우 — 「정다각형은 변과 각이 모두 같아야 해.」","mis":"M4-2-u4-X20"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같은 다각형이에요.","민서의 말은 그 뜻(또는 계산)과 맞지 않아요.","둘레는 한 변 × 변의 수(정육각형은 6)로 구해요."],"variant_rule":{"alt":[{"stem":"정다각형에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「마름모는 네 변이 모두 같으니까 정사각형이야.」","correct":true,"mis_target":"M4-2-u4-X07"},{"t":"서윤 — 「정다각형의 둘레는 한 변 × 변의 수야.」","mis":"M4-2-u4-X20"},{"t":"시우 — 「정다각형은 변과 각이 모두 같아야 해.」","mis":"M4-2-u4-X20"},{"t":"은우 — 「정팔각형은 변이 8개야.」","mis":"M4-2-u4-X20"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같은 다각형이에요.","도윤의 말은 그 뜻(또는 계산)과 맞지 않아요.","둘레는 한 변 × 변의 수(정육각형은 6)로 구해요."],"asset":null},{"stem":"정다각형에 대해 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「직사각형은 네 각이 모두 같으니까 정다각형이야.」","correct":true,"mis_target":"M4-2-u4-X08"},{"t":"시우 — 「정다각형은 변과 각이 모두 같아야 해.」","mis":"M4-2-u4-X20"},{"t":"은우 — 「정팔각형은 변이 8개야.」","mis":"M4-2-u4-X20"},{"t":"하랑 — 「작은 정삼각형도 정다각형이야.」","mis":"M4-2-u4-X20"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같은 다각형이에요.","서윤의 말은 그 뜻(또는 계산)과 맞지 않아요.","둘레는 한 변 × 변의 수(정육각형은 6)로 구해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_c#23','math',4,2,'u4','','g4_2_math_u4_review_c','unit_review','M4-2-u4-C5',4,'sa','auto','정팔각형의 한 꼭짓점에서 대각선을 그어 삼각형 6개로 나누었어요. 정팔각형의 한 각의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-2-u4-C5","difficulty":4,"kind":"sa","stem":"정팔각형의 한 꼭짓점에서 대각선을 그어 삼각형 6개로 나누었어요. 정팔각형의 한 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["135"],"explanation":["모든 각의 합 = 180° × 6 = 1080°예요.","정팔각형은 각 8개의 크기가 모두 같아요.","1080° ÷ 8 = 135°예요."],"asset":{"type":"geo","items":[{"w":128.2,"h":128.2,"pts":{"ㄱ":[77.134171618,104.193976626],"ㄴ":[38.865828382,104.193976626],"ㄷ":[11.806023374,77.134171618],"ㄹ":[11.806023374,38.865828382],"ㅁ":[38.865828382,11.806023374],"ㅂ":[77.134171618,11.806023374],"ㅅ":[104.193976626,38.865828382],"ㅇ":[104.193976626,77.134171618]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅇ"]],"dash":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"],["ㄱ","ㅂ"],["ㄱ","ㅅ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"정오각형의 한 꼭짓점에서 대각선을 그어 삼각형 3개로 나누었어요. 정오각형의 모든 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["540"],"explanation":["삼각형 하나의 세 각의 합은 180°예요.","삼각형 3개의 각을 모두 모으면 정오각형의 모든 각이 돼요.","180° × 3 = 540°예요."],"asset":{"type":"geo","items":[{"w":129.6,"h":122.5,"pts":{"ㄱ":[87.389262615,98.450849719],"ㄴ":[28.610737385,98.450849719],"ㄷ":[10.447174185,42.549150281],"ㄹ":[58.0,8.0],"ㅁ":[105.552825815,42.549150281]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"dash":[["ㄱ","ㄷ"],["ㄱ","ㄹ"]]}],"tag":false}},{"stem":"정팔각형의 한 꼭짓점에서 대각선을 그어 삼각형 6개로 나누었어요. 정팔각형의 모든 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["1080"],"explanation":["삼각형 하나의 세 각의 합은 180°예요.","삼각형 6개의 각을 모두 모으면 정팔각형의 모든 각이 돼요.","180° × 6 = 1080°예요."],"asset":{"type":"geo","items":[{"w":128.2,"h":128.2,"pts":{"ㄱ":[77.134171618,104.193976626],"ㄴ":[38.865828382,104.193976626],"ㄷ":[11.806023374,77.134171618],"ㄹ":[11.806023374,38.865828382],"ㅁ":[38.865828382,11.806023374],"ㅂ":[77.134171618,11.806023374],"ㅅ":[104.193976626,38.865828382],"ㅇ":[104.193976626,77.134171618]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅇ"]],"dash":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"],["ㄱ","ㅂ"],["ㄱ","ㅅ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_c#24','math',4,2,'u4','','g4_2_math_u4_review_c','unit_review','M4-2-u4-C7',4,'sa','auto','친구 7명이 둥글게 앉았어요. 바로 옆에 앉은 친구를 빼고 다른 친구와만 한 번씩 악수를 하면 악수는 모두 몇 번인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-2-u4-C7","difficulty":4,"kind":"sa","stem":"친구 7명이 둥글게 앉았어요. 바로 옆에 앉은 친구를 빼고 다른 친구와만 한 번씩 악수를 하면 악수는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["친구(나무)를 칠각형의 꼭짓점, 옆끼리를 변이라고 생각해요.","옆이 아닌 둘을 잇는 것은 대각선과 같아요.","칠각형의 대각선: 7 × 4 ÷ 2 = 14 — 14예요."],"variant_rule":{"alt":[{"stem":"공원에 나무 8그루가 둥글게 심어져 있어요. 바로 옆 나무끼리는 빼고, 나머지 나무끼리 두 그루씩 줄로 한 번씩 이으면 줄은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["친구(나무)를 팔각형의 꼭짓점, 옆끼리를 변이라고 생각해요.","옆이 아닌 둘을 잇는 것은 대각선과 같아요.","팔각형의 대각선: 8 × 5 ÷ 2 = 20 — 20이에요."],"asset":null},{"stem":"친구 6명이 둥글게 앉았어요. 바로 옆에 앉은 친구를 빼고 다른 친구와만 한 번씩 악수를 하면 악수는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["친구(나무)를 육각형의 꼭짓점, 옆끼리를 변이라고 생각해요.","옆이 아닌 둘을 잇는 것은 대각선과 같아요.","육각형의 대각선: 6 × 3 ÷ 2 = 9 — 9예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_c#25','math',4,2,'u4','','g4_2_math_u4_review_c','unit_review','M4-2-u4-C7',4,'essay','teacher','오각형에 그을 수 있는 대각선의 수를 구하는 방법을 쓰고, 삼각형에는 대각선을 그을 수 없는 까닭도 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u4-C7","difficulty":4,"kind":"essay","stem":"오각형에 그을 수 있는 대각선의 수를 구하는 방법을 쓰고, 삼각형에는 대각선을 그을 수 없는 까닭도 써 보세요.","answer_guide":{"answer":"예: 오각형의 한 꼭짓점에서는 이웃하지 않는 꼭짓점 2개와 이을 수 있어 대각선이 2개이다. 꼭짓점 5개에서 모두 그으면 2 × 5 = 10인데, 대각선마다 두 번 세었으므로 10 ÷ 2 = 5개이다. 삼각형은 어느 꼭짓점을 잡아도 나머지 두 꼭짓점이 모두 이웃하므로 대각선을 그을 수 없다.","scoring_points":["한 꼭짓점에서 2개라고 썼는가","두 번 센 것을 나누어 5개를 구했는가","삼각형은 모든 꼭짓점이 이웃해 대각선이 없다고 썼는가"]},"explanation":["한 꼭짓점에서 5 − 3 = 2개.","2 × 5 ÷ 2 = 5개.","삼각형은 이웃하지 않는 꼭짓점이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_d#1','math',4,2,'u4','','g4_2_math_u4_review_d','unit_review','M4-2-u4-C1',1,'mc','auto','다각형인 것은 어느 것인가요?',ARRAY['M4-2-u4-X01']::text[],true,'{"seq":1,"concept":"M4-2-u4-C1","difficulty":1,"kind":"mc","stem":"다각형인 것은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M4-2-u4-X01"},{"t":"㉯","mis":"M4-2-u4-X01"},{"t":"㉱","mis":"M4-2-u4-X01"}],"explanation":["다각형은 선분으로만 둘러싸인 도형이에요.","㉰만 곡선 없이 선분으로 빈틈없이 둘러싸여 있어요.","곡선이 섞였거나 끝이 열린 도형은 다각형이 아니에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[25.6,72.0],[8.0,72.0]],[[8.0,72.0],[8.0,32.0]],[[8.0,32.0],[48.0,8.0]],[[48.0,8.0],[88.0,32.0]],[[88.0,32.0],[88.0,72.0]],[[88.0,72.0],[54.4,72.0]]]},{"w":96,"h":80,"seg":[[[8.0,8.0],[88.0,8.0]],[[88.0,8.0],[88.0,72.0]],[[8.0,72.0],[8.0,8.0]]],"curve":[[[88.0,72.0],[8.0,72.0],[48.0,41.6]]]},{"w":96,"h":80,"poly":[[[8.0,8.0],[88.0,8.0],[88.0,32.0],[64.0,32.0],[64.0,72.0],[32.0,72.0],[32.0,32.0],[8.0,32.0]]]},{"w":96,"h":80,"seg":[[[8.0,60.8],[88.0,60.8]]],"curve":[[[8.0,60.8],[88.0,60.8],[48.0,-12.8]]]}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 다각형인 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-2-u4-X01"},{"t":"㉰","mis":"M4-2-u4-X01"},{"t":"㉱","mis":"M4-2-u4-X01"}],"explanation":["다각형은 선분으로만 둘러싸인 도형이에요.","㉯만 곡선 없이 선분으로 빈틈없이 둘러싸여 있어요.","곡선이 섞였거나 끝이 열린 도형은 다각형이 아니에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"circle":[[[48.0,40.0],33.6]]},{"w":96,"h":80,"poly":[[[8.0,72.0],[8.0,24.0],[32.0,8.0],[64.0,8.0],[88.0,24.0],[88.0,72.0],[48.0,48.0]]]},{"w":96,"h":80,"seg":[[[8.0,72.0],[8.0,40.0]],[[88.0,40.0],[88.0,72.0]],[[8.0,72.0],[88.0,72.0]]],"curve":[[[8.0,40.0],[88.0,40.0],[48.0,-19.2]]]},{"w":96,"h":80,"seg":[[[24.0,8.0],[72.0,8.0]],[[72.0,8.0],[88.0,40.0]],[[88.0,40.0],[72.0,72.0]],[[72.0,72.0],[24.0,72.0]],[[24.0,72.0],[8.0,40.0]]]}]}},{"stem":"이번에는 다른 그림이에요. 다각형인 것은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"M4-2-u4-X01"},{"t":"㉯","mis":"M4-2-u4-X01"},{"t":"㉰","mis":"M4-2-u4-X01"}],"explanation":["다각형은 선분으로만 둘러싸인 도형이에요.","㉱만 곡선 없이 선분으로 빈틈없이 둘러싸여 있어요.","곡선이 섞였거나 끝이 열린 도형은 다각형이 아니에요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"seg":[[[8.0,72.0],[48.0,8.0]],[[48.0,8.0],[88.0,72.0]],[[88.0,72.0],[22.4,72.0]]]},{"w":96,"h":80,"seg":[[[8.0,60.8],[88.0,60.8]]],"curve":[[[8.0,60.8],[88.0,60.8],[48.0,-12.8]]]},{"w":96,"h":80,"curve":[[[9.6,40.0],[86.4,40.0],[48.0,-6.4]],[[86.4,40.0],[9.6,40.0],[48.0,86.4]]]},{"w":96,"h":80,"poly":[[[8.0,8.0],[88.0,40.0],[8.0,72.0],[32.0,40.0]]]}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_d#2','math',4,2,'u4','','g4_2_math_u4_review_d','unit_review','M4-2-u4-C2',1,'sa','auto','세계 전통 가옥 체험장에서 찾은 도형이에요. 이 도형의 변은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u4-C2","difficulty":1,"kind":"sa","stem":"세계 전통 가옥 체험장에서 찾은 도형이에요. 이 도형의 변은 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 꼭짓점에서 시작해 한 방향으로 돌며 변에 표시를 해요.","빠뜨리거나 두 번 세지 않게 끝까지 세요.","변은 8개예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,8.0],[32.0,8.0],[32.0,32.0],[64.0,32.0],[64.0,8.0],[88.0,8.0],[88.0,72.0],[8.0,72.0]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"아래 도형은 변이 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 꼭짓점에서 시작해 한 방향으로 돌며 변에 표시를 해요.","빠뜨리거나 두 번 세지 않게 끝까지 세요.","변은 6개예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[24.0,8.0],[72.0,8.0],[88.0,40.0],[72.0,72.0],[24.0,72.0],[8.0,40.0]]]}],"tag":false}},{"stem":"이번에는 다른 그림이에요. 세계 전통 가옥 체험장에서 찾은 도형이에요. 이 도형의 변은 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 꼭짓점에서 시작해 한 방향으로 돌며 변에 표시를 해요.","빠뜨리거나 두 번 세지 않게 끝까지 세요.","변은 7개예요."],"asset":{"type":"geo","items":[{"w":96,"h":80,"poly":[[[8.0,72.0],[8.0,24.0],[32.0,8.0],[64.0,8.0],[88.0,24.0],[88.0,72.0],[48.0,48.0]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_d#3','math',4,2,'u4','','g4_2_math_u4_review_d','unit_review','M4-2-u4-C3',1,'mc','auto','변이 8개인 다각형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X04','M4-2-u4-X07']::text[],true,'{"seq":3,"concept":"M4-2-u4-C3","difficulty":1,"kind":"mc","stem":"변이 8개인 다각형의 이름은 무엇인가요?","options":[{"t":"팔각형","correct":true},{"t":"칠각형","mis":"M4-2-u4-X04"},{"t":"구각형","mis":"M4-2-u4-X04"},{"t":"정팔각형","mis":"M4-2-u4-X07"}],"explanation":["다각형은 변의 수에 따라 이름을 붙여요.","변의 수와 꼭짓점의 수는 같아요 — 모두 8개예요.","그래서 팔각형이에요."],"variant_rule":{"alt":[{"stem":"꼭짓점이 9개인 다각형의 이름은 무엇인가요?","options":[{"t":"구각형","correct":true},{"t":"팔각형","mis":"M4-2-u4-X04"},{"t":"십각형","mis":"M4-2-u4-X06"},{"t":"정구각형","mis":"M4-2-u4-X07"}],"explanation":["다각형은 변의 수에 따라 이름을 붙여요.","변의 수와 꼭짓점의 수는 같아요 — 모두 9개예요.","그래서 구각형이에요."],"asset":null},{"stem":"선분 6개로 둘러싸인 도형의 이름은 무엇인가요?","options":[{"t":"육각형","correct":true},{"t":"오각형","mis":"M4-2-u4-X04"},{"t":"칠각형","mis":"M4-2-u4-X04"},{"t":"정육각형","mis":"M4-2-u4-X07"}],"explanation":["다각형은 변의 수에 따라 이름을 붙여요.","변의 수와 꼭짓점의 수는 같아요 — 모두 6개예요.","그래서 육각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_d#4','math',4,2,'u4','','g4_2_math_u4_review_d','unit_review','M4-2-u4-C4',1,'mc','auto','변의 길이가 모두 같고 각의 크기가 모두 같으며 선분 9개로 둘러싸인 도형의 이름은 무엇인가요?',ARRAY['M4-2-u4-X07','M4-2-u4-X04']::text[],true,'{"seq":4,"concept":"M4-2-u4-C4","difficulty":1,"kind":"mc","stem":"변의 길이가 모두 같고 각의 크기가 모두 같으며 선분 9개로 둘러싸인 도형의 이름은 무엇인가요?","options":[{"t":"정구각형","correct":true},{"t":"구각형","mis":"M4-2-u4-X07"},{"t":"정팔각형","mis":"M4-2-u4-X04"},{"t":"정십각형","mis":"M4-2-u4-X04"}],"explanation":["변의 길이·각의 크기가 모두 같으니 정다각형이에요.","변(꼭짓점)이 9개이니 구각형이에요.","이름 앞에 「정」을 붙여 정구각형이에요."],"variant_rule":{"alt":[{"stem":"각의 크기가 모두 같고 변의 길이도 모두 같은 다각형의 꼭짓점이 5개예요. 이 도형의 이름은 무엇인가요?","options":[{"t":"정오각형","correct":true},{"t":"오각형","mis":"M4-2-u4-X07"},{"t":"정사각형","mis":"M4-2-u4-X04"},{"t":"정육각형","mis":"M4-2-u4-X04"}],"explanation":["변의 길이·각의 크기가 모두 같으니 정다각형이에요.","변(꼭짓점)이 5개이니 오각형이에요.","이름 앞에 「정」을 붙여 정오각형이에요."],"asset":null},{"stem":"변의 길이가 모두 같고 각의 크기가 모두 같으며 선분 8개로 둘러싸인 도형의 이름은 무엇인가요?","options":[{"t":"정팔각형","correct":true},{"t":"팔각형","mis":"M4-2-u4-X07"},{"t":"정칠각형","mis":"M4-2-u4-X04"},{"t":"정구각형","mis":"M4-2-u4-X04"}],"explanation":["변의 길이·각의 크기가 모두 같으니 정다각형이에요.","변(꼭짓점)이 8개이니 팔각형이에요.","이름 앞에 「정」을 붙여 정팔각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_d#5','math',4,2,'u4','','g4_2_math_u4_review_d','unit_review','M4-2-u4-C5',1,'sa','auto','한 변의 길이가 3 cm인 정칠각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u4-C5","difficulty":1,"kind":"sa","stem":"한 변의 길이가 3 cm인 정칠각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["정칠각형은 변이 7개이고 길이가 모두 같아요.","모든 변의 길이의 합 = 한 변 × 변의 수예요.","3 × 7 = 21 cm예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 6 cm인 정구각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["정구각형은 변이 9개이고 길이가 모두 같아요.","모든 변의 길이의 합 = 한 변 × 변의 수예요.","6 × 9 = 54 cm예요."],"asset":{"type":"geo","items":[{"w":123.3,"h":121.2,"poly":[[[69.732926593,97.225860556],[38.267073407,97.225860556],[14.162831426,77.0],[8.698843361,46.012183827],[24.431769954,18.761955617],[54.0,8.0],[83.568230046,18.761955617],[99.301156639,46.012183827],[93.837168574,77.0]]],"tick":[[[69.732926593,97.225860556],[38.267073407,97.225860556],1],[[38.267073407,97.225860556],[14.162831426,77.0],1],[[14.162831426,77.0],[8.698843361,46.012183827],1],[[8.698843361,46.012183827],[24.431769954,18.761955617],1],[[24.431769954,18.761955617],[54.0,8.0],1],[[54.0,8.0],[83.568230046,18.761955617],1],[[83.568230046,18.761955617],[99.301156639,46.012183827],1],[[99.301156639,46.012183827],[93.837168574,77.0],1],[[93.837168574,77.0],[69.732926593,97.225860556],1]],"lab":[[[54.0,117.2],"6 cm"]]}],"tag":false}},{"stem":"한 변의 길이가 9 cm인 정육각형의 모든 변의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["정육각형은 변이 6개이고 길이가 모두 같아요.","모든 변의 길이의 합 = 한 변 × 변의 수예요.","9 × 6 = 54 cm예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUD