INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_d#11','math',4,2,'u4','','g4_2_math_u4_review_d','unit_review','M4-2-u4-C4',2,'mc','auto','여섯 각의 크기가 모두 같지만 변의 길이는 같지 않은 육각형이 있어요. 이 도형은 정육각형인가요?',ARRAY['M4-2-u4-X08','M4-2-u4-X04','M4-2-u4-X10']::text[],true,'{"seq":11,"concept":"M4-2-u4-C4","difficulty":2,"kind":"mc","stem":"여섯 각의 크기가 모두 같지만 변의 길이는 같지 않은 육각형이 있어요. 이 도형은 정육각형인가요?","options":[{"t":"변의 길이도 모두 같아야 하므로 정육각형이 아니에요","correct":true},{"t":"각이 모두 같으니 정육각형이에요","mis":"M4-2-u4-X08"},{"t":"변이 6개라서 정육각형이에요","mis":"M4-2-u4-X04"},{"t":"크기가 작아서 정육각형이 아니에요","mis":"M4-2-u4-X10"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같아야 해요.","이 도형은 변의 길이이(가) 모두 같지 않아요.","그래서 정육각형이 아니에요."],"asset":{"type":"geo","items":[{"w":286.0,"h":252.2,"poly":[[[52.0,228.238401754],[220.0,228.238401754],[262.0,155.492267836],[178.0,10.0],[94.0,10.0],[10.0,155.492267836]]],"lab":[[[65.1,213.1],"120°"],[[206.9,213.1],"120°"],[[242.4,151.7],"120°"],[[171.5,28.9],"120°"],[[100.5,28.9],"120°"],[[29.6,151.7],"120°"],[[136.0,248.2],"6 cm"],[[258.3,201.9],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"두 변의 길이와 두 각의 크기만 같은 삼각형이 있어요. 이 도형은 정삼각형인가요?","options":[{"t":"각의 크기도 모두 같아야 하므로 정삼각형이 아니에요","correct":true},{"t":"변이 모두 같으니 정삼각형이에요","mis":"M4-2-u4-X07"},{"t":"변이 3개라서 정삼각형이에요","mis":"M4-2-u4-X04"},{"t":"크기가 작아서 정삼각형이 아니에요","mis":"M4-2-u4-X10"}],"explanation":["정다각형은 변의 길이와 각의 크기가 모두 같아야 해요.","이 도형은 각의 크기이(가) 모두 같지 않아요.","그래서 정삼각형이 아니에요."],"asset":{"type":"geo","items":[{"w":156.8,"h":112.9,"poly":[[[10.0,88.934180146],[132.799784807,88.934180146],[38.729692039,10.0]]],"tick":[[[10.0,88.934180146],[132.799784807,88.934180146],1],[[132.799784807,88.934180146],[38.729692039,10.0],1]],"lab":[[[24.2,81.5],"70°"],[[117.8,83.5],"40°"],[[44.8,24.8],"70°"]]}],"tag":false}},{"stem":"네 변의 길이가 모두 같지만 네 각의 크기는 같지 않은 사각형이 있어요. 이 도형은 정사각형인가요?","opt