INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_d#22','math',4,2,'u4','','g4_2_math_u4_review_d','unit_review','M4-2-u4-C4',3,'ox','auto','크기가 다른 두 정육각형은 하나만 정육각형이에요.',ARRAY['M4-2-u4-X10']::text[],true,'{"seq":22,"concept":"M4-2-u4-C4","difficulty":3,"kind":"ox","stem":"크기가 다른 두 정육각형은 하나만 정육각형이에요.","answer":"X","reason_options":[{"t":"둘 다 변의 길이와 각의 크기가 모두 같아서","correct":true},{"t":"정육각형은 크기가 정해져 있어서","mis":"M4-2-u4-X10"}],"mis":"M4-2-u4-X10","explanation":["정다각형은 변의 길이·각의 크기로만 정해요.","크기나 놓인 방향은 상관없어요.","변이 모두 같고 각이 모두 같으면 정다각형이에요."],"asset":{"type":"geo","items":[{"w":124.0,"h":117.8,"poly":[[[77.0,93.837168574],[31.0,93.837168574],[8.0,54.0],[31.0,14.162831426],[77.0,14.162831426],[100.0,54.0]]],"tick":[[[77.0,93.837168574],[31.0,93.837168574],1],[[31.0,93.837168574],[8.0,54.0],1],[[8.0,54.0],[31.0,14.162831426],1],[[31.0,14.162831426],[77.0,14.162831426],1],[[77.0,14.162831426],[100.0,54.0],1],[[100.0,54.0],[77.0,93.837168574],1]]},{"w":87.1,"h":87.0,"poly":[[[43.56554672,62.958533024],[16.435998912,56.031222165],[8.870452192,29.072689141],[28.43445328,9.041466976],[55.564001088,15.968777835],[63.129547808,42.927310859]]],"tick":[[[43.56554672,62.958533024],[16.435998912,56.031222165],1],[[16.435998912,56.031222165],[8.870452192,29.072689141],1],[[8.870452192,29.072689141],[28.43445328,9.041466976],1],[[28.43445328,9.041466976],[55.564001088,15.968777835],1],[[55.564001088,15.968777835],[63.129547808,42.927310859],1],[[63.129547808,42.927310859],[43.56554672,62.958533024],1]]}]},"variant_rule":{"alt":[{"stem":"정사각형을 비스듬히 돌려 놓아도 정사각형이에요.","answer":"O","reason_options":[{"t":"변의 길이와 각의 크기는 그대로라서","correct":true},{"t":"반듯하게 놓여야 정사각형이라서","mis":"M4-2-u4-X10"}],"explanation":["정다각형은 변의 길이·각의 크기로만 정해요.","크기나 놓인 방향은 상관없어요.","변이 모두 같고 각이 모두 같으면 정다각형이에요."],"asset":{"type":"geo","items":[{"w":117.5,"h":117.5,"poly":[[[66.482387631,93.548290561],[10.451709439,66.482387631],[37.517612369,10.451709439],[93.548290561,37.517612369]]],"tick":[[[66.482387631,93.548290561],[10.451709439,66.482387631],1],[[10.451709439,66.482387631],[37.517612369,10.451709439],1],[[37.517612369,10.451709439],[93.548290561,37.517612369],1],[[93.548290561,37.517612369],[66.482387631,93.548290561],1]]}],"tag":false}},{"stem":"정삼각형은 정다각형이에요.","answer":"O","reason_options":[{"t":"세 변의 길이와 세 각의 크기가 모두 같아서","correct":true},{"t":"변이 3개뿐이라 정다각형이 아니라서","mis":"M4-2-u4-X03"}],"explanation":["정다각형은 변의 길이·각의 크기로만 정해요.","크기나 놓인 방향은 상관없어요.","변이 모두 같고 각이 모두 같으면 정다각형이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_d#23','math',4,2,'u4','','g4_2_math_u4_review_d','unit_review','M4-2-u4-C5',4,'sa','auto','정오각형의 한 꼭짓점에서 대각선을 그어 삼각형 3개로 나누었어요. 정오각형의 모든 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-2-u4-C5","difficulty":4,"kind":"sa","stem":"정오각형의 한 꼭짓점에서 대각선을 그어 삼각형 3개로 나누었어요. 정오각형의 모든 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["540"],"explanation":["삼각형 하나의 세 각의 합은 180°예요.","삼각형 3개의 각을 모두 모으면 정오각형의 모든 각이 돼요.","180° × 3 = 540°예요."],"asset":{"type":"geo","items":[{"w":129.6,"h":122.5,"pts":{"ㄱ":[87.389262615,98.450849719],"ㄴ":[28.610737385,98.450849719],"ㄷ":[10.447174185,42.549150281],"ㄹ":[58.0,8.0],"ㅁ":[105.552825815,42.549150281]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"dash":[["ㄱ","ㄷ"],["ㄱ","ㄹ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"정팔각형의 한 꼭짓점에서 대각선을 그어 삼각형 6개로 나누었어요. 정팔각형의 모든 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["1080"],"explanation":["삼각형 하나의 세 각의 합은 180°예요.","삼각형 6개의 각을 모두 모으면 정팔각형의 모든 각이 돼요.","180° × 6 = 1080°예요."],"asset":{"type":"geo","items":[{"w":128.2,"h":128.2,"pts":{"ㄱ":[77.134171618,104.193976626],"ㄴ":[38.865828382,104.193976626],"ㄷ":[11.806023374,77.134171618],"ㄹ":[11.806023374,38.865828382],"ㅁ":[38.865828382,11.806023374],"ㅂ":[77.134171618,11.806023374],"ㅅ":[104.193976626,38.865828382],"ㅇ":[104.193976626,77.134171618]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ","ㅂ","ㅅ","ㅇ"]],"dash":[["ㄱ","ㄷ"],["ㄱ","ㄹ"],["ㄱ","ㅁ"],["ㄱ","ㅂ"],["ㄱ","ㅅ"]]}],"tag":false}},{"stem":"정오각형의 한 꼭짓점에서 대각선을 그어 삼각형 3개로 나누었어요. 정오각형의 한 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["108"],"explanation":["모든 각의 합 = 180° × 3 = 540°예요.","정오각형은 각 5개의 크기가 모두 같아요.","540° ÷ 5 = 108°예요."],"asset":{"type":"geo","items":[{"w":129.6,"h":122.5,"pts":{"ㄱ":[87.389262615,98.450849719],"ㄴ":[28.610737385,98.450849719],"ㄷ":[10.447174185,42.549150281],"ㄹ":[58.0,8.0],"ㅁ":[105.552825815,42.549150281]},"poly":[["ㄱ","ㄴ","ㄷ","ㄹ","ㅁ"]],"dash":[["ㄱ","ㄷ"],["ㄱ","ㄹ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_d#24','math',4,2,'u4','','g4_2_math_u4_review_d','unit_review','M4-2-u4-C7',4,'sa','auto','공원에 나무 8그루가 둥글게 심어져 있어요. 바로 옆 나무끼리는 빼고, 나머지 나무끼리 두 그루씩 줄로 한 번씩 이으면 줄은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-2-u4-C7","difficulty":4,"kind":"sa","stem":"공원에 나무 8그루가 둥글게 심어져 있어요. 바로 옆 나무끼리는 빼고, 나머지 나무끼리 두 그루씩 줄로 한 번씩 이으면 줄은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["친구(나무)를 팔각형의 꼭짓점, 옆끼리를 변이라고 생각해요.","옆이 아닌 둘을 잇는 것은 대각선과 같아요.","팔각형의 대각선: 8 × 5 ÷ 2 = 20 — 20이에요."],"variant_rule":{"alt":[{"stem":"친구 6명이 둥글게 앉았어요. 바로 옆에 앉은 친구를 빼고 다른 친구와만 한 번씩 악수를 하면 악수는 모두 몇 번인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["친구(나무)를 육각형의 꼭짓점, 옆끼리를 변이라고 생각해요.","옆이 아닌 둘을 잇는 것은 대각선과 같아요.","육각형의 대각선: 6 × 3 ÷ 2 = 9 — 9예요."],"asset":null},{"stem":"공원에 나무 9그루가 둥글게 심어져 있어요. 바로 옆 나무끼리는 빼고, 나머지 나무끼리 두 그루씩 줄로 한 번씩 이으면 줄은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["친구(나무)를 구각형의 꼭짓점, 옆끼리를 변이라고 생각해요.","옆이 아닌 둘을 잇는 것은 대각선과 같아요.","구각형의 대각선: 9 × 6 ÷ 2 = 27 — 27이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u4_review_d#25','math',4,2,'u4','','g4_2_math_u4_review_d','unit_review','M4-2-u4-C9',4,'essay','teacher','정육각형 모양을 정삼각형 조각으로 채우면 6개, 사다리꼴 조각으로 채우면 2개가 필요해요. 조각 수가 다른데도 모두 바르게 채운 것인 까닭과, 바르게 채웠는지 확인하는 방법을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u4-C9","difficulty":4,"kind":"essay","stem":"정육각형 모양을 정삼각형 조각으로 채우면 6개, 사다리꼴 조각으로 채우면 2개가 필요해요. 조각 수가 다른데도 모두 바르게 채운 것인 까닭과, 바르게 채웠는지 확인하는 방법을 써 보세요.","answer_guide":{"answer":"예: 사다리꼴 1개는 정삼각형 3개와 같은 모양이라 사다리꼴 2개는 정삼각형 6개만큼이다. 그래서 쓰는 조각이 달라도 같은 모양을 채울 수 있다. 바르게 채웠는지는 조각끼리 겹친 곳이 없는지, 조각 사이에 빈틈이 없는지 확인한다.","scoring_points":["사다리꼴 = 정삼각형 3개라고 썼는가","채우는 방법은 여러 가지라고 썼는가","겹침·빈틈이 없는지 확인한다고 썼는가"]},"explanation":["사다리꼴 = 정삼각형 3개, 2개면 6개만큼.","쓰는 조각에 따라 방법은 여러 가지예요.","겹치지 않고 빈틈없는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
